/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210303-3","meetingId":"r03-c-budget","date":"2021年3月3日","dateIso":"2021-03-03","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を181件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年度品川区一般会計予算","agenda":"令和３年度品川区一般会計予算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"おはようあります。私からは、９１ページ、新型コロナウイルスの予防接種事業について、全般的に何点かお伺いいたします。６名の体制で臨むというふうに聞いております。当時、しながわ活力応援給付金に関しては、多くの職員の方が、正に夜通し役所の中で働いていらっしゃったかと理解していますが、新型コロナウイルス感染症のワクチン接種に関しては、この６名の方が行っていくということなのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今のご質問の国、都、区の区分について、改めてご説明します。国は主にワクチン確保、それから財政の措置を行います。東京都が、今現在始まっておりますが、医療従事者への接種体制の構築、あと市町村事務に係る調整を行います。","voiceIndex":4,"id":"exchange-001"},{"speaker":"芹澤委員","kind":"確認","question":"会場の確保ももちろん市区町村の役割ということで、接種会場が今どういう状況なのか、実際に何会場、最終的に目指していて、今どれほど確保できているのかをお聞かせください。民間委託に関してですけれども、会場運営と、あとはいわゆる接種券みたいなものの印刷とか発送とか、そこもあわせてやるのでしょうか。確認をお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"会場からお答えをいたします。現時点で８会場の確保ができております。ご説明いたします。障害児者総合支援施設、旧荏原第四中学校、大崎第一地域センター、旧ひろまち保育園、品川区医師会館、荏原医師会館、ここまでは先日の厚生委員会のほうでご報告させていただきました。","voiceIndex":6,"id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"ウェルカムセンター原と八潮学園を含めて８会場ということでお話を伺いました。それとあと、印刷、郵送も民間に委託されるということで、これは、しながわ活力応援給付金のときも同じような形をとったのでしょうか。非常に多くの区民の個人情報を、多分渡さざるを得ないのだと思いますけれども、その情報提供の範囲もお聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"印刷業者に関しましては、住所、その辺りのこと、郵送に関するもの、それから接種券番号については、印刷業者のほうにお渡しをして、印刷をして郵送いただくという形になっております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"しながわ活力応援給付金の際は、そういった対応ではなくて、役所内で対応したということでしょうか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"しながわ活力応援給付金につきましても、委託なのですが、コールセンター、事務センター、あと、申請書の印刷、封入等も全て委託して対応したです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"接種会場について、今、何点か教えていただいて、例えば地域センターであったりとか、そもそも貸していたりとか、あと、ほかに平時に使っていたりというところはどういう調整をされていらっしゃるのかお聞かせください。大手で３社ぐらいあるかと思いますけれども、保管する温度がそれぞれ違ってきていると思うのです。どういうワクチンが来るのかはまだ恐らく決まっていないのだろうと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"それからワクチンに関しましては、現状ではファイザー製のものが先行して入ってくるというところで、ディープフリーザー等々の設置が徐々に進んでおりますが、それ以降のワクチンの流通体制に関しては現在未定です。","voiceIndex":12,"id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問・要望","question":"その場で、いわゆる解凍していくということになるのでしょうか。この会場のスケジュールです。接種のスケジュールといいますか、例えば土日、夜間とか、どういった時間帯で接種をしていくものなのでしょうか。それで、あくまでも見込みになるかと思いますが、この８会場全てをフル稼働した場合、１日何名程度の接種を予定されていらっしゃるのか、お聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"接種のスケジュールに関しましては、現在、医師会の先生方、医師と看護師等と、執務時間等について詰めておりますので、現状では時間については定まっておりません。調整中です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"芹澤委員","kind":"意見","question":"時間については了解をいたしました。もう一度ですけれども、接種会場が８会場全て整った場合に、１日何名程度、接種を行うことができるのか。あくまでも国のスケジュールなので、まず、供給がどうなるかというのはまた別問題ですけれども、品川区の役割として、会場確保をして人的体制を整えたとすれば、２月末までに終わるのかということを聞きたいと思っていますので、見込み上限数をお聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"大変失礼いたしました。１会場については、現時点では、およそ３００名程度の接種ができることを見込んでおります。ただこれは午前・午後の時間を使った状態で想定した現時点での試算です。","voiceIndex":16,"id":"exchange-007"},{"speaker":"芹澤委員","kind":"質問","question":"１会場３００名というご答弁がありました。これは８会場あって、大きさもそれぞれ違うのかと思うのですが、基本的には、前後は若干ありますけれども、ほぼ同じ３００名を目指してやっていらっしゃるということでよろしいでしょうか。その場合に、医師会が両方にかかわっていくのかと思うのですけれども、医師会とのやり取りというのはどのような形で行っていらっしゃるのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"会場は大小ありまして、医師の配置数も場所によって異なってくるかと思いますが、現時点では、１会場、１セットというか、医師２名体制で行った場合ということで想定しており、ワクチンの供給量によって、その辺りは医師会の皆様と調整をする予定です。","voiceIndex":18,"id":"exchange-008"},{"speaker":"芹澤委員","kind":"質問・要望","question":"財源について確認をさせていただきたいと思います。この予算書の中では１０分の１０というふうに書いてあって、私も報道を見る限りでは国の１０分の１０負担なのかなと思っているのですが、このコロナワクチン接種の全ての費用は国に出していただけるということでよろしいのでしょうか、お聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"委員ご指摘のとおり、現時点で、国から真に必要な費用は全て負担するというふうに示されております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"芹澤委員","kind":"確認","question":"先日の新聞報道で、この国の補助額の上限を超えてしまうところが都道府県でも幾つかあって、そうすると、国から満額もらえないのではないかというような報道があったのですけれども、品川区はそこはあまり関係ないというような認識でよろしいでしょうか。この従事者の範囲はどのように確認をしていくのか、お聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"上限額案は８億５,０００万円ということで、案の状態で、今、国からおりてまいりました。ですので、その辺りについては、報道等はあるかもしれませんが、通知がまだ正式なものが来ておりませんので、その辺りを確認しながら進めてまいりたいというふうに考えております。","voiceIndex":22,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"再度の確認です。保有台数は、一般質問でのご答弁では３７３台、昨日は東京都から追加支給で４０台あったと伺い、計４１３台と確認いたしました。それともう１点、生活困窮者支援の住居確保給付金につきまして、一般質問で、これを利用された方が、もう一度また生活困窮に陥った場合には、再度利用ができるということをしっかり周知してほしいということを要望いたしました。","respondent":"鷹箸保健予防課長、櫻木生活福祉課長","answer":"パルスオキシメーターですが、昨日お伝えした数に加えまして、今年度末までに、都から１５０台貸与されることが予定されております。合わせて年度末までに５２３台保有する予定となっております。住居確保給付金の再支給のご案内に関するご質問です。現在、周知が行き届きますように、必要なご案内をお送りするなど細やかな対応ができるよう準備を進めているところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"新妻委員","kind":"確認","question":"さらに増えて計５２３台ということで、これまで品川区では最多で自宅療養者が４０５人ということでしたので、十分な数があるということを確認させていただきました。品川区の接種方法の考え方ですが、今、６会場プラス２会場、８会場ということが確認されました。品川区の接種方法の考え方は、集団接種が基本であって、加えて、町の中の医療機関でもやっていくという、そういう考え方でよろしいのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご指摘のとおり、集団接種の会場をまず開設いたしまして、その後、病院等々での個別接種のほうに調整しながら進めていければというふうに考えております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"新妻委員","kind":"確認","question":"分かりました。特に八潮学園は学校になりますので、授業を受けながらという、平日であれば授業を受けている生徒がいて、その同じ場所で接種も行われるという、そういうイメージでよろしいのでしょうか。そのほかにも授業は進めながらやらなければいけない会場もあると思いますが、学校施設でありますので、その点だけ確認をさせてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご指摘のとおり、動線については十分に注意してまいりますので、その辺りで混乱が起きないようにしてまいります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"新妻委員","kind":"意見","question":"この情報交換といいますか、やり取りはどういう体制でされているのかということをお知らせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"国、もしくは東京都とのやり取りですが、基本的にはメールによる通知で行っております。その他、こちらのほうで問合せ事項があれば、Ｑ＆Ａという形で、メールないしは電話で直接確認をするということで対応しております。","voiceIndex":32,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。大変な負担もあるかと思いますが、どうぞよろしくお願いいたします。続きまして、母子保健衛生費に関連して、不妊治療助成についてお伺いいたします。今日、確認をさせていただきたいのが、品川区における不妊治療なのでしょうか、妊娠以降の支援というのはたくさんあると確認しているのですが、妊娠をしたいと思う方の相談場所があるのか、お伺いいたします。","respondent":"高山健康課長","answer":"妊娠を望む方に対する相談体制です。通常ですと、保健センターなどで様々な相談事の中の１つとして保健師が対応するといったケースが１つ考えられるかと思います。","voiceIndex":34,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"先日、ある機関紙で、ＮＰＯ法人男性不妊ドクターズ理事の岩本先生の寄稿を見ました。男性不妊症のテーマで寄稿されておりました。品川区においても、男性不妊治療のこういう周知をホームページなり、また健康課なりにチラシを置くなり、ぜひ進めていただきたいと思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"委員ご紹介のとおり、不妊に至る原因は双方にあるということで、女性にとかくその原因を求めがちですが、それは誤った認識ですので、そうした正しい認識が広く伝わりますよう、ホームページ、あるいは東京都などでもそうした分かりやすいパンフレットを作っておりますので。","voiceIndex":36,"id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、品川区各会計予算、同説明書１１１ページ、１４款都支出金、２目民生費補助金７節子ども家庭支援包括補助金に関連して、乳幼児健診について質問いたします。令和３年２月２４日の厚生委員会で、現在、３保健センターで行われている４ヵ月児健康診査が、現行の集団健診だけでなく、医療機関でも個別健診が受けられるようになったという報告がありました。","respondent":"柏木品川保健センター所長","answer":"今回の個別健診の経緯です。現在のコロナ禍において、保健センターで実施しております集団健診、または公共交通機関での移動等に不安をお持ちの保護者がおられます。そのような方が健診未受診とならないよう、区内の医療機関での健診の機会を提供するものであります。","voiceIndex":39,"id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"コロナ流行下、集団健診に不安を持つご父兄の要望に応え、かかりつけ医での個別健診も選択できるようにした、正に時宜にかなった適切な対応であると我が会派は高く評価いたします。４ヵ月児健康診査の内容と意義についてご説明をお願いします。","respondent":"柏木品川保健センター所長","answer":"この時点で健診を行うことにより、発育や発達面の課題等を早期に把握し、その後の健やかな成長につなげていく上で重要な時期に当たると考えております。","voiceIndex":41,"id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"確認","question":"目が合い、あやすと笑い、首が座るなど発達は順調か。授乳は順調かというような児の健康状態のチェックとともに、母子関係は安定しているか、母親に心配事はないか、母親のメンタル状態は、などの母子関係や家庭の育児環境についても確認と相談を行う大切な機会となっています。昨年の新型コロナウイルス流行第２波以降の４ヵ月児健康診査の受診者数の推移についてお示しください。","respondent":"柏木品川保健センター所長","answer":"昨年の４月、５月は、緊急事態宣言で健診が実施できなかったため、昨年６月から１月末までの状況になりますが、対象者数は２,５８１名、受診者数は２,３７７名、受診率は９２.１％になります。参考までに、昨年度の受診率は９５.８％です。","voiceIndex":43,"id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"４ヵ月児の個別健康診査を併用することにより、受診控えを防ぎ、未受診者を減らし、全ての品川区の親子とつながることが、それによって期待することができます。これは児童虐待予防のためにも大切なことと考えます。４ヵ月児健診の集団健診、個別健診の併用が始まるにあたり、区としてそのメリットとデメリットをどのように捉えられているのでしょうか。それについてのご説明をお願いします。","respondent":"柏木品川保健センター所長","answer":"デメリットとしては、医師が保護者の精神的な不調等に気がついても、保健センター等の関係機関への連絡のみとなり、要支援家庭への早期の支援につながりにくい可能性があることが挙げられます。","voiceIndex":45,"id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ご説明ありがとうございました。しかしながら、まだその連携が十分とは言えないのが現状です。今年２月４日に行われた品川区４ヵ月児健康診査個別健診実施説明会でも、現在の保健センターで行われている、その支援の体制あるいは具体的な集団健診の内容についてのご説明がもう少し詳しくあればよかったと参加者として思いました。区のご意見、ご見解はいかがでしょうか。","respondent":"柏木品川保健センター所長","answer":"医療機関との連携です。区といたしましても、今回の個別健診を機に、医療機関と保健センターの連携を強化し、ほかの６ヵ月児健診、９ヵ月児健診等においても、要支援家庭への早期の支援につなげられるようにしたいと考えております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"意見","question":"品川区民の健康と、それから子育て支援、育児支援、いろいろな支援に対して、いろいろな組織が協力して対応するということは非常に大切なことだと考えます。今後も区民の健康と子育て支援が十分、ハイレベルで行われる、それぞれのメリットを生かして行えるように、区としても、今後、ご配慮、ご推進をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"９１ページの国庫負担金、新型コロナウイルスワクチン接種負担金、９７ページの国庫補助金、新型コロナウイルスワクチン接種体制確保事業費補助金について伺いたいと思います。２０２０年度分は、２月１日、もう既に締切りとなりましたけれども、申請者数が何人か、学習塾、受験料、高校、大学、それぞれ伺いたいと思います。何％ぐらいが免除になっているのかについても伺います。","respondent":"櫻木生活福祉課長","answer":"受験生チャレンジ支援貸付事業です。令和２年度の状況につきましては現在集計中ということで、令和元年度の実績を申し上げますと、貸付件数が１６６件、そのうち免除になったのが１５２件ということで、９１.６％の免除率です。","voiceIndex":51,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１６６件というのは、学習塾も受験料も、両方とも貸付を受けているということでよろしいのでしょうか。その点はあとでお願いします。それであれば、この受験生チャレンジ支援貸付事業も、必要な証明書が無料で取れるようにぜひしていただきたいと思うのですが、いかがでしょうか。この手続も、申請書はネットで取ることができ、郵送できるようにならないでしょうかという、この２点をお願いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"ただし、最初の借入申込書以外のところにつきましては、郵送でのやり取りが、状況によっては対応できるです。","voiceIndex":53,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区としてということで、もう１回答弁をお願いします。なので、そのことで窓口に来なければならないというふうにはならないのではないかと思うのですけれども、どうでしょうか。それから、もしどうしても役所に来なければならないというのであれば、休みを取って来なくても済むように、休日や夜間の開庁時に手続ができるようにということにはならないでしょうか。いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"それと、窓口にお越しいただくことについて、金額の多寡というよりは、お金を借りる、受験費用を借りるということをしっかりとご認識いただくということと、制度説明をしっかりするという意味で、一度はご来所いただいているです。","voiceIndex":55,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"休日や夜間とかに対応ができないかということで、最低でも１回だけということで、それ以外のところは郵送でも大丈夫だということで確認させていただきたいと思います。額も幾つもの区が１０万円にしておりますので、ぜひ対象と慰労金の額について拡充をしていただきたいと思うのですが、いかがでしょうか。そういう形で臨時交付金は、苦境に立たされている区民のために活用していただきたいと求めます。","respondent":"高山健康課長","answer":"こちらに関しましては、国の慰労金に加えまして、区独自で設定したものでございまして、直接のコロナ対応に従事された方ということで、その対象を絞って予算を計上させていただきましたが、その配分に関しましては、病院の対応方針などに任せておりますので。","voiceIndex":57,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"コロナウイルスのワクチンについて伺いたいと思います。予防接種実施計画なのですけれども、この計画や要領を作成するというのが新型コロナウイルス感染症に係る予防接種の実施に関する手引きにも書かれているのですけれども、今まさに作成しているところということなのですが、これは計画の実施期間が２月１７日からというふうになっているのですが、ここまでに作るものではないのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"２月１７日というのは医療従事者のことでございまして、東京都が中心になってやっていくということで、その辺りも含めて、ワクチンの供給量が見えたところで、ある程度完成ができるかというふうに見込んでおります。","voiceIndex":61,"id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"初めに、９７ページのコロナワクチンについて伺いますが、ドクターと看護師の確保というのは大切な１つの要素ですが、ドクターの数も看護師の数も決まっている中において、コロナのワクチン以外に通常の医療もあるわけですよね。必ずできるのですか。それと、次が１３９ページの、この品川区役所庁舎の下の駐車場には、いわゆる今、民間企業が入っていますが、どういう形でお金は入ってくるのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、濱中庁舎計画担当課長、三ッ橋子育て応援課長、東野経理課長、森住宅課長","answer":"滞りなく進めることができるようにしてまいります。新庁舎につきまして、国との負担金がどういった形になっているかですが、今後、基本構想、基本計画等で、新庁舎の規模等が検討されていきまして。全国ひとり親世帯等調査ですけれども、５年に１回の調査でして、こちらは調査の歳入・歳出に関しましては、調査旅費、また事務費です。契約としましては、タイムズ２４株式会社との契約になっておりまして、この契約金額を超えた分につきましては事業者の運営費になります。","voiceIndex":64,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"注視ではなくて、どういう具体的にというのをお答えください。やろうと思えばできるという証明だと思うのですけれども、その辺についてもう１回お伺いします。ただ、ＰＣＲ検査センターでスペースを取っていますので、その辺はどうなったのか、お伺いします。それと、区民住宅、６３０戸のうち５７８戸ということは、５２戸空いているのですが、５２戸掛ける家賃だと、年間どのぐらいになるか教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、三ッ橋子育て応援課長、東野経理課長、森住宅課長","answer":"加えて、医師会の先生方以外の健診センターとか、その辺りの先生方、看護師にも、今。効果はあると考えております。そのため、昨年８月からなのですけれども、月約４５万円ほど減額いたしまして、現在継続しています。大体家賃の平均として１４万円から１５万円程度ということになりますので、単純に計算しますと９,０００万円余が年間の使用料になります。","voiceIndex":70,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"入ってくるのですから、ここをどうにかしてもらいたいと思うので、課題としてよろしくお願いいたします。次が、４９ページ、特別区民税というか、歳入全般という意味でお伺いしたいのです。企画調整課、全体を考えているということでぜひ教えていただきたいのですけれども、まず、企画調整課で調整していくためには、いわゆる少子高齢化と言われていますが、これはまず何が一番問題があるのでしょうか。","respondent":"佐藤企画調整課長","answer":"３点目の国民全体の借金がかなりあるというところは、当然承知をしているところでございまして、区民に身近な基礎自治体として、まずは区といたしまして、新しい長期基本計画をきっちりと進めていくというところで一生懸命頑張っていきたいと考えております。","voiceIndex":75,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、国のことだからと思わないでいただきたいのです。企画調整していく上で、やっぱり国全体を見ていくというのは、私は大事だと思って今質問させていただいています。もっと言うならば、なぜ日本の長期国債がこのように金利が安いのか。生産をしてくださる年齢層の方が介護離職するという状態をつくらないための施策をしていっていただきたいと考えていますが、その辺についてはいかがでしょうか。","respondent":"佐藤企画調整課長","answer":"品川区から一度転出されて戻ってきた方の６割が、以前、品川区に住んでたという調査結果もありますので、それくらい品川区のポテンシャルが高いというふうに理解をしております。委員ご案内の介護離職の件に関しましても、区として対応してまいります。","voiceIndex":77,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"順不同ですが、最初に新型コロナウイルスワクチン接種のことです。皆さんのご質問で、大分いろいろなことが分かってきたのですけれども、私からは委託の契約内容について伺いたいというふうに思います。それから、昨日、３社の中から選んで随契というふうに伺ったと思うのですが、どういうふうに優位性を認めてここを選ばれたのかについても伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今回選びましたＪＴＢに関しましては、２３区の中で全部で１０の区と契約を結ぶというところもあり、情報も含めて連携がとれるということと、Ｇｏ Ｔｏ トラベル等々で、そういった郵送とか。","voiceIndex":80,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"委託事業者の選び方ですけれども、今はまだどこの区も進んでいない中で、ほかの今までの実績の中から選ばれたということだと思うのですけれども、これはぜひうまくやってほしいという要望にしておきます。次に、生活保護についてです。多いのではないでしょうかということで、この人数を担当していて十分なアウトリーチができているのか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"あわせて、人員増につきましては、区全体の人員配置の中から決まるものと考えておりますが、生活福祉課としましても、事務の効率化、集中化、ＩＴ化等を通して、ケースワーカーの対人援助業務の余力を創出するような取組を進めてまいりたいと考えています。","voiceIndex":82,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"ケースワーカーの人数です。次に、保育対策総合支援事業費補助金から、区内私立保育園開設経費について伺います。１０月の決算特別委員会では、保育の質の確保のために、東京都が補助金の要件としている財務情報の点検を求めて質問しました。今回は、そもそも保育園の開設事業者をどういう視点で選んでいるのか、伺いたいと思います。保育園運営の事業計画などの提出は求めているのか伺いたいと思います。","respondent":"若生保育支援課長","answer":"基本的に私立保育園開設時に関しましては、開設希望があった事業者から具体的なご提案等をいただきまして、区のほうでヒアリングを行いながら、事業者の保育に対する考え方ですとか財務状況等から適格性を見極め、問題がない場合。","voiceIndex":84,"id":"exchange-034"},{"speaker":"吉田委員","kind":"提案","question":"こういう事業者を保育園事業者として適切と考えるか伺いたいと思います。私の理解が及ぶ範囲では、どうしても配当は賃料補助として支払われる補助金から生み出されるとしか思えないのです。基本的にもうかる事業ではなくて、もうかる事業ではないから補助金が出ているのに、あたかも安定した事業とうたっているということに、とても違和感があるのですが、お考えを伺いたいと思います。","respondent":"若生保育支援課長","answer":"２点ほどご質問いただきました。１点目、事業者の保育事業計画で財務状況等の確認というところですけれども、これは新規でご提案があった場合は、区のほうで経営分析を必ず実施しております。","voiceIndex":86,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"３０％ぐらいです。保育園を増やす必要もあると思いますが、事業者を選ぶにあたっては、保育園運営の事業計画もよく確認していただきたいのと、やはり運営されているところについては、財務情報の点検を再度強く求めたいと思います。今日はこれはここまでにしておきます。次に、地域自殺対策強化交付金について伺います。相談手段の多様化については、いかがでしょうか。伺います。","respondent":"鷹箸保健予防課長","answer":"とにかくここにということでは、区で直接、特に２４時間の対応という部分はかなり難しい部分もありますので、そこはＮＰＯと連携し、東京都が実施しております「こころの健康相談」の窓口などにアクセスしやすいよう、情報提供を現在も進めておりますし。","voiceIndex":88,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"課長もきっとご存じだと思うのですけれども、秋田モデル、秋田のほうで自殺率を低下させたというようなネットワークの組み方もぜひ視野に入れていただきたいと思います。３年間の障害児者計画について、何か意欲が見えない、ロードマップが見えなかったので、この３年間にかける地域生活支援事業について、決意ぐらいで今日はいいですけれども、ぜひお示しください。","respondent":"松山障害者福祉課長","answer":"計画についての見込み数についてお答えいたします。地域生活支援事業は地域に応じまして積極的に今後も実施してまいりたいと考えています。","voiceIndex":90,"id":"exchange-037"},{"speaker":"松本委員","kind":"質問","question":"今日は、９１ページ、新型コロナウイルスワクチン接種負担金、９７ページ、新型コロナウイルスワクチン接種体制確保事業費補助金、１３９ページ、品川音頭の著作権料、また関連して、区の知的財産について、時間が間に合えば、１５７ページ、雑入について伺います。この上限額、負担金と補助金、どちらも上限があるのか、まず、この上限の考え方をお伺いできればと思います。お願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"補助金のほうは、運営費とか、その辺りのものが、もともと示された金額では足らないだろうというところから国から示されたこともあり、上限額が変更されて、上限額案ということで、先ほどご説明させていただいたとおりです。","voiceIndex":93,"id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"その中で示されている上限が、各項目ごとの上限なのか、それとも需用費とかも含めて、旅費とか謝金とかいろいろなものがあるのですけれども、ざっくりまとめて上限が示されているのでしょうか。どちらになるのでしょうか。お願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今のご質問です。こちらで把握しているのは上限額の８億５,０００万円という先ほどのもののみで、内訳については特に示されておりません。","voiceIndex":95,"id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"品川区の場合は既存の施設を使うということなのですけれども、今後、いろいろ状況が変わったときのことに備えてお伺いしたいのですけれども、こういった新たな施設をつくる場合は、今回の対象経費の中に、例えば、工事請負費とかに入ってくるのかどうなのか、この辺りの考え方をお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今のご質問も、真に必要な経費ということで含まれるということでＱ＆Ａのほうに示されておりました。","voiceIndex":97,"id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"一方で、例えば埼玉県の宮代町のほうでは、これは多分、促進策だと思うのですけれども、ワクチンを接種した人に町で使える商品券を配布すると。あるいは横須賀市では、割引サービスみたいな感じで、いろいろと奨励策が各自治体で独自で今いろいろと挙げられつつあります。逆にこれは、この補助金の対象には入らないというふうな理解でよろしいのでしょうか。お願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現時点で把握しているところでは含まれないというふうにこちらは理解をしております。","voiceIndex":99,"id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"品川音頭の著作権料について伺っていきたいのですけれども、これ、予算額を拝見すると、使用料で１万円と極めて少額が計上されています。どういった使用を想定しているのか、あるいは、過去どういった使用がなされたのか。お願いいたします。","respondent":"大澤広報広聴課長","answer":"令和２年度は、現在のところ、ラジオ等で使われて５,０００円少しということで、かなり年度によって差がありますので、令和３年度は１万円ということで計上しているものです。","voiceIndex":101,"id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"当区も「ハタチの龍馬」とか、品川区３競技応援キャラクターとか、キャラクターも存在しているところだと思います。３競技応援キャラクターについては、過去の議事録を拝見すると、商標登録はされているというふうになっているかと思うのです。この辺りのキャラクターとか、あるいは今の品川音頭の著作権とかの知的財産の管理体制は、区全体としてはどういうふうになっているのでしょうか。","respondent":"中山会計管理者","answer":"知的財産の管理体制ということですが、そのほかに商標登録ですとかロゴの登録とかもあわせまして、一応無形資産ということで会計管理室のほうで管理しているものです。","voiceIndex":103,"id":"exchange-043"},{"speaker":"松本委員","kind":"提案","question":"その結果、すごいことに２０２０年、関連売上が１,６９８億円ということで、実際に直接入るお金ではないのですけれども、そういった形で地域振興に役立てている。例えば、３競技応援キャラクターがありますけれども、これを区内の商店が自分のところの商品で使いたいのだというふうに言った場合に、今、どういうふうな扱いになっているのか、お尋ねしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"３競技応援キャラクターの取扱いについてです。使用したい団体や企業等がございましたときには、届出だけしていただいて、特に使用料等はいただいていないというところです。ぜひたくさん使っていただきたいと思っているところです。","voiceIndex":105,"id":"exchange-044"},{"speaker":"塚本委員","kind":"確認","question":"７７ページ、７９ページの住民票とか印鑑証明等のコンビニ交付についてに関わる手続について伺いたいと思います。昨日、報道でもタブレットを国のほうから４万１,０００台ぐらい配りますということでしたけれども、品川区として、１点目にお伺いしたいのは、バーコードとかＯＣＲの形で接種券から自動で読み取るみたいなものに対応ができているのですかというところの確認が１点目です。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後また調整が入るかもしれませんが、情報をこちらから取りにいって、十分過不足ないようにしていきたいというふうに考えております。","voiceIndex":109,"id":"exchange-045"},{"speaker":"塚本委員","kind":"意見","question":"そのときに、１回の入力で済ませられるのか。場合によっては、国がアクセスできるデータであって、それはちょっと使えないので、品川区は品川区で接種結果をまた二重に登録しなければいけないみたいなことがあっては、いかがなものかというふうに思うので、そういったところの懸念についての現状を、答えられる範囲でお願いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"国のシステムから情報を取り出すことはできるようだということで聞いております。ただ、こちらのほうで区のシステムで予約管理をするか、国の予約システムで管理をするか、その辺りも、現在、調整して詰めて、効率がよい方法を考えていければというふうに考えております。","voiceIndex":111,"id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。次に、住民票とか印鑑証明、課税納税証明のコンビニ交付についてなのですけれども、予算を見ると、全体の交付のうちコンビニ交付は、１０％はいかない状況かと思います。もう１点は、戸籍証明については、今年の１月か、コンビニ交付が始まっていると思うのですけれども、これが今年度の予算にはコンビニ交付の予算が載っていなかったのですが、それがなぜかという２点をお伺いします。","respondent":"山本情報推進課長、木村戸籍住民課長","answer":"引き続き周知等も図りながらコンビニ交付を伸ばしていきたいというふうに考えているところです。戸籍証明に関するコンビニ交付の経費が載っていないですけれども、こちらについては、申し訳ございません、漏れでございまして、実際に今年の１月からスタートをしておりまして、実際にもう交付を始めておるところでございまして。","voiceIndex":113,"id":"exchange-047"},{"speaker":"塚本委員","kind":"意見","question":"それで、戸籍住民課の３階の窓口とかを見ていると、本当に人で混雑しているのが結構目について、こういう状況を見たときに、こういったコンビニ交付というか、マイナンバーカードが普及するに伴って、技術的には、マイナポータルというもので自宅でキャッシュレスで決済すれば印刷できてしまうよねというのは時々聞く声ですけれども、こういったことに対しての区のお考え、あまり時間がないので。","respondent":"山本情報推進課長","answer":"自宅等からマイナポータルを使ってということになりますと、一部インターネット等を使うことになりますので、その辺がセキュリティ上の問題が少しあるのかなというふうに考えているところです。","voiceIndex":116,"id":"exchange-048"},{"speaker":"せお委員","kind":"質問・要望","question":"８９ページ、入院助産費、１１３ページ、放課後子ども教室等補助金、お時間ありましたら、１０１ページ、公園・児童遊園整備費をお伺いします。初めに入院助産費です。こちらは児童福祉法に基づくものですので、対象となる方には確実に提供していただきたいのですが、入院助産の周知方法に関しては、現在どのように行っているのかお聞かせください。","respondent":"三ッ橋子育て応援課長","answer":"入院助産の実績値です。平成３０年度は５件、平成３１年度（令和元年度）は７件、令和２年度は２件となっております。周知方法です。","voiceIndex":120,"id":"exchange-049"},{"speaker":"せお委員","kind":"提案","question":"母子手帳をお渡しするときなどの早期の段階の情報提供のほうが継続した適切な支援につながりますので、周知方法にはその時期も検討していただきたいと要望します。先ほどの入院助産の対象の方に限らず、出産育児一時金の４２万円を引いた２０万円以上の金額を出産の際に自費で出すというのは、一般的に考えても大変なことなのではないでしょうか。私からも改めて要望いたします。","respondent":"三ッ橋子育て応援課長","answer":"様々近隣区が実施している出産育児一時金の上乗せ事業ですが、区は、代表質問でもお答えいたしましたように、東京都などの動向を踏まえ、また、近隣区の状況も踏まえながら、区として研究してまいります。","voiceIndex":122,"id":"exchange-050"},{"speaker":"せお委員","kind":"質問・要望","question":"そういった視点で、衛生費でも質問する予定ですが、予算の使い道はこのようなところにあるのではないかと考えていて、国や都のスタンスとは違った、痒いところに手が届く心通じ合える支援をぜひ品川区が行っていただきたいと思います。お忙しい中ありがとうございました。次に、放課後子ども教室です。予算見積書の中の運営費に、この特別支援に関する補助金は含まれていますでしょうか。お聞かせください。","respondent":"廣田子ども育成課長","answer":"こちらの補助金については、区は委託料の中でまかなっている関係で、申請をしておりません。","voiceIndex":124,"id":"exchange-051"},{"speaker":"せお委員","kind":"質問・要望","question":"昨年の第４回定例会の一般質問で取り上げましたが、すまいるスクールは品川区の全児童放課後等対策事業としていて、さらには第二期品川区子ども・子育て支援事業計画には、令和２年度から令和６年度までの計画ですが、そちらにおいては、「希望するすべての児童が」と書かれています。は４年生以降の受入れの拡大も検討していただきたいのですが、見解をお聞かせください。","respondent":"廣田子ども育成課長","answer":"今後どうできるかというところはあるのですけれども、今現在は、今いるお子さんたちに関しても、どうしていくかというところが課題となっておりますので、その検討の中で考えていこうと思っています。","voiceIndex":126,"id":"exchange-052"},{"speaker":"せお委員","kind":"質問・要望","question":"このような考え方を取り入れていただいて、品川区の子育て支援が充実した心温まるものとなるよう要望します。最後に、１点だけ公園のところです。公園・児童遊園整備費の事項別の説明では、北品川公園と、大井坂下公園の公園施設長寿命化とあります。そこで、北品川公園と大井坂下公園の改修においては、なぜ国庫補助金である防災・安全交付金の対象となるのか教えてください。","respondent":"高梨公園課長","answer":"補助金を入れている、入れていないの違いですが、基本的には、要件に合致するものについては積極的に申請をしていきたい、このように考えておるところですが、東京都と国と調整する中で。","voiceIndex":128,"id":"exchange-053"},{"speaker":"せお委員","kind":"質問","question":"続きは土木費でお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-054"},{"speaker":"こんの委員","kind":"確認","question":"私からは、９１ページ、個人番号カード交付事業、９７ページ、母子保健衛生費、１１５ページ、高齢者社会参加促進事業をお聞きしたいと思います。順不同でお聞きいたします。母子保健衛生費に関連して、大きく２つお聞きしたいと思います。１つは、産前産後のサポート事業、もう１つは、妊婦健康診査についてお聞きしたいと思います。その点、まず確認させてください。","respondent":"柏木品川保健センター所長","answer":"その中で父親のほうからの質問、あと、父親に対して、妊娠または出産後の内容、またはご相談については、そういう場を通じて、今、実施しています。","voiceIndex":132,"id":"exchange-055"},{"speaker":"こんの委員","kind":"質問","question":"両親学級が、今、新型コロナウイルス感染症の関係で父親学級としてくださっていると。大変にありがとうあります。それと同時に、ネウボラ相談の中では、両親の方が相談に来られているケースを今伺いました。私はこうした補助金も活用して、産前産後における父親同士、父親に特化した、そうした相談する、交流を持つ、こうした支援が必要ではないかと考えるわけですけれども、いかがでしょうか。","respondent":"柏木品川保健センター所長","answer":"父親に特化したというところで、先ほどご答弁させていただきました、現在、父親学級という形で実施をしておりまして、その中で区の補助事業と類似する内容が多く含まれてあります。","voiceIndex":134,"id":"exchange-056"},{"speaker":"こんの委員","kind":"質問","question":"今お答えくださったところは、新型コロナウイルス感染症の関係で今だけなのかと理解をしてしまったので、国の予算も使って今後どうですかということを言いましたけれども、これからも新型コロナウイルス感染症に関係なく、そういう状況は品川区として体制を組むのであれば、それはそれでお願いしたいというふうに思います。多胎妊娠の場合に対して、区としては何か対応していることはあるのでしょうか。","respondent":"高山健康課長","answer":"妊婦健康診査の回数という点で申しますと、２３週までには４週間に１回でありますとか、２４週から３５週にかけては２週間に１回、その後は、３６週以降は１週間に１回というようなことで、おおむねの積み上げの数字が出てまいりませんが、その中での１４回ということで。","voiceIndex":136,"id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"おおむねの回数を伺ったところですが、相談なども合わせてどれぐらいなのか、お分かりになれば、お答えいただきたいと思います。現在、１４回の妊婦健診に対する費用助成、今お答えいただいた公費助成があるわけですけれども、多胎妊娠の場合の追加の受診、こうした費用に対しての一定額の助成、こうしたことも必要ではないかと考えますが、この点は今どのような状況でしょうか。","respondent":"高山健康課長","answer":"そうした意味では、２３区共同して、あるいは東京都と歩調を合わせて、できるだけそういった償還払いのような保護者の方の負担が少なくて済むような仕組みをやはり構築する必要があるかと思いますので、そちらのほうは、また引き続いて。","voiceIndex":138,"id":"exchange-058"},{"speaker":"こんの委員","kind":"提案","question":"そこでちょっとご案内ですけれども、やはり国の来年度の予算で、多胎妊娠を対象に、単胎妊娠よりも追加で受診する妊婦健康診査にかかる費用を補助する市区町村に対して、経費の２分の１を補助するという新規事業を国は始めます。ぜひこうした国の事業を区独自で活用して、そうした方への費用負担軽減策を創出していただきたい、そのように提案するわけですけれども、いかがでしょうか。","respondent":"高山健康課長","answer":"委員ご提案の仕組みを品川区独自で構築するということになりますと、既に２３区の中でも１つの区がそのような仕組みをとっている区もございまして、申請手続などを拝見しますと、やはりいろいろ、かかる費用を証明するような書類を個別にご用意いただくとかということで。","voiceIndex":140,"id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"繰り返しになりますが、今ご答弁いただいた考え方もあるのだろうということですが、ぜひ区民の、本当にコロナ禍の中で出産をする、新型コロナウイルス感染症がいつ終息するのか分からない、こうした中での出産、安心・安全に出産ができる体制をという考え方をぜひ持っていただきたい、このように思います。次にまいります。そこにはスマホ教室も含まれておりますが、これは新規事業なのでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"私からは、高齢者社会参加促進事業のうちのスマホ教室が新規事業かどうかということのご質問にお答えします。こちらは令和３年度の新規事業ということで、高齢者の方が安心してスマホを利活用できるようにということで考えております。","voiceIndex":142,"id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうした方々への、いわゆるスマホ、インターネットが使える、こうしたものへの一歩踏み出す支援というのでしょうか、そうしたところも、このスマホ教室で行えたらなと、このようなことを考えるわけなのですが、例えばスマホを実際に使っていらっしゃる高齢者の方から、スマホの選び方とか、あるいは携帯電話業者へ行くときの心構えだとか、店員とのやり取りだとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-061"},{"speaker":"木村委員","kind":"質問","question":"私からは、４９ページの一番上の特別区税からの質問です。この特別区税がマイナス１８億２,８００万円余と大きくなっていますけれども、品川区の人口は、ピーク時より２,０００人ほど減っているということをお聞きいたしました。人口減少も影響していると思いますけれども、区税とは、所得税や住民税のことでしょうか。お聞かせください。","respondent":"伊東税務課長","answer":"区税と特別区税というくくりですけれども、その中には特別区民税、軽自動車税、そして特別区たばこ税、これが入っておりまして、その総称として特別区税と申しているものです。","voiceIndex":146,"id":"exchange-062"},{"speaker":"木村委員","kind":"質問・要望","question":"人口が減っているからということで、やっぱりかなりのダメージがあろうかと思いますけれども、頑張っていただきたいと思います。下から２行目にあります、１９款諸収入は前年比５億１,８００万円余の伸びですけれども、この諸収入とはどのような種類で、売上はもちろん伸びたのでしょうけれども、これの種類というものを教えていただきたいと思います。","respondent":"品川財政課長","answer":"前年度との比較で５億円程度上がっているというところですけれども、こちらの排水工事関係の受託収入が昨年度よりも上がっているというところで、大きく伸びているです。","voiceIndex":148,"id":"exchange-063"},{"speaker":"木村委員","kind":"質問","question":"いろいろなものがあろうかということであります。次に、同じページの一番下でありますけれども、歳入合計ですが、前年度に比べて５８億４,５００万円の減額を見込んでいますけれども、やはり新型コロナウイルス感染症以外に減額の大きな要因というものが何かあるのでしょうか。お聞かせください。","respondent":"品川財政課長","answer":"こちらのところは、先ほど税務課長からも少しお話があったかと思いますけれども、納税義務者等の減少と、いわゆる区民所得が、令和２年度、非常に落ちていると想定されます。そういったところでの住民税額の減というところを見込んでおります。","voiceIndex":150,"id":"exchange-064"},{"speaker":"木村委員","kind":"質問","question":"５２ページの一番上の特別区たばこ税、前年比８００万円の減の見込みになりましたけれども、原因はどのようなことが考えられるか。区内でのたばこ店や販売機が大分減っているということも前にお聞きしたことがあったのですが、そして、灰皿の撤去なども大きな要因になっているのか、お聞かせください。","respondent":"伊東税務課長","answer":"たばこの売上げ本数が減っているという点ですけれども、この間、やはり健康志向の高まりですとか、あとは外的に、喫煙できる環境が減少しているというような状況、吸いにくいような状況になっているということ、あとは単価的に、この間、値上げとかもされてきていまして。","voiceIndex":152,"id":"exchange-065"},{"speaker":"木村委員","kind":"質問","question":"本区には約３０億円もの税収が入ってくるわけであります。何となく複雑な気持ちですが、この３０億円の使い道は、以前にもお尋ねしましたが、これといった使い道は決まっていないということで明らかにしてくれませんでした。過去にはどのようなことに使われてきたのでしょうか。差し支えない程度でお聞かせいただければと思います。","respondent":"品川財政課長","answer":"一例と申し上げますとなかなか難しいところもあるのですが、これまでの区の事業の中で、特別区たばこ税の収入を使って様々な点で事業に活用させていただいていると、このような状況です。","voiceIndex":154,"id":"exchange-066"},{"speaker":"木村委員","kind":"質問","question":"なかなかこれといったことは示せないのかもしれませんが、私は喫煙をしませんけれども、１箱でも多くのたばこが区内で売れることを願うものであります。本区の特別区たばこ税の歳入は将来的に現在より減っていくのか。どのように推移をしていくのかというものが、何となくたばこを吸わない目で見ていても気になるところでありますけれども、ここのところを、どのようなお考えでしょうか。","respondent":"伊東税務課長","answer":"ですので、今後、売渡し本数に関してはもうしばらく減る傾向は続くのかと考えていますけれども、その後の税率の改正等々があれば、また盛り返すというような状況で、３０億円は何とか死守していきたいというふうに思っているところです。","voiceIndex":156,"id":"exchange-067"},{"speaker":"木村委員","kind":"質問","question":"たばこの売上げだけではなく全てに影響が出てくることも考えられます。少しでもワクチンへの希望を持ち、我々にも以前のような生活が返ってくると思いお聞きいたしますけれども、たばこの売上げアップや、ワクチンも含めた全てのことに対して、区のお考えを最後にお聞かせください。","respondent":"品川財政課長","answer":"これがどういう方向に動くかというところはまだ見えないところはありますが、いい方向に向いてくれれば歳入のほうもまた変わってくるのではないかと思いますので、それに応じて、また適切に区としては事業を進めていきたいと、このように思っております。","voiceIndex":158,"id":"exchange-068"},{"speaker":"小芝委員","kind":"質問・要望","question":"私からは、１０７ページの生活保護の件でお聞きします。午前中にも質問がございましたので、二重の答弁をいただかないよう質問させていただきたいと思います。昨年１年は、コロナ禍によりまして生活が苦しくなり、厚生労働省の統計によれば、生活保護受給を申請する方が増えたと聞きます。その前の年、前年同月比でどのくらいのパーセンテージだったのか教えてください。","respondent":"櫻木生活福祉課長","answer":"令和元年度で最も申請件数の多かった月ですと、令和２年３月が４８件という形で一番多い数字になります。前年同月比ということですと、まだ３月が来ておりませんのでお答えしかねるところではありますが、平均的には１０％程度増えているかです。","voiceIndex":161,"id":"exchange-069"},{"speaker":"小芝委員","kind":"質問","question":"昨年４月からの緊急事態宣言による、例えば非正規職員の雇い止めなど、失業された方がすぐに生活保護の受給を申請されたわけではないと考えておりますが、区のほうで生活保護の相談に来られた方には、どういった対応をされてきたのでしょうか。教えてください。","respondent":"櫻木生活福祉課長","answer":"基本的に生活保護のご相談に来られた方に関しましては、ご事情をよくお伺いしまして、生活保護の要件に当てはまる方には速やかに申請の手続をご案内するということになっておりまして、生活保護にまで至らないという方々に対しましては、暮らし・しごと応援センターのほうで。","voiceIndex":163,"id":"exchange-070"},{"speaker":"小芝委員","kind":"質問","question":"そのほかにも例えば社会福祉協議会への案内とかもされていたのでしょうか。","respondent":"櫻木生活福祉課長","answer":"暮らし・しごと応援センターの中で、社会福祉協議会の、特に緊急小口資金であったり、総合支援資金等のご案内も丁寧にしています。","voiceIndex":165,"id":"exchange-071"},{"speaker":"小芝委員","kind":"質問","question":"生活福祉課のほうから社会福祉協議会への紹介の割合というのは、例えばその１か月で相談に来られた方のうち、大体どのくらいの割合であったのか、教えていただければと思います。","respondent":"櫻木生活福祉課長","answer":"すみません、ちょっと割合という意味ですと数字はございませんが、基本的に暮らし・しごと応援センターに来られる方のほとんどが住居確保給付金の申請ということでございまして、その時点で一定の困窮度合いであるですので。","voiceIndex":167,"id":"exchange-072"},{"speaker":"小芝委員","kind":"確認","question":"緊急小口資金や、またそのほか総合支援資金といったものが、コロナ禍ではセーフティネットの１つとして大きな役割を果たしてきたのかなという認識をしております。一方で、生活保護を受ける側ではなく、そういった方々を支える役割を担っていますケースワーカーについてお聞きいたします。確認ですが、品川区のケースワーカーの方は、今現在、何名いらっしゃるのでしょうか。","respondent":"櫻木生活福祉課長","answer":"２月１日時点の数字ですが、４４名です。","voiceIndex":169,"id":"exchange-073"},{"speaker":"小芝委員","kind":"質問","question":"ケースワーカーというのは、午前中の質疑を聞く限り、例えば、大学などで社会福祉主事の任用資格を持っていなくとも任用されるという認識を持っておりましたが、行政職の方でも人事異動でケースワーカーになるという認識で合っていますでしょうか。","respondent":"櫻木生活福祉課長","answer":"委員ご指摘のとおり、福祉職以外に、いわゆる事務職の職員もケースワーカーとして携わっております。","voiceIndex":171,"id":"exchange-074"},{"speaker":"小芝委員","kind":"質問・要望","question":"新聞報道によりますと、社会福祉法というのは都市部では生活保護世帯８０に対してケースワーカー１人の配置を標準数として定めております。社会福祉法の求める数はあくまで標準数なので、マストではないのかもしれませんが、人事異動を検討する際に、例えば、あらかじめケースワーカーの数を法定の標準数８０世帯に近い枠で設定することもできそうに思いますが、いかがでしょうか。","respondent":"黒田人事課長","answer":"職員数ですが、職員の総数については条例で上限を定めている関係がございまして、その中で全体的にどのような部門に何人配置できるかというところは、毎年、所要人員調査をしていますので、そういった中で、人員配置については。","voiceIndex":173,"id":"exchange-075"},{"speaker":"小芝委員","kind":"質問","question":"確かに午前中の質疑では高齢の受給者世帯に会計年度任用職員を活用しているとのお話を伺っておりましたが、例えば２年前にケースワーカーが担当の受給者から日頃から脅迫を受け、結果として事件に加担したという痛ましいニュースがございました。現在の会計年度任用職員の採用に際して、どのような基準があるのか教えてもらえますでしょうか。","respondent":"櫻木生活福祉課長","answer":"会計年度任用職員でケースワークに携わっている高齢者世帯自立支援員という名前がついておりますが、その方々には、社会福祉の豊富な経験もしくは高度な専門性を持った方という要件がありますので、それに沿って採用を行っているです。","voiceIndex":175,"id":"exchange-076"},{"speaker":"小芝委員","kind":"意見","question":"その経験豊富な方も会計年度任用職員として登用して、最初は１０３世帯とおっしゃっていましたけれども、たしか、こういった会計年度任用職員の方も含めると９０世帯弱ということで、この法定の標準数８０世帯になるべく近づくように取り組んでおられることは認識しておりますので、今後ともこの標準数に近い数に近づくよう、また、これが生活保護の適正化にも資すると考えますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":177,"id":"exchange-077"},{"speaker":"横山委員","kind":"質問","question":"私からは、９３ページ、子ども・子育て支援体制整備総合推進事業費、９５ページ、子ども・子育て支援事業費補助金、１３７ページ、教職員研修についてお伺いいたします。１点目に教職員研修についてお伺いいたします。一般質問でもお伺いいたしましたが、児童虐待に関する学校と教育委員会の取組について詳細をお聞きします。児童虐待対応に関する研修の対象と頻度について具体的に教えてください。","respondent":"矢部教育総合支援センター長","answer":"管理職については、校長および副校長を管理職と呼びます。管理職同士の情報連携もとても大切ですので、今後、研修方法の検討とともに理解を進めてまいります。","voiceIndex":179,"id":"exchange-078"},{"speaker":"横山委員","kind":"質問・要望","question":"どう実感を送ることができるか。３０代になって、やっと自分なりの生活を取り戻してきた方々のアンケートの結果として、自分を精神的に支える人に求めるものとして、以下の５つの共通点があるとのお話がありました。４、時熟、待つことができる人。現状把握、進捗の確認、必要な園に関しては適宜サポートを実施していただきたいと思いますが、確認の頻度とチェック方法について、ご説明をお願いいたします。","respondent":"立木保育課長","answer":"保育の研修の件についてですが、まず、インセンティブの部分に関してですけれども、虐待対応ですとか、あと研修の中身につきましては、これは必ずやっていただきたいというところがありますので、インセンティブというよりは。","voiceIndex":181,"id":"exchange-079"},{"speaker":"横山委員","kind":"質問・要望","question":"情報発信の工夫をぜひお願いしたいと思います。研修につきましては、確認できました。「心とはなんですか」、「信頼って何」、「愛するとはどういうことですか」など、心、信頼、愛という漠然としていて個人によって解釈が異なる言葉について事前に共有化を図っています。言葉の意味を共有し、関係機関で認識のずれが起きないように運用していただきたいと思いますが、区のお考えをお聞かせください。","respondent":"崎村子ども家庭支援センター長","answer":"ご指摘のとおりマニュアルを作成、配布して終わりではなくて、マニュアルをそれぞれの関係機関が対応力の向上に努めていただけるように、共通理解の促進に努めていきたいと考えています。","voiceIndex":183,"id":"exchange-080"},{"speaker":"おくの委員","kind":"質問・要望","question":"区営住宅に入居するときや退去するときに、浴槽と給湯設備を設置し、また、撤去することが自己負担とされているけれども、これを区の負担で行うことを求めて質問いたしました。品川区は、今も区営住宅の入居者が自己負担で浴槽と給湯設備を設置し、また、退去時に撤去すべきだというお考えなのでしょうか。この点からお伺いいたします。","respondent":"森住宅課長","answer":"区といたしましては、令和元年度からですが、退去された後の原状回復時に、区のほうで風呂釜の設置を進めております。２年間で１３戸新たに設置をしたところです。","voiceIndex":186,"id":"exchange-081"},{"speaker":"おくの委員","kind":"質問・要望","question":"設置、撤去について、区が負担することになったということで、これは私たちの会派も求めていたことですので非常に歓迎いたします。では、居住者の交代がなくて、同じ居住者のもとで浴槽、給湯設備が故障したり、壊れた場合に、修繕したり、あるいは取り替えたりした場合にはどうなのでしょうか。これは依然として自己負担のままなのでしょうか。これもお伺いいたします。","respondent":"森住宅課長","answer":"令和元年度から区のほうで設置をしておりますけれども、それ以前に自己負担で設置をされた方のものについて修繕が必要だということについては、自己の財産ですので、それぞれの居住者の方にやっていただいているです。","voiceIndex":188,"id":"exchange-082"},{"speaker":"おくの委員","kind":"質問","question":"自己の財産で自己負担だということなのですけれども、さきに紹介した石田ちひろ委員の質問への答弁の中で、当時の住宅課長は、区営住宅の多くは都営住宅から移管されたものだと答弁されています。都営住宅における昨年のこの動きをご存じでしょうか。区営住宅においても、こういうことをやってみるべきではないかと私は思ったのですけれども、いかがでしょうか。お伺いします。","respondent":"森住宅課長","answer":"試行期間ということで、どのぐらいの規模で、どのぐらいの申込者があったかということは、住棟単位についても、区のほうでは把握できておりませんけれども、都の状況を見ながら、使用者の声がどのように生かされていて、どのぐらいの付け替えがされたのかということは。","voiceIndex":190,"id":"exchange-083"},{"speaker":"おくの委員","kind":"質問","question":"区営住宅のほうで、やるべきではないかという点については、どうお考えでしょうか。","respondent":"森住宅課長","answer":"都のほうでも３０年以上住まわれた方でというような方で一応線を引いているというところもありますので、区では、今のところ、それぞれの方に処理していただくということで考えております。","voiceIndex":192,"id":"exchange-084"},{"speaker":"おくの委員","kind":"質問・要望","question":"区営住宅に入居してから年月が経てば、浴槽、給湯設備、老朽化は当然進みます。ですから、区営住宅でも、民間賃貸住宅と同様に、浴槽、給湯設備は一般的で必要不可欠な住宅設備だという認識を前提にして、居住者の費用で設置した浴槽、風呂釜などであっても、区の負担で修繕や取替えを行うことに何とか踏み出していただきたいのですけれども、もう一度いかがでしょうか。","respondent":"森住宅課長","answer":"基本的には、壊れた部分について補修をするとか、そういったものについては、それぞれの財産ですので、これからもお願いをしていくことで、区のほうで今住んでいる方に対して取替えをしていくということは今のところ考えておりませんけれども。","voiceIndex":194,"id":"exchange-085"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、１４０ページ、ふるさと納税寄附金、それから時間があれば、１３３ページの都議会議員選挙費と衆議院議員選挙費について質問します。ふるさと納税による税の流出についてなのですけれども、一昨年の流出額は２３億円でありましたが、年々増加する傾向を区はどのように考えていらっしゃるのか。","respondent":"伊東税務課長","answer":"ということで大きな金額ですので、我々も何とかと思っているところですけれども、根本的には、制度改正をしないことにはなかなか難しいというところがあります。","voiceIndex":197,"id":"exchange-086"},{"speaker":"湯澤委員","kind":"質問","question":"登録サイトを増やせば手数料がかかるというご回答は伺っておりますが、例えば、楽天ふるさと納税、こちらのほうは、楽天カードユーザーが利用すれば最大３１％のポイントが還元されるために、かなりの人気になっております。以上、登録サイトを増やすこと、品目を増やすこと、金額設定、品切れについて、４点ご意見をお聞かせいただければと思います。","respondent":"伊東税務課長","answer":"登録サイトを増やすべきというお話ですけれども、我々、この間、平成２８年度だったかと思いますけれども、最大規模ということでふるさとチョイスに登録してやってきた経過があります。","voiceIndex":199,"id":"exchange-087"},{"speaker":"湯澤委員","kind":"質問","question":"今、シナモロールは、１つのほうだけ品切れということでありましたけれども、ふるさとパレットのほうを見ると、２つとも品切れの状態であったと思いますので、やっぱり返礼品が品切れというのはどうかと思いますので、在庫数を増やすとか、あとは、寄附者に返礼品が遅くなるという旨を伝えて受注生産するなどすべきかと思います。そのほかについては、それぞれぜひ前向きな検討をしていただければと思います。","respondent":"伊東税務課長","answer":"ガバメントクラウドファンディングの今後ですけれども、ガバメントクラウドファンティングに関しては特定の自治体の事業に対してやるものですので、それぞれいい事業がございましたら活用していきたいというふうに考えております。","voiceIndex":201,"id":"exchange-088"},{"speaker":"くにば委員","kind":"質問","question":"本日は、１５７ページ、雑入の公園内自動販売機設置運営事業収入、あわせて、区有施設の自動販売機設置運営について伺います。残りの時間で、１５１ページ、広告料収入の広報しながわについてお伺いします。自動販売機の設置による収入は、当区においても着実な税外収入の確保の１つとして定着しており、適切な管理運営が望まれます。お伺いします。","respondent":"高梨公園課長、東野経理課長、稲田土木管理課長","answer":"区立公園内の自動販売機の状況についてご説明をいたします。区立公園におきましては、１５公園におきまして全３９台の自動販売機を設置しております。庁舎でいきますと、庁舎内では５台ほど設置しておりまして、この中に６３８万５,０００円ほど計上しているものです。それと、設置許可で許可をしている自動販売機がございまして、公園内が１８台、年間１１万５,１２８円。","voiceIndex":205,"id":"exchange-089"},{"speaker":"くにば委員","kind":"質問","question":"その公園内に設置しているものに関してですけれども、先ほどおっしゃった数字と、プラスアルファで、あと福祉団体が管理している自販機があるというふうに伺ったのですけれども、そこに関しても併せてご答弁をお願いします。","respondent":"高梨公園課長","answer":"先ほどご説明しました１５公園３９台の内訳ですが、私のほうで収入額を申し上げた、飲料事業者によるものが２１台です。そのほかの１８台につきましては、区内の福祉団体による設置ということになってあります。","voiceIndex":209,"id":"exchange-090"},{"speaker":"くにば委員","kind":"質問","question":"それに関しては、お話をお伺いした中で、やはり長年、昔からの契約の中で綿々と置いていると。例えば、１つコカ・コーラの自動販売機が置いてあったら、その横にアサヒ飲料の自動販売機を置くであるとか、そういった形で様々なメーカーの自動販売機をプラスでどんどん置いていくということも可能なのかというふうに考えますけれども、そこに関してご見解を伺います。","respondent":"高梨公園課長","answer":"公園内の自動販売機は、まず、公園利用者の方にしっかりとサービスとして、便益施設として使用していただくというのが目的ですので、まず、公園の中に自動販売機の需要がどの程度あるのか、今置いている自動販売機が足りないかどうかといったところをしっかりと見定めて。","voiceIndex":211,"id":"exchange-091"},{"speaker":"くにば委員","kind":"質問","question":"あわせまして、災害対応型自動販売機、こちらについて伺います。こちらはコカ・コーラ社の事例によりますと、東日本大震災の際には約４００台が稼働して８万８,０００本以上の製品の無償提供が行われたとのことです。現在、本区が管理している自動販売機のうち、災害対応型の割合について、また、今後、災害対応型自動販売機の導入についての方針やスケジュールを教えてください。","respondent":"東野経理課長、高梨公園課長","answer":"こちらにつきましては、災害時の協力要請がすぐにとれるという形で協定を結んでいるものでございまして、今後も、新規に設置する場合につきましては、同様に災害時の備えを行ってまいりたいと考えています。公園内自動販売機につきましては、飲料事業者が設置している１１公園２１台については、全て災害対応用のベンダーという形になっております。","voiceIndex":213,"id":"exchange-092"},{"speaker":"くにば委員","kind":"意見","question":"広報しながわについて、最後に少し時間がありますのでお話しします。これは昨年の予算特別委員会、そして決算特別委員会に続きましてこれで３回目です。それで、そこのスペースがないという部分について、以前も編集方針により、そこの部分はどうにでもなるというふうに申し上げましたけれども、そのスペースがないという部分について、もう一度改めてご答弁ください。","respondent":"大澤広報広聴課長","answer":"詰めれば入るということだと思うのですけれども、やはり区報は見やすさという観点も重要ですので、現在のところ、広告スペースを増やす考えはございません。","voiceIndex":216,"id":"exchange-093"},{"speaker":"くにば委員","kind":"質問","question":"スペースを詰めればというよりは、スペースがあるから、この広告を入れたいということで、すみません、また総務費で質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-094"},{"speaker":"松澤委員","kind":"質問","question":"私からは、６５ページ、区民活動交流施設使用料についてお聞きします。品川区では、令和元年７月に４０万人を超え、区民の９割が住み続けたいとの声には、私も生まれ育った町として大変誇らしく思っております。そこで現在の品川区の人口、今、コロナ禍ですけれども、どれだけ増えて、今後どのような推移を見込んでいるのか教えてください。","respondent":"佐藤企画調整課長","answer":"今後、３月、４月は、転入も増える時期でもありますので、その動向を見極めていきたいと考えています。","voiceIndex":220,"id":"exchange-095"},{"speaker":"松澤委員","kind":"質問","question":"我が町品川の発展は大変うれしい限りであります。昨年からの質問になりますが、全国の自治体でも課題となっています町会・自治会の加入について質問いたします。昨年の質疑の中で、町会加入の促進活動で、促進チラシや申込みはがきの配布、ＱＲコードによる電子申請など、大変努力していただいておりますが、町会・自治会の加入率は、ここ数年で、どのような推移をたどっているのか教えてください。","respondent":"川島地域活動課長","answer":"過去３年間、町会・自治会加入率の推移ですが、平成３０年度が５９.８６％、令和元年度が５９.９６％、令和２年度が５８.３４％と、約６０％で推移しているところで、ほぼ横ばいの状況という認識です。","voiceIndex":222,"id":"exchange-096"},{"speaker":"松澤委員","kind":"質問","question":"この数字は、区の支援の下支えによって何とか横ばいを保っているのではないでしょうか。これはまた別の若い世代だけをターゲットに、なぜ町内会に入らないのかという大学生が町会・自治会加入の参加ポスターを作るためにとったアンケートのものですが、「そもそも町会ってなんですか」、「何をするの」、「魅力が分からない」、「高齢者しかいないんでしょう」という意見が大半を占め驚きました。","respondent":"川島地域活動課長","answer":"定期的なメンテナンスや更新がなかなか難しい状況にあるという町会・自治会が少なくないということで、担い手の確保につきましては非常に難しい課題ですが、現在やってあります町会・自治会活動活性化促進調査の結果などもしっかり活用して。","voiceIndex":224,"id":"exchange-097"},{"speaker":"松澤委員","kind":"提案","question":"そこで区民の皆さんの地域の問題を解決したい、地域の魅力をもっと高めたいという思いを実現するための施設整備に対して支援助成を行い、防犯防災、多世代機能、環境など、分野を問わず、コンテスト形式にして助成金を採択するやり方をご提案いたします。そういったような取組も品川区でぜひやっていただきたいと思いますが、ご見解をお聞かせください。","respondent":"川島地域活動課長","answer":"引き続きこの制度をしっかり活用していきまして、創意工夫を凝らしました町のイベントを実施してもらい、その活動を地域で共有しまして、地域の元気の源になります町会・自治会活動の活性化をしっかり支援していきたいというふうに考えております。","voiceIndex":226,"id":"exchange-098"},{"speaker":"松澤委員","kind":"質問・要望","question":"まだまだ１件と少ない実績数で、もう少しこの支援が拡充すればいいかなと考えています。人を動かす動機という部分におきまして、何々しなさいとか、何々しなければならないという受け身の昔のような考え方ではなく、やはり若い世代の何々したいという自発的な考え方を確実に引き出して、時代の変化を注視し、これからもますます活気あふれる品川区になるよう要望して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-099"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１１５ページの特別養護老人ホーム運営費に関わって、特養ホームの増設について伺います。これはどういう意味でしょうか。特養ホームを増設するということでしょうか。伺います。","respondent":"寺嶋福祉計画課長","answer":"第八期の介護保険事業計画におきましても、様々なニーズに対応するよう特養ホームを含めた施設整備全般を検討していくという意味です。","voiceIndex":230,"id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"特養ホームを含めたということですけれども、今後、重度化が想定されるということで、そういった整備も含めて行っていくということですけれども、この重度化が想定されるというのはどういう意味でしょうか。これまでも重度化してきた人がいたと思うのです。これまでと何が違うのか伺います。","respondent":"寺嶋福祉計画課長","answer":"当然ながら、高齢化に伴って要介護度の状態も重度化していくという傾向が見受けられます。そういった意味で、今後、重度化が進むという認識を持っているということで申し上げたところです。","voiceIndex":232,"id":"exchange-101"},{"speaker":"のだて委員","kind":"質問","question":"高齢化が進んで、それで重度化が進んで、それで必要だということなのですけれども、つまりは特養ホームも増設していくということでよろしいのか伺います。","respondent":"寺嶋福祉計画課長","answer":"特養ホームを含めた様々なサービスの提供に努めていくです。","voiceIndex":234,"id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、小山台住宅跡地に２９ベッド、また、八潮南特養の増築と、特養ホームを増やす計画が示されておりますけれども、この計画は歓迎しております。さらなる増設計画はあるのでしょうか。ぜひつくっていただきたいと思いますけれども、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"現在予定されているものとしましては、今、委員からありましたとおり、この２か所です。地域密着型サービスの整備ということもあわせて検討しています。","voiceIndex":236,"id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"地域密着型も検討しているということで、今、何か所か検討されているところがあるということでしょうか。","respondent":"寺嶋福祉計画課長","answer":"そういった意味では、来年度、これは歳出のほうになりますけれども、特養ホームの基本計画ということで２か所、先ほど申し上げました八潮南、それから小山台の計画を進めていくという、今こういう方向性になっているところです。","voiceIndex":238,"id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"地域密着型については、まだ具体的にはなっていないということだと思います。そして、今回、八潮南特養の増築が示されたわけですけれども、なぜ増築することになったのか、理由を伺います。","respondent":"寺嶋福祉計画課長","answer":"この間も様々、地域密着型、いわゆる特養も含めた地域密着型サービスの進捗も含めまして、特養ホームの整備についても、この間、検討はしてきたところですけれども、ご案内のとおり、平成２８年５月に平塚橋、それから平成２９年６月に上大崎ということで。","voiceIndex":240,"id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"３０ベッド以上に増えると思っています。地域密着型は２９ベッド以下ですけれども、これまでの方針を変えたということでしょうか。伺います。","respondent":"寺嶋福祉計画課長","answer":"一定程度、比較的小さめな用地でも整備は可能だという、こういったメリットがありまして、それから様々なニーズに応えられるといったことも含めて、地域密着型サービスの整備を力を入れて進めてきたところですけれども、特養ホームにつきましては、先ほど申し上げたとおり。","voiceIndex":242,"id":"exchange-106"},{"speaker":"のだて委員","kind":"質問","question":"方針としては変わっていないということですけれども、やはりさらなる増設を進めていくということが必要だと思うのです。昨年２月の申請で４７１人が申込みをして、介護度５の人も、１００歳以上の人も入れないと、８６％の方が入れないという状況を、さきの一般質問でも示させていただきました。今年の２月と、昨年８月の申込み数を伺います。","respondent":"宮尾高齢者福祉課長","answer":"私からは、特別養護老人ホーム入所申請の数についてお答えをいたします。昨年８月にお申込みをいただいた申込者の数ですが４４５人、その半年前の２月の時点でお申込みいただいた方が４７９人とそれぞれなっております。","voiceIndex":244,"id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"今年２月の申請の申込数が分かりましたら、あとでご答弁いただければと思います。こうした新しい特養ができても状況は変わっていないということになっています。まだまだ特養ホームの増設が必要だと思いますけれども、いかがでしょうか。やはりそうした大規模な特養を増設していくということが、待機者が入れるようにしていくためには必要なのではないかというふうに思うのですけれども、いかがでしょうか。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"繰り返しの答弁になりますけれども、今現在、高齢者の人口がまだ増え続けている時期にあるということでは、一定程度の施設整備が必要だと考えております。今年２月末でお申込みをいただいた方の数ですが、速報値でありますので、若干人数が変更する可能性はありますが、２月末時点で４１３人の方から申請をいただいております。","voiceIndex":246,"id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"申請をしても入れないという方が待っていらっしゃるというわけですから、ぜひ増設を進めていっていただきたいというふうに思うのですけれども、区は、この待機者を正しく定義すること、数を正確に把握することは大変困難ということも説明しておりますが、やはり潜在的な待機者もいるわけですから、申請者全員が入れるよう増設をすることが必要だと思います。","respondent":"宮尾高齢者福祉課長","answer":"その方一人ひとりに対して、私どもはしっかりと丁寧に説明をさせていただいて、いろいろなご提案をしています。中には、詳しくご説明をされると、いろいろな選択肢があるということを、そこで改めてお知りになる方もいらっしゃいます。","voiceIndex":249,"id":"exchange-109"},{"speaker":"のだて委員","kind":"質問","question":"先ほども言いましたけれども、８６％の方が入れないという状況なわけです。そうした中で、やはり入れるように増設をしていくということが必要だと思います。区も、再度入所申請している方が４割と説明をしています。こうした方々がずっと申し込み続けているわけです。その方々が入れないということで、区の認識でもこういった方々は本当に必要な方だというふうに思うのですが、認識を伺います。","respondent":"宮尾高齢者福祉課長","answer":"ですので、先ほどの答弁の繰り返しになりますけれども、施設入所がかなわなかった、そこで決して我々の支援、サポートが終わるわけではなく、そこからどうやって次につなげていくかというところも、ふだん非常に大切にして業務に当たっているところです。","voiceIndex":251,"id":"exchange-110"},{"speaker":"のだて委員","kind":"質問・要望","question":"入れない方が数百人単位でいるわけですから、土地がないというのであれば、民間に土地を募集などもして増設する計画をつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-111"},{"speaker":"あくつ委員","kind":"質問・要望","question":"歩道橋維持費収入で関連をしまして、南品川青物横丁交差点と、京浜急行北品川駅前の２つの歩道橋について伺います。というところで、これはエレベーターの設置、もしくは横断歩道の設置の実現は、議会の方はご存じだと思うのですけれども、２０年近く前からの地元要望であり、区から国へ要望を上げていただくように、私も委員会での質問や直接国へも、これは陰にも陽にも何度も取り上げてきた悲願の一つです。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただきましたように、やはり広幅員の国道を渡るということで、それを通行する方もいると、バリアフリー対応のエレベーターもついていないというところで、地域から、以前より強い要望をいただいているところでございまして、区としましては。","voiceIndex":255,"id":"exchange-112"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこで国会議員にお願いをしまして、先週の金曜日、２月２６日の国会の予算委員会で、地元の要望として質問で取り上げていただきました。この質疑の模様は衆議院のインターネット中継アーカイブでどこからでも見られますけれども、所管課長である都市計画課長もご覧になったと思うのですが、国交省道路局長の答弁をお聞きになっての感触、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区の受け止めですが、やはりこれまでも国から説明のあった、歩道が狭いですとか、様々な課題についての発言がありましたが、非常に前向きな発言を道路行政のトップの局長が国会の場で発言していただいたと、前向きな答弁として、第一歩ということで。","voiceIndex":257,"id":"exchange-113"},{"speaker":"あくつ委員","kind":"質問・要望","question":"時間の関係で、北品川駅の前の歩道橋について、これも国道１５号です。第一京浜ですけれども、これは国会で質問していただくことはできなかったのですが、こちらも長年の地元要望です。あそこの辺りは信号がないものですから、結構遠回りしなければいけない。この歩道橋に関しての区のお考えと、国への要望状況、また課題等があれば、お聞かせください。","respondent":"鈴木都市計画課長","answer":"北品川歩道橋につきましても、青物横丁歩道橋と同様、昭和４０年代当初、築５０年以上が経過している歩道橋だということで、地域からは、老朽化に伴う建て替え、それから、やはり駅前にあって横断するための一番身近な横断施設ということで。","voiceIndex":259,"id":"exchange-114"},{"speaker":"あくつ委員","kind":"質問・要望","question":"両歩道橋に関しましては、国への働きかけと要望を一層強めていただければと思います。続きまして、交通安全対策特別交付金、関連をいたしまして自転車活用推進計画についての策定の進捗状況を確認します。品川区の当初予算で、今日は歳入の審査ですけれども、土木費の都市計画費辺りには、策定経費が計上されていないのですけれども、それはどこかに含めているのか、どこに含まれるのか教えてください。","respondent":"鈴木都市計画課長","answer":"この計画の中身をしっかり確認をして、一方では都市計画のマスタープランの改定も行います現計画はどちらかというと自転車について明示しているところはございませんが、マスタープランの改定検討は、やはりハード的なところで。","voiceIndex":261,"id":"exchange-115"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１年半前にこの話をしたときに一番大事だなと思っていたのは、品川区においては、いわゆる違法駐輪のことでしか自転車というものの位置づけがなかったので、これから今いろいろな環境が変わってくる中で、新しい活用の位置づけをぜひお願いしたいので計画をというお話だったので、それはしっかりと検討していただきたいと思います。それが審査に影響をしたのかどうか、そのことについて教えてください。","respondent":"築山障害者施策推進担当課長","answer":"区の考える指定管理施設や運営のあり方や障害福祉事業とは異なっている部分も多々出てくるかもしれないが、そのことも含め審査をしてほしい」という表明がされまして、そのことが応募団体の大事なスタンスとして説明がございました。","voiceIndex":263,"id":"exchange-116"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今後の考え方というか、意向も伺った上で、冒頭申し上げた、いわゆる継続を求めたいというお声が非常に利用者の中で多かったというところと、ただ、今回の議案の賛否が必ずしもリンクをしないというところで私どもも検討させていただいています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":265,"id":"exchange-117"},{"speaker":"あべ委員","kind":"質問","question":"自転車駐車場ですけれども、大森駅水神口の地下駐輪場の利用率は現行でどの程度になっているでしょうか。それから、情報公開手数料、この１,０００件の内訳を教えてください。どのような積算でこの金額になっているでしょうか。これが週末まで毎日発行しても、割り返すと、丸々２年以上かかってしまうのではないかと思うのですけれども、こういう体制でいいのかどうかということをまずお伺いします。","respondent":"川口交通安全担当課長、大澤広報広聴課長、木村戸籍住民課長","answer":"こちらにつきましては９７.５％、また、公園内にあります機械式の地下の駐車場、こちらにつきましては４４.７％となっております。情報公開手数料の内訳ですけれども、閲覧にかかる手数料の３００円掛ける１,０００件と、あとコピー代として、１０円掛ける２万４００枚ということで。出先施設での取扱いを始めるというところで、スピード感を持って対応してまいりたいというふうに思っております。","voiceIndex":267,"id":"exchange-118"},{"speaker":"あべ委員","kind":"質問","question":"やはり地下駐輪場は非常に規模が大きいところですけれども、これがまだ利用率が４０％台ということで一番低くなっている。なので、品川区のこの３００円が物すごい突出した状況になっているかと思うのですけれども、本来、品川区の持つ行政の情報は区民のものです。これはやはり今の時代に合わないと思うので、見直しをされるべきではないかと思いますが、いかがでしょうか。ご答弁をお願いします。","respondent":"川口交通安全担当課長、大澤広報広聴課長","answer":"ですので、現在、利用率の非常に高い部分は当日利用となっておりますので、今後、利用状況等も見ながら検討してまいりたいというふうに考えております。一部の方への労力の提供ということでは受益者負担という考え方で、今のところ、閲覧の手数料はいただくということで実施してまいりたいというふうに考えております。","voiceIndex":271,"id":"exchange-119"},{"speaker":"あべ委員","kind":"質問・要望","question":"駐輪場は、地下が使いにくい、使われにくいから余計に地上の利用率が上がるという面もあると思いますので、バランスも含めて考えていただければと思います。なぜほかの区がそのような形にしているのか、情報公開というのは民主主義のスタートラインですので、ぜひ前向きにご検討をいただければと思います。実績を教えていただきたいのと、令和３年度は、どうなっていくのか教えてください。","respondent":"櫻木生活福祉課長","answer":"ご質問の暮らし・しごと応援センターで配布しております食料支援の件ですが、実績としましては、今年度につきましては９件の実績があります。９件で、おおむね３か月程度ご利用いただいているという状況です。来年度につきましても同じような形で継続したいと考えています。","voiceIndex":274,"id":"exchange-120"},{"speaker":"あべ委員","kind":"意見","question":"チラシも見たことないです。必要な方は大勢いらっしゃると思いますし、予算もかけているわけですし、ある程度質の高い食材を提供しているということから、こういうものがあるから相談に来てねというためにできた事業だったと思いますので、たまたま来た人にご案内をするのではなくて、これを契機にご案内できるように、ぜひ運用方よろしくお願いしたいと思いますが、一言よろしくお願いします。","respondent":"櫻木生活福祉課長","answer":"基本的に制度としては、様々な制度を含め周知をしていくことは大事なことだと考えています。この事業の性質自体が、ある程度お話を伺った上で必要な方にご紹介するということもありますので、その辺りを見ながら適切な周知は考えていきたいと考えています。","voiceIndex":276,"id":"exchange-121"},{"speaker":"あべ委員","kind":"質問・要望","question":"時間がなくなってしまいましたけれども、冒頭だけ触れます。特別区競馬組合配分金、特別区競馬組合は２３区でつくる一部事務組合です。人事・厚生事務組合や清掃一部事務組合に比べても、公開情報が非常に少なくて、どのような組織であって、どういう人が、どのように運営しているのか、予算、決算、組織など、ほとんど分からない状態であると思います。ぜひ品川区としても取り扱っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":278,"id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"確認","question":"５０ページ、第１款特別区税、それから５３ページ、第２款の地方譲与税の中の森林環境譲与税、これは児童相談所の新築分に絡んでです。それから第１３款で国庫支出金、民生費補助金の、９３ページ、母子・父子家庭自立支援給付金事業補助金。その中で、これも新型コロナウイルス感染症の影響を受けたことから大分支給も増えたと思うのですが、その支給の金額の実態等、世帯数とかを確認させてください。","respondent":"崎村子ども家庭支援センター長、三ッ橋子育て応援課長","answer":"今年度、１月末現在ですけれども、虐待相談の件数、子ども家庭支援センターでは、今、５２０件取り扱っているところです。令和元年度が５１０件でございましたので、２か月を残して前年度を上回る件数を、今、受理、対応しています。こちら、申請の締切りが２月２６日となっておりまして、まだ最終確認をして審査をしている部分がありますので、最終的にはもう少し件数が上がると思われます。","voiceIndex":281,"id":"exchange-123"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"虐待の件数はストレスとか、新型コロナウイルス感染症の影響はあると思うのですけれども、１件でも少なくなっていただきたいという、相談の中で早くクリアしてもらいたいなという希望がありますので、その辺、これからも十分対応をお願いしたいと思います。それから、ひとり親の今の手当の関係ですけれども、総額でお話しいただいたのですけれども、１世帯当たりの金額をもう１回確認させてください。","respondent":"加島児童相談所移管担当課長、三ッ橋子育て応援課長","answer":"一時保護についてですが、原則は自らの一時保護所で対応いたします。支給金額ですが、基本給付は１世帯当たり５万円、第二子以降は１人当たり３万円。追加給付ですが、１世帯当たり５万円です。再支給分は、基本給付と同様で、１世帯当たり５万円、第二子以降、１人当たり３万円となっております。","voiceIndex":284,"id":"exchange-124"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一時保護所が相互利用というお話を今いただいたのですけれども、例えばその連携についての費用的なものというのは。例えば品川区のお子さんが別の場所に行ったときには、その分の負担とか。それから、相互利用するための組織的なもの、新たな組織をつくるということは私は非常におかしいと思いますので、どういう体制をもって相談をやっていくのか、その点について教えてください。","respondent":"加島児童相談所移管担当課長、三ッ橋子育て応援課長","answer":"他区の一時保護所で品川区の子どもが仮に事故、けが等があった場合の責任問題といいますか、責任の所在についてですけれども、こちらにつきましては、依頼元。今年度につきましては、なかなかお米については対応できないのですけれども、来年度、品川ロータリークラブがお米の寄附をしてくださる予定になっております。","voiceIndex":287,"id":"exchange-125"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ところが、令和３年度の予算の中には、その補助金は直接計上されていないと思うのです。その辺がどういうふうになっているのか教えてください。それから、建築費総額が約３０億円ですけれども、基本方針の中には、財源として３種類の国庫補助金、その辺も出ていたのですけれども、あとこれからどのような補助金が対象になってくるのか、その辺も確認させてください。","respondent":"加島児童相談所移管担当課長、三ッ橋子育て応援課長","answer":"ですが、一時保護所、こちらは最大で約２億４,０００万円、点数に基づき交付を見込んでおりまして、工事期間の３か年にわたってこれを収入する計画です。養育費の支援における家庭相談員の役割です。令和２年度から採用した家庭相談員に関しましては、家庭裁判所の調査官をちょうど定年退職され、４月１日からこちらに会計年度任用職員として採用しております。","voiceIndex":290,"id":"exchange-126"},{"speaker":"鈴木（真）委員","kind":"確認","question":"最後に、特別区税に関して確認だけ。理由も人口減とか所得減というのは十分分かっておりますが、今度、長期基本計画との関係でもう１回改めて見てみたのですけれども、そこでも大分長期基本計画と比べると数字も変わっている状況になっています。ただ、それが今後どういうふうに、この状況ですから非常に難しい状況と、それから区の財政全体を今後どう見るかも考えていく中で、考え方だけ確認させてください。","respondent":"佐藤企画調整課長","answer":"現在、委員ご紹介のとおり、新型コロナウイルス感染症の影響から、適切に成果指標を設定することがなかなか難しい状況です。新型コロナウイルス感染症が収束に向かいましたら、また策定作業を始めまして、財政面も含めて適切に対応したいと考えています。","voiceIndex":293,"id":"exchange-127"},{"speaker":"鈴木（真）委員","kind":"意見","question":"十分その辺は分かりますので、ぜひお願いしたいと。ただ、予算上ですと、今年は計上してないのかどうか、ちょっとそこが分からなかったので、予算上のどこかに計上されているのかどうか、予算は要らないのかどうか。","respondent":"佐藤企画調整課長","answer":"今年度、実施計画の策定に係る予算は計上しておりません。","voiceIndex":295,"id":"exchange-128"},{"speaker":"安藤委員","kind":"質問","question":"９７ページ、社会資本整備総合交付金、この交付金は、品川駅南地域周辺まちづくり事業にも、２分の１、３００万円が充当されております。関連して、この品川駅南地域の再開発計画について伺いたいと思います。伺いますが、区はこの間、品川駅南地域のまちづくり検討に予算をつけて委託してきましたが、総額幾ら予算をかけてきたのか、累積額を伺います。いつからこの検討経費が予算化されたのかも伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今までに品川駅南地域におけますまちづくりの予算についてですが、平成２４年度から計上していまして、令和３年度を含めますと、合計１０回計上しています。歳出の合計金額ですが、令和２年度予算額、令和３年度要望額としまして、合計金額が約１億１,５００万円です。","voiceIndex":298,"id":"exchange-129"},{"speaker":"安藤委員","kind":"質問","question":"１０年にわたり１億円を超える予算がつき検討されてきたということです。伺いますけれども、予算を組んで区民の税金を使って検討されたものです。こうした資料の内容は隠さず公開されて当然だと思いますけれども、いかがでしょうか。一定の調査権もあります。黒塗りや非公開などの処理をせずに公開すべきだと思うのですけれども、議員から出してと言われたら出していただけるのでしょうか。伺います。","respondent":"中道まちづくり立体化担当課長","answer":"情報公開についてですが、区としましては、行政の情報等は公開が原則ということは認識しています。","voiceIndex":300,"id":"exchange-130"},{"speaker":"安藤委員","kind":"質問","question":"今回、私、情報公開で請求したのですが、情報公開しなくても、議員ですから、区政を監視する役割もありますから、出していただけるのでしょうかという質問もしたのでお答えください。一部と言いますけれども、まちづくりですから、どういうまちをつくるかという検討する資料を出さないというのは、私はおかしいと思っていまして、政策形成過程だからこそ情報は公開すべきなのではないでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"情報公開、または、そのまちづくりの途中での開示ですが、そこのまちづくりの検討中のまだ素案の段階になりますので、そうしたまだ決定していない情報につきましては、やはり今後どうなるか、地域の方がそれを見たときに、まだ確定でないものを不安に思ってしまう。","voiceIndex":302,"id":"exchange-131"},{"speaker":"安藤委員","kind":"質問","question":"くどいようですけれども、議員が出してと言ったら出せないのかというところはお答えください。何が不安なのかなと思って。区はまちづくりの検討、しかも税金も相当使っていますよね。これだけの大きな、区としては位置づけが高い事業について、その過程を公開しないというのは、私はこれはまちづくりに住民の意見を入れるつもりがないというふうにしか思えないのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"まちづくり全般ということで私のほうからお答えいたします。まちづくりを進める事業にあたりましては、検討の段階におきまして、議員の皆様には建設委員会であったり、常任委員会の中でご説明しながら、ご意見をいただき、熟度を上げながら整備しています。","voiceIndex":304,"id":"exchange-132"},{"speaker":"安藤委員","kind":"質問","question":"今回、私、質問したいと思って情報公開したからこういう情報が出たのですけれども、建設委員会には２０１４年５月のまちづくりビジョン公表前の報告以来、７年近くも報告されてない。このアンケートはもちろん税金で実施されています。住民参加、議会に説明というのは建前で、なるべく水面下で検討を進めて、開発協力企業など一部の意向でまちづくりをしたいからではないのでしょうか。伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今現在のまちづくり状況ですが、まだ素案の段階の前なので、建設委員会のほうに報告すべき段階でないです。建設委員会のほうに報告すべき段階、素案等を決定しましたら、その段階で建設委員会のほうには報告いたします。","voiceIndex":306,"id":"exchange-133"},{"speaker":"安藤委員","kind":"質問・要望","question":"かなり大がかりにアンケートも１,０００人を対象にやっていたわけですから、そのアンケートが基礎材料となって、どういうまちづくりを進めるかというのをそれは建設委員でも議論すべきでしょうと思うので、それは、これまでのやり方を改めてきちんと建設委員会に報告してくださいと述べたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"品川駅南地域の未来を創る推進協議会、または品川浦周辺地域再開発協議会の事務局ですが、地域の方々の町会長ならびに商店街、または代表者といった方々で構成されてあります。","voiceIndex":308,"id":"exchange-134"},{"speaker":"西本委員","kind":"確認","question":"ただ、自費で設置した方で壊れた場合は自分で直せという、これはちょっと私は理解できないなと思ったので、その考えをもう一度確認させてください。そして、次、６０ページの使用料です。これはどういうときに使われるのでしょうか。それからもう１つ、指定管理者制度、これは歳入全般になると思うのですけれども、指定管理者制度を使っていて、この利益、歳入は全く発生しないという仕組みなのでしょうか。","respondent":"森住宅課長、川島地域活動課長、品川財政課長、佐藤企画調整課長","answer":"ご自身でつけられたものにつきましては、それぞれ補修をしていただいてということで。集会所の貸し出しの考え方としましては、使用料を何時間で何平米の広さの部屋をお貸しするかというような形で料金設定をしているものでございまして。早急な対応をするためということで２億円増やしております。指定管理料ですけれども、運営費をたたずまいとしてまず考えまして、それから利用料収入を引いて。","voiceIndex":311,"id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"結局、給湯器、それから浴槽のことについては、令和３年度から事業として始めますということになっているわけですから、では、令和３年度からそれを適用して、その方々が、例えば故障したといった場合は誰が払うのですか。区が払うのですか、それとも個人になるのですか。３分の１から半分ぐらいにしてくださいねと言われているのです。ですので、それを考慮していただけないでしょうか。それ教えてください。","respondent":"森住宅課長、川島地域活動課長、佐藤企画調整課長","answer":"その後、令和３年度からは、それぞれご自身でつけられたものに対しては、もし撤去してよいということであれば。こちらは、制限が感染症対策であるということを丁寧に説明させていただきまして、ご理解の上で今ご利用いただいておりますので、今のところ。２点目の収支を予算書等に反映してはですが、今、常任委員会のほうで報告を毎年させていただいているモニタリング評価等で。","voiceIndex":316,"id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"区営住宅はやはり理解できません。壊れたら設置してあげればいいではないですかと思います。それと、集会所については、コロナ禍の状況で、そういう仕様になっているのです。だから、その分お金がかかっているのです。だから、それは前向きにぜひ検討していただきたい。ここだけお願いします。","respondent":"川島地域活動課長","answer":"繰り返しの答弁になりますが、現状の料金はそのままという形で考えさせていただきたいと思います。","voiceIndex":320,"id":"exchange-137"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"６１ページ、区民斎場使用料、なぎさ会館、６７ページ、八潮北公園スケートボード場について質問します。初めに、なぎさ会館、区民斎場使用料のことなのですけれども、新型コロナウイルス感染症の対策に伴い、令和２年４月１３日から利用制限をかけているということです。利用者は１日１組ということなのですけれども、当然、今はまだコロナ禍なので、現況をお知らせいただきたいと思います。","respondent":"木村戸籍住民課長","answer":"今年度に入りまして１月末現在での稼働率ですけれども、約３４％という形になっております。昨年度は約４０％ですので、ご利用される方の減少傾向があります。感染症拡大防止のために家族葬など葬儀を小規模化するような動きがあるです。","voiceIndex":323,"id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問","question":"約３４％の稼働率ということで、民間の葬祭場も、やはり今課長のご答弁ありましたように、本当に家族葬、あるいは、もうそのまま見送って葬祭をやらないというのが現状だと思います。それで、今この状態で、緊急事態宣言が解除されて、見込みとして、どういうふうにお考えになっているのかお願いします。","respondent":"木村戸籍住民課長","answer":"実際のコロナ禍のこれからの状況に応じて、ある程度そういう３密みたいな部分での動きが解除されるような形になりましたら、基本的には元通りの２組というような形に戻して、もちろん感染症対策も行いつつ行っていきたいというふうに考えておるところです。","voiceIndex":325,"id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本当に新型コロナウイルス感染症が終息しても、今後の葬祭のあり方というものが物すごく加速すると思うのです。当然、区民斎場なので、協定の葬儀制度とかもある中で、今後どういうふうに、取組というか、現状のままやっていくのか、あるいは、なぎさ会館を今後どういうふうに展開していくのかだけお聞きしたいと思います。","respondent":"木村戸籍住民課長","answer":"今後、地域の皆様のそういう需要を踏まえながら活用を考えてまいりたいというふうに思っております。","voiceIndex":327,"id":"exchange-140"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ホームページに、授乳室の使用の記載があるのですけれども、「葬儀が執り行われていない時間帯は、斎場利用者以外の方にもご使用いただけます」と書いてあるのですけれども、実際に利用されている方はいらっしゃるのですか。","respondent":"木村戸籍住民課長","answer":"現地では、のぼりも立ててご案内をしていますけれども、外出自粛の影響もあると思うのですが、現在はほとんどご利用がないというような状態です。引き続き、ご活用いただきたいというふうに考えております。","voiceIndex":329,"id":"exchange-141"},{"speaker":"高橋（伸）委員","kind":"質問","question":"防災の観点からも、今後ともよろしくお願いいたします。続いて、６７ページ、八潮北公園スケートボード場についてお伺いします。２０１７年にオープンした公共のスケートパーク、インターネット上でも、東京都のスケートパーク・スポット一覧として、本当に最新鋭のセクションを備えていて、公園の管理パークで、夜の９時までやっているということで、とても高評価をいただいております。","respondent":"高梨公園課長","answer":"今年度は、新型コロナウイルス感染症の対応もありますので、通常であれば毎月最終土曜日ということで年１２回実施していますが、令和２年度につきましては、年６回ということで予定をしております。現在まで、８月、１０月、１１月と、今年度は３回実施をしております。","voiceIndex":331,"id":"exchange-142"},{"speaker":"高橋（伸）委員","kind":"意見","question":"令和元年の決算を見ても２,４５８回、令和２年の決算３,１４８回ということで、数字的にも利用者がすごく多いのが見受けられます。それで、今後、もっともっとスケートをやる若者たちに知らせるために、区として、ＰＲ強化をこれからどういうふうに展開していくのかどうかだけお知らせください。","respondent":"高梨公園課長","answer":"今後についてですが、やはり訪れる方は若者、若年層の方が多いということで、若年層の方が多く使うＳＮＳを中心とした発信を来年度から行う予定で、現在、準備をしています。","voiceIndex":333,"id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"ここで確認したいのは、都区の全体フレームでは３.６％の減となっているのですが、先ほど紹介した区のほうは５.４％の減になっていまして、区のほうが２.０パーセント弱、大きくなっている。このことについて確認させてください。もう１つは、この法人住民税の影響を小さくするには、今後どのようなことが考えられるのか教えていただきたいと思います。","respondent":"品川財政課長","answer":"それから２点目の法人住民税のほうですけれども、この国税化については、なかなか品川区独自で動いても対国となりますと厳しい状況がありますので、２３区連携して、このことについては東京都とも連携して、やはり国のほうに声を上げて。","voiceIndex":336,"id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"この対象としては、飲食店の時短営業とか、外出移動自粛による直接的な影響を受けた事業者であるとか、また、その対象となり得る事業者としての具体例も細かく例示されて、いわゆる人流とか物流も含めた幅広い業種というふうに確認をしています。もう１つは、今の大臣答弁にありました国で手の届かないところ、これを自治体でしっかり対応していただきたいと。２点についてお伺いいたします。","respondent":"品川財政課長","answer":"令和２年度から、具体的に言えば、もう去年の３月ぐらいからですか、融資を大分力強く区のほうでは対応して支援を行ってきております。もう一部、何年かは返済をしなくていいとか、そういうような対応もして、何とか企業に頑張っていただきたいというような形で対応をしています。","voiceIndex":338,"id":"exchange-145"},{"speaker":"本多委員","kind":"質問","question":"１２９ページの防災区民組織育成費について質問します。地域コミュニティ防災活動拠点電源確保事業補助金ですけれども、３か年計画ですけれども、２０１町会・自治会への普及について、制度の利用状況、これまでと、これからについてそれぞれ教えてください。","respondent":"中島防災課長","answer":"地域コミュニティ防災活動拠点電源確保事業補助金に関してのお尋ねですが、こちらにつきましては、今年度の９月補正で、今年度事業としてお認めいただいたものでございまして、地域の防災区民組織の電源確保、災害時の初動対応で電源確保ができるように。","voiceIndex":342,"id":"exchange-146"},{"speaker":"本多委員","kind":"質問","question":"３か年計画ですので、おおむね３か年で全ての町会・自治会に行き渡るのかなというふうな感じだと思います。それで、今、実績が、まだ始まって日も浅いので、８６件の申請があって８０件ということですけれども、主にこの８０件というのが、先ほどの答弁でもありましたけれども、発電機ですとか、その辺が中心だということだと思うのですが、ほかにどういったニーズがあるのか、その現況を教えてください。","respondent":"中島防災課長","answer":"今年度、地域のほうからお申込みいただいたものは、今、手元にある数字ですと、カセットボンベ式の発電機が８０台、あと、ガソリン式の発電機が４４台、それと、太陽光を活用した蓄電池が４６台です。","voiceIndex":344,"id":"exchange-147"},{"speaker":"本多委員","kind":"質問","question":"分かりました。カセットボンベ式の発電機が一番なのですね。ガソリン式の発電機かなと思っておりましたが、分かりました。例えば、町会・自治会に区が貸与しているポンプがありますけれども、ポンプそのものは区の貸与だと思うのですが、それに使うガソリンとか、その辺の貯蔵については、どのように把握をされているのでしょうか。","respondent":"中島防災課長","answer":"基本的に燃料は危険なものでありますので、その基準の範囲内で管理していただくように考えております。","voiceIndex":346,"id":"exchange-148"},{"speaker":"本多委員","kind":"質問","question":"４０ｌぐらいまでが目安なのでしょうか。容量がある程度、一定量を超える場合の貯蔵に対する有資格者の配置の義務ですとか、あまり量が少なくてもいざというときに何十時間か使えないと備えにもならないのですが、あまり量が多くても、逆に危険過ぎるというところで、４０ｌを超える場合の有資格者の配置義務ですとか、その辺についてはいかがでしょうか。","respondent":"中島防災課長","answer":"といいますのも、４０ｌで、発電機の大きさでありますとか、つなぐ電源にもよると思いますが、大体１日から３日程度、４０ｌ程度あれば発電機が動かせるのではないかと考えておりまして、今、被害想定でいきますと、大体二。","voiceIndex":348,"id":"exchange-149"},{"speaker":"本多委員","kind":"質問・要望","question":"それでこれは、町会・自治会のどなたも取扱いできるようになってもらいたいと思って質問しているのですけれども、限られた人しか取り扱わないというのでは、いざというときに不備があってもいけないと思いますので、スマートなマニュアルというのでしょうか、例えば混合ガソリンの古い発電機とかがあって、取扱者が限られたりしているものだと、なかなか取扱いの方が限られてしまいますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":350,"id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１４０ページ、減債基金繰入金、それから、１４４ページ、諸収入の貸付金元利収入です。１４０ページの減債基金繰入金についてお尋ねします。以前から減債基金の充当先についていろいろお尋ねしてきました。令和３年の予算書には、空欄ではなく記載されたということで、ありがたく思っています。幾つかお尋ねするのですが、令和３年度の繰入金額は、これまでの繰入金額よりも１桁多いのです。","respondent":"品川財政課長","answer":"ただ、来年度、やはり歳入の状況がかなり厳しいというところがあります。これに対して、令和３年度につきましては、一般の起債の返済分も減債基金のほうでまかなっていくという対応をしている関係から、前年度よりも金額が上がっているというものです。","voiceIndex":352,"id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"質問","question":"とすると、令和３年度に起債償還元金と、一時借入金の利子を除いた起債利子、その合計は１１億９,４００万円ぐらいなのです。減債基金というのは、見込額が７５億円強です。減債基金のほうは７５億円もあるので、どうしてぴったりというか、その４,７００万円分に減債基金繰入金を充当していないのか、そこがちょっと分からないのです。すみません、細かいですがお願いします。","respondent":"品川財政課長","answer":"繰入金というところで、歳入・歳出のバランスを見て、どのぐらい繰入れをするべきかというところの金額から、その後に各基金のほうの配分を決めていくというような形をとっておりますので、そういった中での計算上の結果です。","voiceIndex":354,"id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"以前からお尋ねしていることでもう１つ、一般財源のお話なのですが、この減税基金繰入金は、充当先が今みたいに起債の償還元金と利子に置いています。つまり、財調の基金と同じような性格なので一般財源としているという、これまでの課長のご答弁にもありましたが、そういう認識でよろしいのでしょうか。財政の専門家というお立場で教えていただきたいと思います。","respondent":"品川財政課長","answer":"財政調整基金については幅広く活用ができるという基金になっておりますので、そういう中での一定のルールに基づいた繰入金の額を今回の令和３年度の予算として計上しているというものです。","voiceIndex":356,"id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"確認","question":"それで、目的というか、繰入れ先が決まっているけれども、一般財源扱いというこれまでのご説明は、今、私のほうで幾つか地方財政法のお話をしたのですが、それによって一般財源という扱いになっているという、特定財源という言い方をするとあれですけれども、その辺りは、もう１回確認でお願いします。","respondent":"品川財政課長","answer":"一般財源扱いかですが、使い方というところに関しては、幅広く使えているので、そういうところの部分と解釈しても構わないかということは考えております。減債基金のほうにつきましては、当然限定されていますので、そういった部分での活用ということになっております。","voiceIndex":358,"id":"exchange-154"},{"speaker":"高橋（し）委員","kind":"質問","question":"そちらも別の機会にお伺いします。先ほどご説明にあった減税補てん債なのですけれども、今年度の予算にはもちろん見込みにも書いておりません。先ほど、１０年から数年にわたって行ったということですが、この減税補てん債について、簡単にご説明いただき、そして今年のような税収の見込み、あるいはそれが厳しい状況の中で、その起債について、見込まれるのかどうかというところもお尋ねします。","respondent":"品川財政課長","answer":"現時点で、歳入状況は非常に今厳しい状況ではあるのですが、減税補てん債を上げていくという方向性の考えは、基本的にはございません。","voiceIndex":360,"id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"意見","question":"財政状況の資料にも、品川区は過去に起債されていた減税補てん債は令和８年で完了するというふうに書いてあります。今後も適切に基金の積立てと繰入れを行うようにお願いいたします。減税補てん債についても、機会があればお尋ねしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":362,"id":"exchange-156"},{"speaker":"大倉委員","kind":"質問・要望","question":"７９ページ、住民基本台帳証明手数料、６０ページ、総務使用料、７５ページ、自転車駐車場について伺います。この活用の現況について教えてください。次に、総務使用料のところから集会所使用料、文化センター使用料、公園運動施設使用料について、支払い方法と利用までの流れについて伺いたいと思います。その辺の確認をさせていただきたいと思いますので、お願いいたします。","respondent":"木村戸籍住民課長、古巻文化観光課長、中元スポーツ推進課長、川口交通安全担当課長","answer":"ただ、少し今のオペレーションといいますか、こちらは内部的な話になりますけれども、そちらでいろいろ運用上の課題も正直ございまして。施設予約システム等の関係もございまして、すぐに何か変えられるといったものでございませんし、いろいろなことも含めて。公園運動施設の使用料につきましては、委員ご指摘のとおり、登録団体であれば口座振替に対応していますが。現在、自転車とバイクも収容できることになっております。この台数につきましては、現在、合計で８,６２３台となっております。","voiceIndex":364,"id":"exchange-157"},{"speaker":"大倉委員","kind":"質問・要望","question":"総務使用料の文化センター等の予約システムの関係で、たしか、予約システムは数年前に見直しがかかっていて、そのときには検討されなかったということなのだと思うのですが、今後ぜひ、事前に申込みをしたときにまた支払ってということがないように工夫をしていただきたいと思いますが、要は、二度手間にならないように、１回申し込んで、せっかくインターネットで予約ができるのに。","respondent":"山本情報推進課長、川口交通安全担当課長","answer":"窓口のキャッシュレスにつきましては、交通系ＩＣカード以外のキャッシュレス決済サービスも対応できるように、今、検討を進めているところです。各保管所の収容台数につきましては、現在、八潮北保管所が４,５００台のキャパシティがあります。こちらは平均で、収容台数なのですけれども、１,１０８台の２６％、不動前保管所は５５.３％となっております。","voiceIndex":369,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"それについてどのように見解をお持ちでしょうか。ということは、品川区も、豪雨時の浸水対策に備えて、戸越幹線などの雨水貯留管を何本も造っています。そして工法も同じシールド工法を使って地下を掘削していますので、トンネルの大小はありますが、調布市と同様の工事内容なので、今後、地盤の沈下や隆起や空洞が発生する可能性がこの品川区にもあるということですか。教えてください。","respondent":"松本河川下水道課長","answer":"今、私たちでは、第二戸越幹線という幹線工事を実施しています。今、委員からありました調布市で発生した事故については認識しています。第二戸越幹線につきましては、事故が発生した地盤条件とは異なり、特殊な地盤性ではないということは確認しています。","voiceIndex":373,"id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"こういう事故が発生したということは、シールドマシンの大小はあるにせよ、この品川区でも起きておかしくないのではないですか。ここは絶対安全だと言えるのですか。これをつくるにあたって、品川区は地下３５ｍですが、この幹線工事を進めてきましたが、何を根拠に、今、課長はおっしゃっているのですか。こういうことがあるから絶対大丈夫だと言えるんですか。さらに、継続して調査しているのでしょうか。","respondent":"松本河川下水道課長","answer":"しかし、この下水道工事の受託事業につきましては、昭和６２年から実施してございまして、おおむねトンネル工事と言われるシールド工事につきましては、約９kmやっているところです。この９kmの中で今までこういった陥没が発生したということは聞いてございません。","voiceIndex":375,"id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"地下は実際に見えないですよね。成功しています。もしこれで万が一のことがあったらどうするのですか。学者も言っています。今、半年でもう調査は終わりということですが、そこに住んでいる方は、もうそれで大丈夫なのですか、安心できるのですか。もし何かあったら、それは区で補償してくれるのですか。そして今回これをやってもいいと認可したのはどこなのですか。その辺を教えてください。","respondent":"松本河川下水道課長","answer":"ですので、このシールド工事で発生するようなことは、今回の事故においても、特殊地盤であること、あとシールドマシンに支障が生じて土砂を取り込み過ぎたことによって発生したところですので、今回そういったことがないように。","voiceIndex":377,"id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"でも、それはちゃんと事情は、何かあるかもしれないということは説明しているのでしょうか。ですけれども、これは実際に継続して調査をしなければいけないのではないですか。安全をどうやって保障できるのですか。できないのではないですか。そして、もし賠償問題になったときは、これは回答がありませんでしたけれども、その責任は品川区にあるということですか。その辺について教えてください。","respondent":"松本河川下水道課長","answer":"賠償問題につきましては、瑕疵が施工事業者のほうに本当にあるという場合になれば、請負者のほうの補償になるかですし、原因がはっきりしないというか、原因が特定できないとかという場合には、発注者である品川区。","voiceIndex":379,"id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"皆さんが安心して暮らされている。その中で地下を掘り進んでいる。区でやっていることだから、「私たちは大丈夫よね、安心よね」と思っていると思います。断言できますか。この間の飛行機もそうではないですか。どなたが言い切っているのか分からないけれども、では、絶対区のほうで、もう絶対に大丈夫だというちゃんと保障ができて、そして賠償もきちんとするということでいいのですか。教えてください。","respondent":"松本河川下水道課長","answer":"今お話のありました絶対ということは、やはり私からは、絶対大丈夫だということはなかなか言えないところです。しっかり管理してやっていきたいと考えています。","voiceIndex":381,"id":"exchange-163"},{"speaker":"中塚委員","kind":"質問","question":"１４１ページ、公共施設整備基金繰入金に関わって、歳入減に伴う１０％のマイナスシーリングと、再開発を含め、公共事業の先送りについて伺いたいと思います。昨年の８月に副区長より依命通達が出され、原則１０％のマイナスシーリングが全ての部局に示されました。このマイナスシーリングの対象となり廃止となった、また縮小となった事業はあるのか、それは何か伺いたいと思います。","respondent":"品川財政課長","answer":"マイナスシーリングの件です。令和３年度予算に向けて依命通達を出しました。令和２年度、コロナ禍の中で、８月に依命通達を出したのですが、８月の時点で令和３年度の歳入は非常に厳しいという見込みのもとでシーリングをいたしました。","voiceIndex":384,"id":"exchange-164"},{"speaker":"中塚委員","kind":"質問","question":"お伺いしたのは、マイナスシーリングの対象となって廃止となった、または縮小した事業があるのかないのか、伺いたいと思います。","respondent":"品川財政課長","answer":"事業自体というところについては、やはりまた区の政策等、そういったところを見た形でのやり取りでやっていくものだというふうに考えております。","voiceIndex":386,"id":"exchange-165"},{"speaker":"中塚委員","kind":"質問","question":"つまり、削られた事業はないということです。やはりコロナ禍であっても住民福祉に必要な福祉予算はしっかり確保して、むしろ弱い者を追い詰めている社会なだけに、そこは手厚くすべきだと意見を述べておきたいと思います。この施政方針で述べた一部先送りの経費の特徴とは何か、伺いたいと思います。そして再開発事業ですけれども、緊急性はないと私は思いますけれども、いかがでしょうか。","respondent":"品川財政課長、多並都市開発課長","answer":"一例を申し上げますと、例えばＬＥＤ化工事とか、そういう部分につきましては、緊急性という面から見れば、翌年度に繰り越しても大丈夫ではないかというような判断のもとに、そういった工事の一部を見送って。私からは、再開発事業についてお答えします。区では、老朽化した建物の改築や、または狭い道路の拡幅など、まちの抱える地域の課題を解決するために再開発事業を進めているところです。","voiceIndex":388,"id":"exchange-166"},{"speaker":"中塚委員","kind":"質問","question":"改めて伺いたいと思います。代表質問でも、このコロナ禍の下、ビルや道路やにぎわいをやっている場合なのかと、そこに莫大な税金を使っている場合なのかと、少なくとも今はコロナ対策の予算を手厚くすべきだと伺いました。ここで述べられた配慮ですけれども、一体どのような配慮をしたのか、社会経済の変化にも配慮したとは何を差しているのか伺いたいと思います。","respondent":"多並都市開発課長","answer":"区では再開発事業を進める中で、この事業の性格としまして、検討段階から事業の実施までの間に非常に長期となる事業が多くあります。","voiceIndex":391,"id":"exchange-167"},{"speaker":"中塚委員","kind":"質問・要望","question":"再開発事業を防災対策だと区は様々おっしゃいます。しかもそれが品川を含め首都圏の首都直下型大震災と被害が広域化すれば、避難生活は数か月にわたるわけですから、改めて再開発によるマンションは、また、オフィスビルは防災対策にはならない。コロナ禍であっても、今までどおりにビルや道路を造り続けるお構いなしという姿勢は改めるべきだと思いますが、改めていかがでしょうか。","respondent":"多並都市開発課長","answer":"区といたしましては、誰もが安心して暮らせるように、まちの安全を強固なものにして、環境面を含めた持続可能な住みよいまちづくりを目指し進めているものですので、必要な経費については計上させていただいて、しっかり進めていくという考えです。","voiceIndex":393,"id":"exchange-168"},{"speaker":"中塚委員","kind":"質問・要望","question":"持続可能とよく言ったものだと思います。今のように再開発マンションを造り続け、再開発オフィスビルを造り続け、そのようなまちは、正に持続が不可能だと思います。オフィスビルを縮小、撤退する企業も見受けられます。持続可能とこの場で言うのであれば、それこそ品川区政の根本的な再開発事業優先の姿勢を改めて見直していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":395,"id":"exchange-169"},{"speaker":"大沢委員","kind":"質問","question":"５３ページの児童相談所と、６１ページ、区民集会所をお願いします。５３ページの児童相談所ですけれども、この児童相談所において、一時保護、要は、引き離すということと、落ち着いて戻すという、こういう２つの機能を有するわけですけれども、そこらについて、開所をするにあたって、どのような準備と、どのような検討がされているのか教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":397,"id":"exchange-170"},{"speaker":"大沢委員","kind":"質問","question":"先ほど児童相談所移管担当課長がいらっしゃったので、よかれと思って聞いたのですが、質問を変えて、先に区民集会所からいいですか。区民集会所からいきましょうか。","respondent":"川島地域活動課長","answer":"荏原第一地域センター、当時、荏原第一出張所というふうに言っていた時代ですが、私の認識では、昭和３５年、荏原第一出張所が古い敷地で改築いたしまして、そちらが手狭になったということで、今のところ、小山三丁目２２番のところに。","voiceIndex":399,"id":"exchange-171"},{"speaker":"大沢委員","kind":"質問・要望","question":"当時の私の先代からの話ですと、いろいろとやはり地元の商店街との関わりもあったやに聞いておりますけれども、そこのところをご説明というか、せっかくの機会ですので教えていただきたい。","respondent":"川島地域活動課長","answer":"現状、武蔵小山商店街振興組合と、武蔵小山マンション管理組合と、品川区による区分所有ということで、荏原第一地域センターの１階と２階部分を所有しておりますが、そちらは先ほどの土地が手狭だというふうなところで、区が３億円余のお金を出しまして床を買い。","voiceIndex":401,"id":"exchange-172"},{"speaker":"大沢委員","kind":"質問","question":"そのような中にあって、今度新しくできるわけですけれども、町会のホームページを見ておりますと、町会のホームページから各地域センターの紹介に移りますけれども、地域センター独自のホームページは、何か事情があってお作りになっていないのか、そこの理由があったら教えてください。","respondent":"川島地域活動課長","answer":"独自のホームページというところでは、今、施設の案内とかというところがありますが、今委員がイメージしているのが、いろいろな情報ですとか、イベント等を告知するところがないというようなところだと思いますが、それにつきましては、今年度。","voiceIndex":403,"id":"exchange-173"},{"speaker":"大沢委員","kind":"意見","question":"若年層の町会の加入率も低いということはもうずっと言われていることですけれども、新しく若年層の若い方たち、あるいはニューカマーを引き寄せるには、地域センター独自の、官ではなく民に近いような感覚を持ったホームページ作りが大事だと思うのですけれども、どういうふうにお考えになりますか。","respondent":"川島地域活動課長","answer":"委員のご指摘のとおり、自由度が高く、そして見ていてわくわくするようなページになればというようなところはありますが、ご指摘を踏まえまして、こちらのほうで情報発信する際は、若い方が喜ぶようなもの。","voiceIndex":405,"id":"exchange-174"},{"speaker":"大沢委員","kind":"質問","question":"これは終わります。聞いていないですか。保護するという引き離す機能と、あるいはまた、元へ戻すという機能を、児童相談所は２つ相反する機能を持っているわけで、そこのところをこれから開設準備にあたっての、課題、あるいはいろいろなところをどういうふうにスムーズに移行していくのか、どのような取組がなされているのか、２分以内でお答えください。","respondent":"加島児童相談所移管担当課長","answer":"児童相談所において一時保護した子どもの家庭復帰のケースもしくは分離させるケース、それに向けてどのような準備状況かということですけれども、今、品川区においては、児童相談所、それから子ども家庭支援センターを併存させる方向で検討を行っておりますので。","voiceIndex":407,"id":"exchange-175"},{"speaker":"たけうち委員","kind":"質問","question":"私は、歳入全般と、１５７ページの被災地派遣職員給与費負担金、歳入については今日、令和３年度は非常に厳しいというお話の中で、区民税も厳しい、また財調も厳しいと、いろいろそういうお話を伺って大変身が引き締まるわけですが、その中でこの予算、歳入の部分で、どのような工夫というか、ご苦労をされたのかという大きい話かもしれませんけれども聞かせていただくのと、また、税外収入ということで。","respondent":"品川財政課長","answer":"令和３年度予算に対し、この歳入の厳しい状況の中で、どのような工夫をしてきたかですが、１つは、やはり歳出のほうについて事業の見直し等を行って歳入減に対応しようということでやってきたというところが１つあります。","voiceIndex":410,"id":"exchange-176"},{"speaker":"たけうち委員","kind":"質問・要望","question":"被災地のほうは主な成果を聞いたので、人事課長が来たら教えてください。それから、歳入のほうはいろいろ分かりました。恐らく国とか都のいろいろな補助金とか、いろいろなお金もなるべく使えるものは多く取ろうという、こういう工夫もされたのだと、答弁にはなかったけれどもそう思いました。１０年になりますけれども、その辺の目安というか、予定がもしあったら教えてください。","respondent":"黒田人事課長、品川財政課長","answer":"いつまで続けるかというところにつきましては、これは特別区長会のほうにも東北のほうから首長が要請に参りまして、復興に力を貸してほしいということで、現在も要請がありますので、そういった中では。こういったところも考慮しながら、うまく歳入確保できないかどうかというところは、今後もまた検討していきたいと、このように思っております。","voiceIndex":414,"id":"exchange-177"},{"speaker":"たけうち委員","kind":"質問","question":"新しい予算の中にもそういうものが入っていますけれども、今、各自治体でそういうバス停の命名権といいますか、ネーミングライツ、そこがどういう名前がいいのか、例えば公共施設の近くであれば、そこが分かるような名称がいいので、ネーミングライツというわけにはいかないのでしょうけれども、幾つかバス停を設定する中で、地域の、例えば企業ですとか、また、町会、商店街。","respondent":"鈴木都市計画課長","answer":"やはりコミュニティバスは地域密着、地域に愛されるバスということで、事例として、全てにヒアリングして行ったわけではございませんが、聞いている中で、ネーミングライツを使って命名をしたというところは事例として伺ったことはないのですが、やはりこれから来年度。","voiceIndex":417,"id":"exchange-178"},{"speaker":"たけうち委員","kind":"質問・要望","question":"恐らく東京の中ではあまりないのかもしれないですけれども、結構地方へ行くと、もうそういう形でやっているところがたくさんありますので、ぜひそこは検討してと、要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":419,"id":"exchange-179"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、５２ページ、森林環境譲与税についてお伺いをしたいと考えています。もう１個は、住民の森林、林業に対する理解の醸成。これは、ちょっと私はいろいろ疑問があってこれをやるつもりなのだけれども、例えば校外学習とか、環境交流ツアーみたいな、都市部の人は理解を求めるためにいろいろやってくださいということが一応書かれているわけであります。これはもう確実にとられるということであります。","respondent":"品川財政課長","answer":"森林環境譲与税の件ですが、今、委員からお話しあったとおり、令和３年度予算は３,２００万円程度、活用見込みとして、早川町のマウントしながわ活用事業、それから、大きいところとしましては、児童相談所での間伐材の利用というところがあります。","voiceIndex":421,"id":"exchange-180"},{"speaker":"石田（秀）委員","kind":"意見","question":"他区の事例も、２３区、私も一覧表を見ましたけれども、毎年使わないで基金で積んでいるところも結構多いです。こういうことを、学校まで広げるとすごく難しいし、例えば庁舎とか大きいものだと、これをやるのは、すごく大変なのだけれども、私は常にこれからいろいろな改築、シルバーセンターとかいろいろ出ているけれども、これは、目指してほしいのです。","respondent":"品川財政課長","answer":"こういう技術は、今、年々発達してきているところですので、そういう状況も見ながら、これから公共施設等いろいろ整備していくにあたっては、こういった情報も得ながら、よりよい省エネ、創エネができるような建物を築いていきたいと、このように考えております。","voiceIndex":423,"id":"exchange-181"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1128#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":124107,"voices":425}},{"id":"r03-20210303-10","meetingId":"r03-cm03","date":"2021年3月3日","dateIso":"2021-03-03","committee":"議会運営委員会","time":"午後 ６時０５分～午後 ６時１１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5402#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":2232,"voices":15}},{"id":"r03-20210305-3","meetingId":"r03-c-budget","date":"2021年3月5日","dateIso":"2021-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を192件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年度品川区一般会計予算","agenda":"令和３年度品川区一般会計予算","exchanges":[{"speaker":"湯澤委員","kind":"質問","question":"おはようあります。私からは１６５ページ、ホームページ等経費、それから１７１ページ、成人式経費について質問します。ホームページ経費等については、昨年１１月に品川区の公式ホームページがリニューアルされました。リニューアルを行った経緯と、どのようなところを変更したのか、お聞かせください。","respondent":"大澤広報広聴課長","answer":"緊急情報が自動的に表示されるＴｗｉｔｔｅｒのみを埋め込みとしまして、２４時間３６５日、常に表示されるようにしております。２点目としましては、緊急情報バナーを自由に編集できる仕様に変更しまして、即時対応を可能として、一目で緊急の内容が分かるようにしております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"湯澤委員","kind":"質問","question":"確かに以前のものはかなりトップページの情報量が多くて、巻物のような縦長になっていたかと思いますので、大分すっきりしたと思います。そこで品川区のリニューアルにあたって、他の自治体から参考にしたものや採用したものがあったのか、またリニューアルした際に、区民から寄せられたうれしいご意見や厳しいご意見、そのようなものが寄せられていれば教えてください。","respondent":"大澤広報広聴課長","answer":"区民の反応ですけれども、やはりスマホで見るときに大変に見やすくなったというお声はいただいております。リニューアルしたことでの苦情は、今のところ特にいただいておりません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"湯澤委員","kind":"質問・要望","question":"一方、品川区民がホームページを開くときには明確な目的があって、その目的地に早くたどり着きたいということが求められていると思います。品川区の魅力を発信しつつ検索がしやすい、私はどちらも大切だと思うのですが、区として公式ホームページでは、どういったところに重きを置いて、また、何を強く発信していきたいと考えているか、お聞かせください。","respondent":"大澤広報広聴課長","answer":"しながわ写真ニュースをトップページに表示しておりますが、区の取組みはもちろんですけれども、それだけではなくて、例えば区内の木や花ですとか、風景も紹介しておりまして、区民にも区外の方にも、品川区に関心を持っていただければというふうに考えてあります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"湯澤委員","kind":"質問","question":"現在のチャットボットは分野ごとに導入されていて、総合案内をしてくれるチャットボットがないのですけれども、それは何か理由があってのことでしょうか。今後そういったものを作成する予定があるのか、または課ごとに増やしていく予定なのか。それと、それぞれのチャットボットで文字の大きさや入力のスペースなど、雰囲気が違うように思うのですが、これは製作元が違うのでしょうか。教えてください。","respondent":"山本情報推進課長","answer":"こちらについては運用上の課題等がありますので、現在こういった形にしていますが、総合案内のチャットボットも含めまして、どういった形で運用すれば利用しやすいものになるか、引き続き検討していきたいというふうに考えてあります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"湯澤委員","kind":"質問・要望","question":"区のホームページに入ると、アクセス者全員にチャットボットが案内役としておもてなしをするという機能があったほうがいいかなと思いますので、総合案内のものもあったほうがいいのかなと考えています。チャットボットに名前が付いていると、愛着などが湧くのかなとも思います。このチャットボットは、多言語にも対応しているのかも教えていただきたいと思います。","respondent":"山本情報推進課長","answer":"電話対応の件数ですが、現時点では目に見えて実感できるほどの電話対応件数が減っているというわけではございませんけれども、引き続きチャットボットの周知を行いながら、多くの方にご利用いただけるようにしていきたいというふうに考えてあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ＬＩＮＥの国内利用者数は２０２０年時点で８,６００万人を超えているということで、品川区民もぜひ友達になっていただければ、特に災害等の緊急時に大きな役割を果たすと思います。そこで、現在の登録者数と、これまでの成果や見えてきた課題、また、最終的に目指したい登録者数などがあれば教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"ただ、やはりまだまだの数だと考えていますので、今後も周知に努めて、登録者数、最終的には自治体の人口の１割が登録するとすごいことだというふうに言われていますので、すぐには無理ですけれども、最終的な目標としては。","voiceIndex":14,"id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問・要望","question":"目標も１割ということで、より多くの方に必要な情報提供ができるように、我々の会派としても協力していきたいと考えていますので、ぜひ、高い目標値を持って取り組んでいただきたいと思います。次に、成人式経費についてお伺いいたします。今年は残念ながらリアル開催を見送った成人式でありますけれども、記念品を全部そろえて郵送するとお聞きしております。","respondent":"立川総務課長","answer":"記念品につきましては、当日参加された方に配付するということで、新成人の人数の大体５０％ぐらいを見込んで発注しています。大体１,０００円ぐらいの記念品なのですけれども、追加といたしまして、約１,５００ぐらいということで、１５０万円ぐらいです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"湯澤委員","kind":"質問・要望","question":"最後の質問になりますけれども、今後の成人式ですが、新型コロナウイルス感染症が収束、今、期待されつつも、これからどうなるかはまだ分かりません。来年も今年同様、ぜひリアル開催に向けてできる限りの準備をしていただきたいと考えていますが、区の方針をお聞かせ願えればと思います。","respondent":"立川総務課長","answer":"来年度につきましては、やはりこういった状況が継続する可能性もありますけれども、今年以上に積極的に開催の方向で取り組んでいきたいというふうに考えております。","voiceIndex":18,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"私からは１６３ページ、指定管理者モニタリング、１６９ページ、ＡＩツール運用等経費、１９１ページ、総合区民会館運営費から質問をします。今回、厚生委員会で、指定管理の指定の議案として選定に関わる資料が提示されました。こうした選定情報については、何をどこまで我々議会、ひいては区民へ公表されるのか、現行の規定を改めて教えてください。","respondent":"佐藤企画調整課長","answer":"ただ、選定委員会での率直な意見交換や、応募団体の営業・技術・信用の保護等に配慮するものということで、ただし書を規定しています。","voiceIndex":21,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"その配慮というところは一定理解をするのですけれども、ほかの自治体と比較しても、率直に言って品川区は、ちょっと点数など、そういった情報が少ないのではないかと思います。後でもう少し理由を述べたいと思うのですが、指定管理選考に関しての透明性をもっと、さらに高めていただくためにも、公表項目を増やすべきではないかと思うのですけれども、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"落選した事業者名が特定される場合も考えられるため、落選した事業者の点数や提案の詳細を公表すると、営業・技術・信用の保護に問題が発生するかどうか、今、その辺を見極めて検討しています。","voiceIndex":23,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"課題と相違を認識していて検討しているということです。応募した団体の営業・技術・信用を守るのはもちろん、確かに重要なことではあるのですが、今回、厚生委員会や歳入の審議であえて伺いましたように、例えばエントリーをした団体の審査会でのご発言であったり、報道に関する委員の率直な意見の交換というのですか、意見が、まさに今回の審査選定においての核心部分であるようにも思います。","respondent":"佐藤企画調整課長","answer":"委員ご指摘のとおり、事業者の営業・信用等の保護に配慮しつつ、公表する項目や内容について、さらに検討を進めてまいりたいと考えております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"しかし一方では、今回の件を顧みると、指定管理者制度の根幹に立ち返れば、本来は指定管理者が一定期間、この契約期間を履行した後に、理由を問わず、期限が来れば自動的に公募をかけて、現法人を継続させたほうがいいのか、それとも新たな事業者が適しているのか、そこで改めて審査・選定、そして議会が議決をしていくという姿が、今回の中でも。","respondent":"佐藤企画調整課長","answer":"この間、区といたしましては、指定管理者制度の改正についても様々検討してまいりました。その項目の１つといたしまして、公募によらず指定管理者を選定する場合の回数制限というものを今検討しています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１６９ページのＡＩツール運用等経費のところで、関連して外部人材の活用について伺います。２０１４年に、今からもう７年前になりますけれども、私はこの同じ予算特別委員会の総括質疑で、その当時、これからマイナンバー制度を導入することに対して、ＣＩＯ補佐官というものの任用を求めました。施政方針でも書いてありますけれども、もう少し具体的に教えてください。","respondent":"山本情報推進課長","answer":"区といたしましては、デジタル化をさらに推進していくために、当然内部でのデジタル人材の育成というところに、力を入れてまいりますが、外部人材につきましても、どういった形で活用していくことが最適なのかを今検討していますけれども、引き続き検討を進めします。","voiceIndex":29,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"提案","question":"品川区だけではないです。現在きゅりあんのホームページでご利用の流れというページを見ると、これは当時と変わっておらず、大ホール、小ホール、イベントホールについては、予約の申込み、審査を経て、来館の上申請手続き、施設利用料の支払いを行って、そして利用当日を迎えると、このような流れになっているのですけれども、原則、これはこのとおりでいいのかどうか伺います。","respondent":"古巻文化観光課長","answer":"総合区民会館の運営に関してのご質問ですけれども、原則としましては、委員からご指摘のあったとおり、今、ホームページでご案内しているようなやり方で、来館をしていただいて諸手続きをしていただく、お金の支払いもしていただくといった流れになってあります。","voiceIndex":31,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"確認","question":"たまたまこのご相談された方は、品川区のほかに都内とか、ほかの都市でも大規模な公共施設をよく利用される方でした。本人確認書類のみは、郵送やファックスで提出が必要ですと。施設の予約についても当然インターネットで、これは品川区もインターネットでできます。きゅりあんはいよいよ大規模改修に入るのですけれども、こうしたことについての検討は進んでいるのかどうか、伺いたいと思います。","respondent":"古巻文化観光課長","answer":"システムとの整合性のようなところも、手続き上の整合性もありますので、オンライン決済等が進んでいる時代ですので、今後の課題として認識して、検討を進めてまいりたいというふうに考えてあります。","voiceIndex":33,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後になりますけれども、個別対応はしているということが、ホームページには一切そのようなことは書いてなくて、多分いろいろな、そのような声が上がっているというように品川文化振興事業団の方もおっしゃっていましたので、これはぜひ全体的に進めていただきたいということで、最後に要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"私からは１６７ページ、ＬＩＮＥ公式アカウント運用、１８５ページ、生活安全推進事業、１９９ページ、品川区独自ボランティア「しな助」について質問いたします。初めに新規事業になります、新型自動通話録音機について質問いたします。そこで、最近の犯罪の傾向や動向などをご説明いただけますでしょうか。","respondent":"黛生活安全担当課長","answer":"しかしながら、新聞報道等にもございましたように、昨年、区内で新型コロナウイルス感染症の患者数をごまかした病院から口止め料をもらったのだけれども、これを返さなければいけないなどといって、１,４００万円をだまし取られるという事案も発生しておりまして。","voiceIndex":37,"id":"exchange-017"},{"speaker":"松澤委員","kind":"質問・要望","question":"少し減少しているということが分かります。特にコロナ禍で外出しにくい高齢者は、寂しいという心の隙間をつかれることが大変危惧されております。昨年も質問いたしましたが、抑止効果の高い自動通話録音機を増やしてほしいとの要望に、ほかの自治体との調整もあり、努力していますが難しいとのご答弁がありました。この新型自動通話録音機が導入に至った経緯と、仕組みについてご説明をお願いいたします。","respondent":"黛生活安全担当課長","answer":"これはＮＴＴ東日本が提供するサービスですが、品川区はここにプラスアルファの対策といたしまして、あらかじめ登録しておく連絡先に生活安全担当を加えていただきまして、万一の際は。","voiceIndex":39,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"今、１つ気になったのですが、生活安全担当に通話が行くとするではないですか。そうすると今度生活安全担当の方が、ご家族と会えないときに、多分お電話すると思うのです。大丈夫ですかと。そうすると、逆にその電話が、詐欺かなと思われたりしないのかとふと思ったのですけれども、そのような観点はいかがでしょうか。","respondent":"黛生活安全担当課長","answer":"そのようなことも十分考えられると思います。そこにつきまして、まさに警察に、さらにバックアップ体制として入っていただいて、必ずその方の安全が確認できるようなスキームを構築してまいりたいと考えています。","voiceIndex":41,"id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"詐欺被害に対しても、おっしゃるとおり、これまでも様々な対策が講じられてきましたが、その手口は巧妙化、複雑化しており、被害額も依然として高い水準で推移しているとお聞きしています。そこで、先ほどご説明がありました、この新型自動録音機の試験的導入です。この新型自動通話録音機ですが、これは国や都からの助成金事業ではないのでしょうか。","respondent":"黛生活安全担当課長","answer":"ご提案いただきました認知症対策への応用につきましては、現状直ちにということは、非常に難しいところはあるのかなというふうに考えておりますが、こうしたお声があるということにつきまして、業者のほうにも伝えさせていただいて。","voiceIndex":43,"id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"大変すばらしい取組だと考えています。品川区は、８３運動、まもるっちなど、全国に先駆けて見守り活動の取組に大変実績のある区であります。治安がよい２３区ランキングでも常に上位にある、大変誇り高い地元であると考えています。品川区では、この公式アカウントを取得する際、どのようなプランに加入して、また、このアカウントを取得する際にどれくらい時間がかかるのでしょうか。教えてください。","respondent":"大澤広報広聴課長","answer":"こちらのアカウントの取得までは、やはりＬＩＮＥ株式会社とのやり取りがございましたので、数か月かかっております。","voiceIndex":45,"id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"先ほど湯澤委員への答弁でありましたが、今現在の登録者数が５,７４５人、まだまだ拡大の見込みがあるかなとは思っております。その周知の中で、口コミでの広がりというものがとても効果があるのかなと私は認識しております。例えば各町会長が集まる区政協力委員会の会議など、そういったところでのご案内、また、高齢者クラブへのご案内などを個別に行っているのでしょうか。お聞かせください。","respondent":"大澤広報広聴課長","answer":"ＬＩＮＥの周知につきましては、これまで広報紙やホームページ等での周知が主でございましたので、引き続き従来の媒体を活用するとともに、委員のご提案にありましたような、ピンポイントでの周知というものも、今後検討してまいりたいと考えています。","voiceIndex":47,"id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ大きく広げることもいいのですけれども、ピンポイントで、やはり口コミが私はとても大切だと思っているので、これからもよろしくお願いいたします。ホームページと違い、ＬＩＮＥは、やはり区民がどの情報を求めるか、そのようなところにピンポイントで配信できる強みがあるかなと考えています。そういった視点で、どのような方向性を考えているのか、ご見解をお聞かせください。","respondent":"大澤広報広聴課長","answer":"防災につきましては、今後公式アカウントに追加する予定があります。次にＹｏｕＴｕｂｅの配信ですが、これまでも実績がありますので、より有効な動画を配信するように、積極的に努めてまいりたいと考えています。","voiceIndex":49,"id":"exchange-023"},{"speaker":"松澤委員","kind":"提案","question":"そこでＬＩＮＥの活用や拡充の方法として、１点だけ提案します。渋谷区などはちょっと始めているそうなのですけれども、高齢者の方にＬＩＮＥなど、このネットによる情報の周知が広まるように、スマートフォンの無料貸出し、または安く貸出することはどうかなと考えています。渋谷区は予算をつけております。情報格差を少なくする取組、情報発信の拡充という部分において、ご見解をお聞かせください。","respondent":"大澤広報広聴課長","answer":"スマホにつきましては、今、社会的にも料金の値下げ等も取り沙汰されておりますので、今のところ区からの貸出しは考えておりませんが、高齢者の方へのスマホに関する知識の普及につきましては、必要だと認識しておりますので。","voiceIndex":51,"id":"exchange-024"},{"speaker":"松澤委員","kind":"質問","question":"スマホの所持率が増加しているということは、すみません、私も勉強不足でありました。次にボランティアの部分で、度々の質問になってしまいますが、品川区の独自ボランティア「しな助」、東京２０２０大会のためにつくられましたけれども、しつこいようですが、本当にすばらしいレガシー施策だと考えています。このレガシーを残していくためにも、やはりＬＩＮＥで募集する。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、アンケートを取ったところ、７割以上の方から何らかの形で地域活動といいますか、地域貢献のことはやってみたいというようなお答えもいただいておりますので、改めてどのような形でボランティアを続けていただくのかということで、その中のツールの１つとして。","voiceIndex":53,"id":"exchange-025"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひこの品川区独自の、本当にすばらしいボランティアレガシーを残していただきたいと思います。これからもほかの自治体のよいところを学びまして、区民の欲しい情報、これがピンポイントに伝わり、品川区のこのＬＩＮＥが行政と区民をつなぐ新しいネットワークの中心になるように要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"１７３ページの男女共同参画推進事業より、森前会長の女性蔑視発言について、１９９ページのオリンピック・パラリンピック開催周知事業より、今年夏の開催中止について、それぞれ伺いたいと思います。なぜならば、現実の社会ではいまだに性別による差別、蔑視が根強いからです。そこで今回の女性蔑視発言に対し、なぜここまで多くの方が声を上げたと思うのか、区の見解を伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"区は、人権尊重都市品川を宣言しております。長期基本計画をはじめ、マイセルフ品川プランを進めている中で、この言動はあってはならない、とても残念な発言だったと思いますし、一層推進を進めてまいりたいと考えているところです。","voiceIndex":57,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"これまで組織の中で、また社会や家庭の中で、どれだけ女性は口を出すなという言葉が繰り返されてきたでしょうか。ジェンダーギャップが世界１５３か国の中で１２１位の日本社会だけに、直ちに克服すべきだと思います。改めて、森前会長の発言は明らかに女性蔑視であり、社会のあらゆる場面で克服されるべきだと思いますが、改めていかがでしょうか。","respondent":"島袋人権啓発課長","answer":"残念ながら今年度ですが、コロナ禍の影響で開催することができませんでしたけれども、また新たな委員を募集しています。少しずつではありますが、応募の方も出てきておられる状況です。一層推進してまいりたいと考えているところです。","voiceIndex":59,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ一層推進いただきたいと考えていますし、この根強い差別を克服する、この取組を力強く進めていただきたいと思います。しかし、本当にこの発言には怒りの声が広がりました。先ほどあってはならないという発言でありましたが、改めてこれは性差別だと、女性差別だと私は思いますが、この点ははっきりとご答弁いただければと思います。","respondent":"島袋人権啓発課長","answer":"ジェンダー平等ということですけれども、こちらに関しましては、やはり性別に関わりなく尊重され、個性を、あるいは能力を発揮できる社会が重要ということで、やはりしっかりと全ての区民の方にジェンダー平等意識を持っていただけるように。","voiceIndex":61,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひジェンダー平等の意識の醸成をより進めていただきたいと思いますし、私はこの発言は性差別、女性蔑視だとしっかりと発言していただきたいと考えています。女性蔑視が根強く残る社会の中、コロナ危機が社会を大きく襲いました。痴漢は犯罪です。ジェンダー平等社会へ、日常のあらゆる場面での克服が一層広がっていると思いますが、同じ角度の質問にはなりますけれども、ご見解を伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"無意識のうちにつくられてきた偏見が差別につながらないように、やはりしっかりと、人権啓発課といたしましても、様々な機会を捉えて推進をしていくことが重要だと思いますし、それをすることが人権尊重都市品川を一層進めることにつながると考えております。","voiceIndex":63,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"私自身の中にも、まだまだ反省すべき点はきっとあると思います。次に、夏の東京２０２０大会の開催中止についてです。この予算特別委員会もそうです。しかし、新型コロナウイルス感染症が世界中に広がる中、開催中止を求める声は、日本だけではなく各国に広がっております。そこで、安全・安心とはどのような条件が整う場合を指すのか、その基準を伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"新型コロナウイルス感染症が広がる前に、そもそも東京２０２０大会に向けた東京都安全・安心推進会議というものを東京都でやっておりまして、その中では、関係者が生命・健康の確保、それから生活や社会機能を維持する。","voiceIndex":65,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"今のお話ですと、健康の維持、あと社会の安定が維持されない下では、東京２０２０大会は開催すべきではないと。私はそう思うのですけれども、品川区はいかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、社会機能が維持された状態を目指すために、その状態で開けるように、今、順次準備を重ねているところです。","voiceIndex":67,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"率直に言って難しいということが多くの方の思いだと思います。東京２０２０大会が感染爆発の要因となることは最悪の事態です。選手間のフェアな環境が整わず、安全・安心もないままに開催が前提ということは改めるべきだと思います。改めて今年夏の東京２０２０大会の開催中止を品川区として求めていただくよう要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"私からは１９１ページ、フィルムコミッション事業、１６５ページ、広報経費、１６９ページ、しながわＷｉ－Ｆｉスポット事業、１７３ページ、男女共同参画推進事業についてお伺いいたします。少なくとも私はあまり知らなかったのですが、どのような方法で周知をされていたのでしょうか。","respondent":"古巻文化観光課長","answer":"Ｔｗｉｔｔｅｒドラマの件ですけれども、周知に関しましては、ちょっといろいろなタイミング等も図りながら進めていたところですが、ＳＮＳを使っての周知と、あと、マスコミを集めてのお披露目のような機会を設けまして、大森の映画館になりますけれども。","voiceIndex":71,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"特に、今回このドラマで、品川区内の１１か所、ロケーションを回っておりますけれども、このコロナ禍だからこそ、マイクロツーリズム的な、近場で１時間ぐらいで回れるようなところ、コロナ対策でも、近所を散歩するとか、運動でランニングするということは、認められていることなので、こうしたコロナ禍だからこそ、ドラマを見て、ではこの１１か所のロケーション、ちょっと今日走ってみようかとか。","respondent":"古巻文化観光課長","answer":"今後につきましては、ＹｏｕＴｕｂｅ等へ掲載、登録をさせていただいて、しなロケのホームページでも紹介をしていきたい、このように考えてあります。","voiceIndex":73,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"広報しながわなどでも、本当にちょっとしたスペースに載せてもいいかなと思いますので、ぜひその辺りも含めてご検討よろしくお願いします。これ、私も、ほかの委員の方も結構定期的におっしゃっていることなのですけれども、今後の新聞購読者減に伴う対応はいかがお考えなのでしょうか。","respondent":"大澤広報広聴課長","answer":"ただ少なくなっているので、令和３年度からスポーツ紙への折り込みを新たに始める予定がございまして、それが５,２００部ですので、それを合わせるとこれまでの水準を保てるかと考えています。","voiceIndex":75,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"ただ、このＬＩＮＥ公式アカウントのＰＲ方法が、先ほど広報しながわでやられているということで、これは結局、卵が先か鶏が先かというような話になってしまいますけれども、ぜひＬＩＮＥ公式アカウントのほうは、先ほど町会などにピンポイントでご案内するという方法もしていくということなのですが、例えば町会の掲示板に大きくＱＲコードなどを掲載して。","respondent":"大澤広報広聴課長","answer":"ＬＩＮＥ公式アカウントにつきましては、委員のご提案も含めまして、できるだけ様々な方法で周知に努めてまいります。","voiceIndex":77,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"続けてしながわＷｉ－Ｆｉスポット事業に移りますけれども、今ＳＨＩＮＡＧＡＷＡ ＦＲＥＥ Ｗｉ－Ｆｉをしていると思うのですが、ホームページで通信可能エリアを見ますと、公園などで、楕円形とかの円の範囲内、この範囲で通信できるということなのですけれども、この範囲から抜けてしまった場合、例えば角度でいえば９０度の範囲でしかならなくて、残りの２７０度。","respondent":"山本情報推進課長","answer":"各スポットでその範囲を広げるとなりますと、アンテナの増設が必要になりまして、その際には電源の確保であったり、ケーブルの敷設工事等が必要になりまして、設置できる場所というものはかなり限定されておりますので、今のところ増設が難しいという現状です。","voiceIndex":79,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"１つ気になったのが公園で、なぜか池田山公園にＷｉ－Ｆｉが設置されていないのですけれども、この池田山公園は、品川区の観光の１つの名所となっておりますし、それこそ、しなロケにも掲載されている公園です。ぜひ池田山公園にもＷｉ－Ｆｉを設置していただきたいのですけれども、その点についていかがお考えでしょうか。","respondent":"山本情報推進課長","answer":"池田山公園は、観光地として非常に人気があるスポットというふうには考えてありますので、その辺りの整備については、関係課とともに考えていきたいと思ってあります。","voiceIndex":81,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"続けて男女共同参画推進事業で、いわゆる同性パートナーシップ制度についてお伺いしたいと思うのですけれども、令和２年度におきましては、港区、文京区が同性パートナーシップ制度を導入されて、足立区では区議会議員の方が問題発言をされましたが、その足立区でも令和３年度から同性パートナーシップ制度を導入されるということなのですけれども、こうしたほかの自治体の動向を受けて。","respondent":"島袋人権啓発課長","answer":"この中でどのような報告が上がってくるか、またその報告を鑑みながら、検討を進めてまいりたいと考えているところです。","voiceIndex":83,"id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。このままではほかの区に引っ越してしまうよ」などと、そのように冗談で言われることもあるのですけれども、ほかの自治体において、同性パートナーシップ制度はどんどん進んでおりますので、そうした会議や有識者の方のお声など聞いて、ぜひそうした制度の導入の検討をしていっていただきたいと思うのですが、その点いかがお考えでしょうか。","respondent":"島袋人権啓発課長","answer":"こちらは、区職員・教職員となっておりますが、企業の方にも参考にしていただきたく作成したものです。一層の理解推進が進んだ中で、検討してまいりたいと考えているところがあります。","voiceIndex":85,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは１６３ページ、予算関係管理費、１６５ページ、ホームページ等経費、１６９ページ、情報公開等経費、情報化推進費、タブレットのことを伺います。１７３ページ、男女共同参画推進事業、１７７ページ、庁舎等管理費、庁舎計画費、できるところまで伺います。ぜひ議員からの事前要望には応えていただきたいのですが、いかがでしょう。委託業者の問題なのか、その辺について伺います。","respondent":"品川財政課長、中山会計管理者","answer":"そのような中で、細かい点で、やはりその両者の表示する項目の解釈とか、そういったところに少し違いが出ておりまして、前年比、前年と本年とを比較した形で出すとなると、その項目で出ている項目自体が。令和元年度から、財務諸表を分かりやすくしたいということで、概要版も作成いたしまして、そちらも併せて載せておりますので、ご覧いただければと考えています。","voiceIndex":88,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"事前の議員からの、例えばこのような資料も欲しいという要望には応えていただきたいと思うのですが、その点についてお答えがなかったので、もう一度伺います。なぜでしょうか。今回は適切な情報、多くは文書や電磁的記録になるのだと思うのですが、その作成と、それから品川区情報公開等審議会の意見の尊重を求める立場から質問をいたします。この審議会の結論も尊重されるべきと考えますが、見解を伺います。","respondent":"中山会計管理者、大澤広報広聴課長","answer":"注記につきましては、来年度の決算、令和２年度の決算のときに併せて、しっかり財務諸表と出せるようにしていきたいと考えております。よろしくお願いします。現在、システムを管理している事業者と、どのようにしたらアップすべき日を更新日として出せるかというところを検討しています。","voiceIndex":91,"id":"exchange-043"},{"speaker":"吉田委員","kind":"提案","question":"情報公開です。今まで広町地区の再開発のこともありましたけれども、公開できないものがあるのであれば、きちんとした情報を、区として公開できる内容の文書を、区民に対する説明の文書を用意していただきたいと思いますが、もう一度見解を伺いたいと思います。それから、次に行ってしまいます。事業者とクラウド型通訳サービス利用契約を５年契約で結んでいるということで、仕様書の中身も確認いたしました。","respondent":"大澤広報広聴課長、山本情報推進課長","answer":"情報公開に関してですが、広報広聴課には、各所管から様々相談がありますので、ケースに応じて丁寧に対応していきながら、制度の趣旨を伝えてまいりたいと考えています。掲示の内容ですけれども、１３言語対応ということで、１３言語でサービスができますというところをご案内しているということと、あと手話マーク等々も記載をしています。","voiceIndex":94,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"情報公開は、適切な文書が用意されていないと、そこに個人情報が載っているということで全て非公開にされるのが今の制度ですので、きちんと適切な文書を公文書として用意されることを要望しておきます。啓発講座・交流スペース「みんなのひろば」開催は、昨年より大分予算が増えておりますが、拡充は評価したいと思いますけれども、前年の成果、あわせて次年度の意気込みなどを伺いたいと思います。","respondent":"山本情報推進課長、島袋人権啓発課長","answer":"通訳タブレットの掲示ですが、繰り返しの答弁になりますけれども、こちらのほうはもう既に窓口に掲示をしていると認識しています。その際には障害者福祉団体にも、内容は確認をしてもらっているところです。性の多様性の講座も啓発講座の１つです。交流スペース「みんなのひろば」ですが、今年度実施しました１２月１２日分は、応募者３名、参加者３名、２月１３日分は、応募者１０名、参加者６名でございました。","voiceIndex":97,"id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"今日も戸籍住民課のところを通ってきたのですけれども、ちょっと見当たらなかったので、改めて確認させていただいて、また何か意見を言わせていただきます。その立場で質問をしますが、簡易型プロボーザル方式要領についている想定業務仕様を確認しましたけれども、基本構想検討だけでも６項目にわたって相当な内容です。少し急ぎ過ぎではないかと思いますが、見解を伺います。","respondent":"濱中庁舎計画担当課長","answer":"その中でも、これまで様々な庁舎機能検討委員会の議論であったりですとか、その前には区議会での議論、庁内での議論を重ねてまいりましたので、そういったものを基本構想としてまとめ上げていくというところで、７月までに素案をまとめてパブリックコメントを行ってから。","voiceIndex":100,"id":"exchange-046"},{"speaker":"木村委員","kind":"質問・要望","question":"私からは１６３ページの上から４行目、しながわテレビ・プッシュ普及促進事業、１７５万円余からです。最初にこの名前を見たとき、ちょっとびっくりしましたけれども、このプッシュとは押すという意味ですが、なぜこの名前を使用したのか、このプッシュすることで何を区民に伝えていきたいのか、私的には「えっ」と思いましたが、特別な意味があれば教えていただきたいと思います。","respondent":"佐藤企画調整課長","answer":"それ以外にも、電車の運行情報でございましたり、自治体が発信する生活情報等もお知らせする、幅広いサービスとなっております。","voiceIndex":103,"id":"exchange-047"},{"speaker":"木村委員","kind":"質問","question":"自動的に立ち上がる、そのような意味でプッシュという名前がついたのだろうと思います。１６５ページの下から２行目にありますけれども、ＦＭしながわ広報番組制作費１,２００万円ですが、このチャンネルは品川区のチャンネルですけれども、品川区の専門チャンネルではなく、時間帯を使用しているということでよろしいのでしょうか。","respondent":"大澤広報広聴課長","answer":"ＦＭしながわの中で、「ほっとラジオしながわ」として、月曜日から金曜日まで、１１時から３０分間、夜１０時、２２時から３０分間の枠で、区の広報番組を流しています。その経費です。","voiceIndex":105,"id":"exchange-048"},{"speaker":"木村委員","kind":"意見","question":"最初からずっと品川区の番組ではないということで、午前と、そして午後の３０分、１時間を本区の専用時間としているということですけれども、この始めるきっかけは何でしたか。年間の使用料が１,２００万円ということですが、失礼な言い方ですけれども、どれだけの価値があるのかなと、このように思います。お答えください。","respondent":"大澤広報広聴課長","answer":"感染症予防について区長のメッセージを放送したときには、区長からのメッセージはかなり説得力があるというような声も届いておりますので、一定のリスナーの方からの評価はいただいているというふうに考えてあります。","voiceIndex":107,"id":"exchange-049"},{"speaker":"木村委員","kind":"質問・要望","question":"区外の人たちから見たときに、品川区というのは本当に住みやすそうだとか、住んでみたいと思わせる、また、品川区はこのような区なのだと、品川区のよさをアピールするための手段と考えますけれども、それでよろしいのかどうか。そしてまた、これからもこの番組を長く続けていただきたいと思いますけれども、お願いをしたいと思います。","respondent":"大澤広報広聴課長","answer":"番組の中では、教育長が出演して品川区の教育制度の説明などもしております。","voiceIndex":109,"id":"exchange-050"},{"speaker":"木村委員","kind":"質問","question":"私もチャンネルを回していて、品川区という声や、また品川区の映像が見えたり、聞こえたりすると、何となくほっと安らぎを感じるのですけれども、純粋に品川区だけの専門チャンネルにするには莫大な資金が必要になります。年間１,２００万円の費用でありますが、妥当とお考えでしょうか。お聞かせください。","respondent":"大澤広報広聴課長","answer":"１,２００万円の内訳ですけれども、制作費として約４万６,０００円の２６０日分ということで計上しています。こちらの金額は妥当な金額というふうに考えてあります。","voiceIndex":111,"id":"exchange-051"},{"speaker":"木村委員","kind":"質問","question":"ぜひ区民の心を癒す番組をお願いしたいと思います。次に１６７ページの上から２行目、外国語版ラジオ広報番組からですけれども、多くの海外の方が、今品川区には約五、六千名ほどの外国人が住んでいるということをお聞きいたしました。それとも視聴率は関係なく、品川区のことをできるだけよく知ってもらうためにこの放送を流しているということでしょうか。簡単にお答えください。","respondent":"大澤広報広聴課長","answer":"ラジオは視聴率が取れませんので、どのくらいの方が聞いていらっしゃるかということはちょっと把握していないのですが、インターＦＭの内容をそれぞれの外国語でホームページに載せていますけれども、それへのアクセスが月８,６００件ありますので。","voiceIndex":113,"id":"exchange-052"},{"speaker":"木村委員","kind":"質問","question":"聞くところによりますと、小学生のほとんどはこの曲を知っているともお聞きをいたしました。ということは、やはり小学生は踊れるのでしょう。これは音楽の授業などで使用しているということでよろしいのかどうか、そこのところをお聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"しかし、オリンピック憲章は、性差別を含めたあらゆる差別の是正を求めています。オリンピックという世間の注目を集める機会こそ、差別・偏見の是正につなげる好機であり、啓発というように言っているわけですから、各啓発事業を行う際には、オリンピック憲章の理念を盛り込んでいくべきだと考えますが、区の見解をお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それはもうオリンピックが、スポーツの祭典に限らず、文化の祭典でもあるという面もありますし、文化事業をやるとき、または教育の場、あらゆる場でオリンピック憲章というのは有効に活用することができる内容だというふうに認識しております。","voiceIndex":122,"id":"exchange-054"},{"speaker":"松本委員","kind":"提案","question":"都市型観光プラン推進事業について伺います。水辺の利活用は、様々な委員から提案がありますので、私のほうからどこまで言えるかということはあるのですけれども、１つ申し上げたいと思うのが、２０２５年に大阪市で万博が開かれますけれども、その開催地の夢洲で、５月４日に日本最大級の花火を打ち上げるというような、オンラインショー型の花火「レッツゴー万博２０２５」が開かれる予定です。","respondent":"古巻文化観光課長","answer":"具体的にどのように使うのかということは、今の委員のご提案も含めて、観光面で何か活用できるものがあれば、うまく活用していくことも１つの発信の手段かなというふうに考えますので、ちょっとまだ具体的に何も言えないですけれども、十分に研究してまいりたいなと。","voiceIndex":124,"id":"exchange-055"},{"speaker":"松本委員","kind":"質問","question":"それで、昨日報じられているところだと、ミャンマーでは、抗議デモで既に５０名程度ですか、５０名を超えた死者が出ているということで、今後もその大使館周辺で、品川区の大使館のほうで活発な抗議活動が行われる可能性があるのですけれども、この辺について大使館との間で何か話し合いが行われているのか、また、その安全面での対応がどうなっているのか、お願いいたします。","respondent":"宮澤協働・国際担当課長、黛生活安全担当課長","answer":"ミャンマー大使館の件です。デモ等が行われていることは把握しておりますが、その件についての大使館との連絡等はしておりません。本件につきましては、所轄の品川警察署と情報を共有し、的確に対応してまいります。","voiceIndex":126,"id":"exchange-056"},{"speaker":"松本委員","kind":"意見","question":"これからまたいろいろと活発になる可能性があるので、ご留意いただければと思います。一方品川区には、過去のデータを見るとミャンマーご出身の方が２００人以上いらっしゃるということで、こちらにまた、恐らくいろいろと心配な、精神的にもストレスを抱えていらっしゃるかと思いますので、そちらは区のほうでも住民ということで、しっかりとご対応いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問","question":"私からは１９８ページ、オリンピック・パラリンピック開催周知事業についてお伺いいたします。当初から、東京２０２０大会の提唱してきた復興五輪というものを非常に強く感じています。それに関しては、もちろん議会も、行政も、全力を挙げてできる限り尽くすということが、まず我々の役割だと思いますけれども、初めにそれについてご見解をお聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大会組織委員会を中心に、聖火リレーをどのように安全に実施することができるかということで、ブロック別に分けまして、そのときの緊急事態宣言があるかどうかとか、新型コロナウイルス感染症の状況も見ながら実施するというふうに聞いております。","voiceIndex":131,"id":"exchange-058"},{"speaker":"芹澤委員","kind":"質問","question":"そうすると、例えば観戦というところでいうと、ウェブ上で見るような仕組みづくりを支援するということも、取組の１つとしてありなのかなと思いました。もちろんケーブルテレビでできれば、それがベストですけれども、放映権などで多分なかなか難しいのだろうと思っていますので、今民間サイトで、東京２０２０大会だけではなくて、五輪の無料のストリーミングサイトというものが幾つかあると伺っています。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それと、例えばＹｏｕＴｕｂｅで見るだとか、そういったことになりますと、委員ご指摘のとおり、やはり放映権の関係がございまして、多少難しいところがあるかなというふうな認識です。","voiceIndex":133,"id":"exchange-059"},{"speaker":"芹澤委員","kind":"質問・要望","question":"レガシーについても伺います。レガシーということで、もう様々な政策が東京２０２０大会開催前に出来上がってきているのかなと思っています。これがオリンピック・パラリンピックが終わった後、どこの予算に入ってくるのかをお聞かせいただきたいと思います。あわせて、先ほど「しな助」のお話が議論として出ていました。「しな助」では、今年どういった事業を行う予定なのかもお聞かせください。","respondent":"中元スポーツ推進課長、辻オリンピック・パラリンピック準備課長","answer":"東京２０２０大会後のレガシーの障害者スポーツの予算の枠組みですが、ちょっとまだはっきりと決まったわけではございませんけれども、１９５ページのほうに障害者スポーツの充実という項目がありますので。来年度は、年度が明けましたら、まず大会のときの運営補助に関わっていただく方への説明会等を予定しております。今年度中にオンラインで「しな助」の心構えですとか、ユニバーサルマナー研修などを開く予定です。","voiceIndex":135,"id":"exchange-060"},{"speaker":"芹澤委員","kind":"提案","question":"障害者の予算関係ですけれども、東京２０２０大会が開催される前から予算というものはあったのですから、この東京２０２０大会の開催を契機に、合算した額にするのはなかなか難しいと思いますけれども、ぜひより大きな額でレガシーとして残していただければと思います。何というか楽天などのショッピングサイトなどだと、利用するとどんどんメルマガが増えていくという感じでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"「しな助」の活動や今後の展開方法については、柔軟にいろいろな方面で展開していきたいと考えています。","voiceIndex":138,"id":"exchange-061"},{"speaker":"新妻委員","kind":"質問","question":"１６７ページ、ＬＩＮＥ公式アカウント運用、１７３ページ、啓発講座・交流スペース「みんなのひろば」開催、１７８ページ、地域活動費に関連いたしまして、しながわ発見出会い事業、そして２０３ページ、住民異動届書作成ツール利用料、順不同で伺ってまいります。このことについて、なぜなのか、まずお伺いいたします。","respondent":"川島地域活動課長","answer":"こちら、コロナ禍の終息の見込みが立たないというところもございまして、令和３年度の予算要求は休止という形で、予算要求していないというものです。","voiceIndex":141,"id":"exchange-062"},{"speaker":"新妻委員","kind":"提案","question":"分かりました。コロナ禍であればこそ、できるやり方というものを提案していただくのが事業者ではと考えています。これまでの事業を振り返ってみてどうだったのかという評価と、また、今回予算が計上されなかったことで、今後もなくなってしまうのではと心配をしております。このような中だからこそ、行政の支援というものが非常に大事だと考えておりますが、見解を伺います。","respondent":"川島地域活動課長","answer":"コロナ禍の終息の状況を見ながら、ほかの自治体でやっている様々な手法ですとかを、事例収集などをしながら、新しい企画の研究もしていきたいというふうに考えてあります。","voiceIndex":143,"id":"exchange-063"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。続いて、ＬＩＮＥ公式アカウント運用と在住外国人向けのＬＩＮＥ情報発信について、一緒に伺わせていただきます。午前中の質疑の中で、このＬＩＮＥの件は多々確認をさせていただきました、６,０００人弱が登録をしているということで、もう少しまだ登録者の人数を増やす余地があるというお話も伺いました。","respondent":"大澤広報広聴課長、宮澤協働・国際担当課長","answer":"ＬＩＮＥの登録数につきまして、全体を調査してはございませんけれども、活用がかなり進んでいると言われている渋谷区では、今２万を超えていると聞いておりますので、品川区も目標にして頑張っていきたいと考えています。在住外国人向けのＬＩＮＥの情報発信についてお答えいたします。こちらは品川区の公式アカウントとは別に、やさしい日本語、また英語で配信するためのアカウントを取得して、情報を配信していく予定です。","voiceIndex":145,"id":"exchange-064"},{"speaker":"新妻委員","kind":"確認","question":"外国人向けのＬＩＮＥの情報発信は、別でということを確認させていただきました。やさしい日本語、また英語ということは、英語がまず前提であって、そこから多言語も検討されるのでしょうか。品川区には約１万３,０００人ちょっとの在住外国人がいらっしゃると思いますが、基本、英語がベースであったとしても、中国語や韓国語も必要になってくるかと思いますが、いかがでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"在住外国人向けのＬＩＮＥの発信におきまして、やさしい日本語、英語で発信していきます。配信していく中で、登録者数、また、ニーズ等を検討しながら、考えていきたいと考えております。","voiceIndex":148,"id":"exchange-065"},{"speaker":"新妻委員","kind":"質問・要望","question":"区内には１１か所の大使館等もあります。そして、次に住民異動届書作成ツール利用料について、確認、お伺いをします。昨年の９月から運用開始されて、本格運用がこの２月からということでよろしいでしょうか。本格運用から１か月ちょっとですが、これまでどうやって周知をされてきたのか、これまでの利用者数と、また、この１か月間の評価をお聞かせください。","respondent":"木村戸籍住民課長","answer":"周知に関しましては、ホームページ、それからＬＩＮＥのチャットボットを通じてですけれども、お知らせをしてきたところです。２月の利用ですが、合計で約１００件、１日５件程度ご利用いただいているところです。","voiceIndex":150,"id":"exchange-066"},{"speaker":"新妻委員","kind":"質問","question":"「あっ、このようなものがあるのだ」ということを、区役所に来た人にも分かりやすいような、目立つようなアピールをぜひお願いしたいということと、民生費で予算化されております高齢者社会参加促進事業に、パソコン・タブレット・スマホ教室があるかと思いますが、このような中でも、今このように書類を取るのに簡単にできるのだということを。","respondent":"木村戸籍住民課長","answer":"今、委員からご指摘のありましたことも踏まえまして、アピール強化、関係課と連携して進めたいと思います。","voiceIndex":152,"id":"exchange-067"},{"speaker":"新妻委員","kind":"確認","question":"最後に、啓発講座・交流スペース「みんなのひろば」開催についてお伺いいたします。午前中にも参加状況等の確認をさせていただきました。パートナーシップ制度の導入ということも、ほかの委員からも出ておりました。先ほどからもお伺いしておりますが、今後の具体的な取組をもう少し詳しくお聞かせください。","respondent":"島袋人権啓発課長","answer":"こちらは、今年度実施しました２回と同じく、令和３年度も２回予定しています。こちらのほうは、先ほどありましたように、アライの方も含めてもっともっと広めていくように、そしていろいろな年代の方々が参加できるような形で進めてまいります。","voiceIndex":154,"id":"exchange-068"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは１６９ページ、ＩＣＴ推進管理経費、１７３ページ、男女共同参画推進事業、１８１ページ、協働推進経費、１８７ページ、社会を明るくする運動経費、１９１ページ、文化活動支援事業についてお伺いいたします。１点目に、男女共同参画推進事業についてお伺いいたします。分かりやすく載せていただきたいと要望いたしますが、区のご見解をお聞かせください。２点目も行きます。","respondent":"島袋人権啓発課長、川島地域活動課長、古巻文化観光課長","answer":"それと女性の人権に関する問題、若い女性を含めてのことですが、今後の検討課題とさせていただきたいと考えているところです。社会を明るくする運動につきましては、法務省が主唱しております全国運動ということで、啓発活動と、それから青少年の表彰を実施しているものです。具体的にどのような形でということは、まだそういった話のまとまりはできておりませんけれども。","voiceIndex":157,"id":"exchange-069"},{"speaker":"横山委員","kind":"質問・要望","question":"社会を明るくする運動についてなのですけれども、昨年１０月にドキュメンタリー映画『記憶』の中村すえこ監督にお話を伺いました。４点目なのですけれども、協働推進経費についてお伺いをいたします。区民、企業などとの協働事業では、事業完了後にも区の支援が必要な場合、区と連携しながら事業が継続できるような仕組みになっておりますでしょうか。実際にどのような事例があるのかを教えてください。","respondent":"川島地域活動課長、宮澤協働・国際担当課長","answer":"そういった活動、様々な活動の中に、いろいろな新しいことを取り込んでいくということは、活動の幅を広げるという意味では有効なことではないかと考えていますが、その辺のところもまた保護司会とお話をしながら。地域活動を行う団体の資金状況であったり、広報戦略であったり、または団体の活動するミッション自体の相談というものも受けていきながら、協働しながら進めているところです。","voiceIndex":161,"id":"exchange-070"},{"speaker":"横山委員","kind":"質問・要望","question":"最後にＩＣＴ推進経費についてお伺いいたします。電話番号を持たずに、Ｗｉ－Ｆｉを使ってＬＩＮＥなど無料アプリからの相談や、スマホからの電子申請しかできないような若者たちがいるという状況につきまして、区としてはどのように捉えておられますでしょうか。全庁的なＩＣＴ化を強化していただきたいと思うのですけれども、簡単に進め方をご説明ください。","respondent":"山本情報推進課長","answer":"ＩＣＴ化の進め方ですが、確かに年代によって様々、使い方、使う媒体等が変わってくるというふうには考えてあります。区といたしまして、若い方から高齢者の方まで様々活用いただけるよう、デジタル化は推進していきたいというふうに考えてあります。","voiceIndex":164,"id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは１７７ページの庁舎計画費の基本構想・基本計画検討経費、策定費から、庁舎の建て替えについて伺いたいと思うのですけれども、令和２年度は庁舎機能検討をしていくということで、庁舎機能検討委員会で議論をされてきました。議論としては、とても不十分だと思っていますけれども、３月の５回目で答申を出して終了ということなのでしょうか、伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"私から、庁舎機能検討委員会の状況と今後の策定委員会について、ご説明差し上げたいと考えています。庁舎機能検討委員会ですが、１月２２日、緊急事態宣言の発出に伴いまして、書面開催とさせていただきまして、委員の方々に資料を提示して、その後様々な意見を集約しています。","voiceIndex":167,"id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ＪＲ東日本の開発と一体となっていることなどから、Ｄ案を前提に進めるべきではないということを繰り返し求めてきました。さらにＤ案敷地は８,３００m2と、現在の庁舎の１万３,０００m2に比べると狭い敷地なので、おのずと高層の庁舎になってきます。この役所を超高層にすることのメリット、デメリット、区の考えを聞かせていただきたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"高層の場合どういったメリット、デメリットのようなものがあるかということも、また検討していくことになると考えております。","voiceIndex":172,"id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"Ｄ案という敷地を前提に進めているということは、超高層になるということも前提だと。一般質問でも否定していないわけですから。ですので、超高層になることでのメリット、デメリット、これを想定しておくのは当然のことではないかなと思うのですけれども、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"高層の場合と低層の場合といったものを、今後機能の規模を決めていく中で、高層にした場合、低層にした場合、どういったメリット、課題等があるのかというものを、また基本構想や基本計画段階等で専門の業者等の知見を生かしながら、議論をするです。","voiceIndex":174,"id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしましたら、低層型の庁舎というものも検討されるということでよろしいですか。","respondent":"濱中庁舎計画担当課長","answer":"機能のほうを決めまして、想定規模の面積を決めます。今候補地となっているところにどういったものが建つのかというものが見えてから、そういった、どのような構造の庁舎になってくるかを検討していくことになります。","voiceIndex":176,"id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとあわせて、区は、この高層にするべきではないという共産党の質問に対して、東京消防庁からもエレベーターを使った避難イメージ等の基準も出しておりますので、そうしたものを参考にしていきたいというふうに言っているのですけれども、私が調べたところ、これは火災時です。この大地震のときの、こうした避難イメージ、そうした基準も出ているのでしょうか。伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"今後、面積は検討事項になってくるかと思っています。高層であろうと、低層であろうと、防災の拠点であるとか、来庁者等が災害時に安全を確保できるような設備の導入は、計画していかないといけないと考えています。","voiceIndex":178,"id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりＤ案という狭い敷地に超高層の庁舎という前提はやめていただいて、区民のための安全な防災の拠点として、しっかり機能する庁舎の建設を強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-077"},{"speaker":"田中委員","kind":"質問","question":"はい、関連です。具体的に可能であるのかということと、区民意見の反映やこの２つの業務委託と整合性をつけることを考えると、少しじっくりと進めるべきだと考えますが、見解を伺います。それで、床面積の部分なのですけれども、検証というのは、今もう区として具体的にこのぐらいの面積というものがあるのか、それとも全てひっくるめてプロポーザルで公募しているのかという部分についてお知らせください。","respondent":"濱中庁舎計画担当課長","answer":"１点目のオフィス環境の調査ですが、こちらも現状の調査、窓口の調査等を通しまして、最適なオフィス空間、新しいワークスタイル等、そういった検証も含めて、まず検討をしていただきます。","voiceIndex":182,"id":"exchange-078"},{"speaker":"田中委員","kind":"提案","question":"今のご答弁だと、今大体の床面積のことについて、区として提案はしていない。そこのところを確認したくて、大体もう区としてこのような庁舎をつくりますよといったものがあるのかどうかというところも確認したいのですが、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"現在床面積に関しましては、庁内検討等でどのような機能が必要なのかというところも考えておりまして、そういった議論を進めながら、こうした業者の知見を使って、必要な規模等を算定していきたいと考えております。","voiceIndex":184,"id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"ということは、まだ全然決まっていないということでいいですか。先日の庁舎機能検討委員会も書面開催でしたし、どうにか区民の方の声が届く、きちんと聴取されて反映される形を求めたいのですが、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"区民意見も、今回庁舎機能検討委員会で様々議論いただきまして、７つの項目、防災ですとか、環境ですとか、区民サービスの向上ですとか、そういった意見がございましたので、答申書を基に、区民の方々でワークショップをやったりですとか。","voiceIndex":186,"id":"exchange-080"},{"speaker":"田中委員","kind":"質問・要望","question":"私たちが求めたいのは、区がもう決定してしまいましたけれどもこれでいいですかという形で区民に聞くのではなくて、変えられる段階で区民の意見を聞いてほしいということを求めています。そこに対してご答弁いただけたらと思います。","respondent":"濱中庁舎計画担当課長","answer":"新庁舎整備基本構想・基本計画策定委員会に関しましては、また区民の意見を募集したものを随時ご提示しながら、そちらを参考に議論を深めていただければと考えております。","voiceIndex":188,"id":"exchange-081"},{"speaker":"小芝委員","kind":"確認","question":"初めに、男女共同参画推進事業についてお伺いいたします。そこで、まず確認を致したいのですが、大井町から武蔵小山のほうに移転するとなると、これまでこのセンターを利用されていた団体にも、多少なりとも影響するのではないかなと思いますが、この登録団体の数、できればその地域ごとの数について教えてください。","respondent":"島袋人権啓発課長","answer":"登録団体の件ですが、現在登録団体数は４９団体あります。地区別にということでございましたが、申し訳ございません、地区別のものは手持ちにございませんが、代表者の住所を見ますと、やはりある程度大井町近辺に偏りが見られるようになってあります。","voiceIndex":191,"id":"exchange-082"},{"speaker":"小芝委員","kind":"質問・要望","question":"現役世代の方々に町会の運営に参加してもらい、魅力ある町会・自治会に向けて一緒に取り組んでもらうためには、オンライン空間をコミュニティの中につくり出すことが私は必要だと考えておりますが、まず確認をいたしますけれども、この品川区の中で、町会・自治会の中でオンラインでの交流を行っている団体は大体どのぐらいあると認識されているか、確認をいたします。","respondent":"川島地域活動課長","answer":"今、町会・自治会のほうでオンラインを活発に使ってやっているところがあるかというお尋ねですが、あまりないというのが正直なところでございまして、正式に把握している活動で申しますと。","voiceIndex":193,"id":"exchange-083"},{"speaker":"小芝委員","kind":"質問","question":"この課題は品川区だけでなく、全国８１５の自治体を対象にしました、都市における自治会・町内会等に関する調査も、ほぼほぼ同じようなアンケート結果でございました。来年度で７年目を迎えますしながわＷｉ－Ｆｉスポット事業を振り返りまして、地域の声もあったと思いますが、どのように評価されておりますでしょうか。教えてください。","respondent":"山本情報推進課長","answer":"今年度末時点で、今まで６６か所の整備を終えたところです。利用人数もかなり増えてきておりまして、平成３０年ですと、年間で大体１５０万件ほどの利用、昨年度が２２０万件ほどというところで、かなり多くの方にご利用いただけている事業だというふうに考えてあります。","voiceIndex":195,"id":"exchange-084"},{"speaker":"小芝委員","kind":"確認","question":"事業開始当初は、人口が集中する駅や大規模な公園で整備が進み、その後庁舎やほかの行政機関、文化施設、そして最近では障害者関係の施設へと、利用者のニーズに合わせて展開されてきていると認識しております。そこでまず確認をいたしますが、町会や自治会の会館にＷｉ－Ｆｉを導入した場合、区が補助する施策、仕組みといったものはあるのかどうか、ご答弁をお願いします。","respondent":"川島地域活動課長","answer":"現状、施設整備補助という仕組みがございまして、そちらを使っていただければ整備できますが、多分その改修費用というのはそれほど高いものではないので、それで使ってしまうとほかの設備改修ができないような場合も出てまいります。ただ、使うことは可能です。","voiceIndex":197,"id":"exchange-085"},{"speaker":"小芝委員","kind":"提案","question":"今後もＷｉ－Ｆｉスポットの拡大が進んでくると認識しておりますが、地域コミュニティの中心とも言えます、この町会・自治会会館の中にもネット環境と整えていく、その発端としてこのＷｉ－Ｆｉの整備を提案したいと考えますが、いかがお考えでしょうか。","respondent":"山本情報推進課長","answer":"現時点では、当初計画していた場所全てにＷｉ－Ｆｉスポットの整備を終えているところですが、今後の計画等につきましては、関係課、また、区民ニーズ等も捉えながら検討していければと思ってあります。","voiceIndex":199,"id":"exchange-086"},{"speaker":"小芝委員","kind":"質問・要望","question":"ぜひ検討していただきたいと思います。今後も地域がつながりますよう、全庁的に取り組んでいただきたいと思いまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"私からは１９９ページ、ブラインドサッカー国際大会等公式戦、それから２０３ページのキャッシュレス決済経費に関わることとして、プレス発表にも出ているオンライン請求クレジット決済による戸籍住民票の取得や、窓口でのキャッシュレス決済について、それから１９１ページ、文化コミュニティ施設経費についてお伺いしていきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それと日本ブラインドサッカー協会は、大会を開催するかしないかという二択ではなくて、ウィズコロナの中でも、どのようにして安全に安心して大会をできるかということをきちんと考えているところですので、その状況で今検討しています。","voiceIndex":203,"id":"exchange-088"},{"speaker":"塚本委員","kind":"意見","question":"過日の全豪オープンテニス、大坂なおみ選手が優勝しましたけれども、このときの選手に対する感染防止、ある種すごい対策が取られていたというようなことも１つ参考にしながら、この感染防止対策はどのように考えていらっしゃるのか、お知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"次回の国際大会での感染防止対策ということですが、１つ参考になりますのが、昨年１１月に国内大会を天王洲でやはり開催させていただきました。","voiceIndex":205,"id":"exchange-089"},{"speaker":"塚本委員","kind":"質問・要望","question":"このシステムは、どこのシステムを使っているのかを教えていただきたいということと、それから郵送代は分かるのですけれども、振込手数料というものも出ていて、この振込手数料はどのようなところで発生するのかを教えてください。住民票なら窓口だと３００円でしたか、この辺の手数料は、特に変更があるのかないのか、以上、お伺いしたいと思います。","respondent":"木村戸籍住民課長","answer":"それから前後いたしますけれども、住民票そのもの、戸籍等の手数料は、一切変える予定はございません。それから収納代行のサービスの手数料ですけれども、こちらは３.５％というような形で見ております。","voiceIndex":207,"id":"exchange-090"},{"speaker":"塚本委員","kind":"質問","question":"これはどのようなことでそれぞれ決まってきたのか、各課それぞれが、いろいろたくさんあるキャッシュレス決済の中で選んで、ある意味選択肢の中で選んだという決め方だったのか、そうではなくて何かしらの理由で、ここに決め打ちで決めざるを得なかったというか、決まるべくして決まったというような類いのものであったのかというような、なぜこのキャッシュレス会社が違っているのかについて。","respondent":"山本情報推進課長","answer":"税、あと国保の保険料につきましては、窓口のキャッシュレスではなくて納付書払いで、納付書についているバーコードをスマートフォンで読み取って、ＱＲコード決済でお支払いいただくという形で、そういった理由でサービスが異なってあります。","voiceIndex":209,"id":"exchange-091"},{"speaker":"塚本委員","kind":"意見","question":"全てを用意すれば済むといえば済むのですけれども、そのようなことが１つの課題と私自身は捉えているのですが、今後キャッシュレス決済は、区の様々な場面で、恐らく時代の要請から広がっていくのだろうと思います。広げていく上での、区としてのこの事業展開における考え方、経費負担というようなことも、もしかしたらあるのかもしれません。３.５％という手数料を区として負担していくというような原則で。","respondent":"山本情報推進課長","answer":"それから手数料等の問題もありますが、なるべく利用件数が多く見込まれるようなところについては、積極的に導入をしていきたいと考えています。","voiceIndex":211,"id":"exchange-092"},{"speaker":"塚本委員","kind":"質問・要望","question":"例えばそうすると、今品川区のきゅりあんなどの大ホールでも、千何名の定員がオーケーというようなことにはなるのだと思いますが、そういった緩和をしていくにあたって、感染防止対策という視点もありますので、その感染防止対策での注意点なども踏まえながら、この緊急事態宣言解除後、どういった形でコミュニティセンターを運用していくお考えがあるのか、お聞かせいただきたいと思います。","respondent":"古巻文化観光課長","answer":"ただ、定員に関しましては、なかなか緊急事態宣言が明けたからといって、感染状況がその後どうなっていくのか、そういった辺りのまだ見極めが難しいところがありますので、徐々に増やせるものは増やしていきたいですけれども、すぐにスイッチを切り替えるように。","voiceIndex":213,"id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"今のお考えを伺いました。特に解除後にはいろいろな予定をされているというか、定員まで使えるのだろうと思っているような方もいらっしゃるかと思いますので、今のような情報の提供というものを、区としてこれは丁寧にやっていただければということをお願いして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-094"},{"speaker":"くにば委員","kind":"質問","question":"１８５ページの生活安全推進事業、１６５ページ、ホームページ等経費です。１８５ページ、生活安全推進事業より、声の防犯プロジェクトについてお伺いします。この声の防犯プロジェクトが企画された経緯、具体的な事業内容などをお聞かせください。どこで放送されているかなど、現在の実施状況をお聞かせください。","respondent":"黛生活安全担当課長","answer":"実施状況につきましては、現在６つの商店街と２つの店舗、それからＦＭしながわなどでも定期的に放送していただいているほか、青パト、それから警察車両に搭載されております車載マイクを使いまして、広報を行っているところです。","voiceIndex":217,"id":"exchange-095"},{"speaker":"くにば委員","kind":"質問・要望","question":"今、６つの商店街と２つの店舗で放送されているとのことでしたけれども、プロジェクト開始から１か月経ちますが、まだ耳にしたことがない方が大勢いらっしゃると思います。ぜひともこのプロジェクトを区内全域隅々まで広げていただきたいと考えますけれども、いかがでしょうか。区内警察署や防犯協会、商店街などとの連携、告知、広報などの計画や意気込み等をお聞かせください。","respondent":"黛生活安全担当課長","answer":"今後ですが、広報しながわでの募集を呼びかける予定となっております。さらには様々な広報媒体を活用し、広く、そして継続的に募集を続けていきまして、プロジェクトを拡大させるように努めてまいりたいと考えております。","voiceIndex":219,"id":"exchange-096"},{"speaker":"くにば委員","kind":"質問","question":"このニュースに関しては、報道されたＡＮＮニュースの動画は約２３万回再生されており、潜在的な注目度が高い事業だと思います。区内全域に広まるよう、積極的な広報と普及活動をお願いします。確かな防犯効果が出たため、足立区は同じ機械を１００台導入することを決めました。品川区でもこの事業を取り入れて、さらなる声の防犯プロジェクトを推進してはいかがでしょうか。見解をお聞かせください。","respondent":"黛生活安全担当課長","answer":"野沢雅子さんからは、この吹き込んでいただいたＣＤにつきましては、防犯目的であればどうぞ幅広く活用してくださいというお声をいただいておりますので、皆様方からご意見を頂戴し、また我々も様々なアイデアを出して、事業を展開してまいりたいと考えております。","voiceIndex":221,"id":"exchange-097"},{"speaker":"くにば委員","kind":"質問","question":"犯罪抑止効果、犯罪被害低減の効果検証が得られましたら、第２弾、第３弾のさらなる実施を期待します。次に、１６５ページ、ホームページについてです。ホームページを閲覧するソフトであるブラウザについてです。広報広聴課は、ウェブ運用においてはごく基本的な問題点について、まず認識はしていますでしょうか。もし認識しているとしたら、なぜこの問題を放置しているのでしょうか。ご答弁ください。","respondent":"山本情報推進課長、大澤広報広聴課長","answer":"ブラウザの件ですが、委員ご指摘のとおり、ＩＥは１０までサポート期限が終わっており、今１１が使われているということで、こちらも将来的にはサポート期限がなくなるというところは聞いているところです。ホームページの問題点については、今後区として検討していきたいと考えています。","voiceIndex":223,"id":"exchange-098"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらに関しては早急な修正を求めます。私が簡単に調べただけでも、３００か所以上あります。広報しながわやしながわガイドで、防災情報については５ページ、区民まつりについては６ページと書いてあるのに、ページをたどると記載されていない。これらの媒体なら放置せず、修正の指示をするのではないでしょうか。修正と運用ルールの制定を求めますが、ご答弁ください。","respondent":"大澤広報広聴課長","answer":"各ページの管理は各部にお任せしているところではありますが、広報広聴課として、全庁的な調整が必要だというふうに認識はしています。","voiceIndex":226,"id":"exchange-099"},{"speaker":"くにば委員","kind":"質問・要望","question":"そこでは達成等級ＡＡと記載されていますけれども、この試験実施期間は２０１５年２月。日進月歩で急速に技術が進歩している時代に、品川区は６年以上前の試験結果を公表しているにとどまっています。総務省では、公共機関に対して年に１回試験結果の公表を求めていますけれども、品川区は、最後にウェブアクセシビリティ試験をしたのはいつでしょうか。今後の方針についてもお聞かせください。","respondent":"大澤広報広聴課長","answer":"過去に遡ってはまだ全部は終わっておりませんが、今後も進めていきたいというふうに考えております。","voiceIndex":228,"id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１７１ページの非核平和都市品川宣言事業に関わって、核兵器禁止条約について伺います。今年１月２２日、世界で初めて核兵器を違法化する核兵器禁止条約が発効されました。私は心から歓迎しています。非核平和都市品川宣言をしている自治体として、核兵器禁止条約の発効を歓迎しているのかどうか、歓迎してほしいと思いますが、いかがでしょう。","respondent":"立川総務課長","answer":"これまでも答弁してまいりましたけれども、区といたしましては、非核平和都市品川宣言に基づき、区独自の平和事業を継続して実施することで、恒久平和確立の意識啓発を区の内外に向けて発信しています。","voiceIndex":231,"id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"改めて態度表明しないということですけれども、新たにこの核兵器禁止条約というものが発効されたわけですから、ぜひそれを歓迎していただきたいと思いますが、この条約は、核兵器の非人道性の告発から出発して、被爆者が非人道性を訴え続けて、ようやくこの核兵器禁止条約として実を結びました。持てる国は、即時に核兵器を捨てよ」とあります。その品川区が核兵器禁止条約を歓迎しないのか、伺います。","respondent":"立川総務課長","answer":"先ほど答弁させていただいたのですけれども、品川区としましては、委員おっしゃるとおり、非核平和都市品川宣言に基づきまして、区独自の恒久平和確立に向けての意識啓発等を実施していますので、繰り返しになりますが、区として。","voiceIndex":233,"id":"exchange-102"},{"speaker":"のだて委員","kind":"質問","question":"もう一つお聞きしました。長崎や広島の悲劇を繰り返してはならないと思いますけれども、いかがでしょうか。改めて伺います。","respondent":"立川総務課長","answer":"区といたしましては、非核平和都市品川宣言に基づき、今後とも事業を実施してまいりたいと思います。","voiceIndex":235,"id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"広島、長崎の被害、差別などを再び繰り返してはならないということさえも表明できない、発信できないということは、非核平和都市品川宣言をしている自治体としてどうなのですか。そのような態度で、姿勢で、本当にいいのでしょうか。自治体として、しっかりと態度表明をしていく、せめて繰り返してはならないということは言っていくべきなのではないでしょうか。伺います。","respondent":"立川総務課長","answer":"広島、長崎に関しましては、区として毎年夏に中学生の広島平和使節派遣、また、長崎に対します青少年平和使節派遣をしています。こういった地道な事業を継続していきたいと考えているところです。","voiceIndex":237,"id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"事業を継続していくのはいいのですけれども、やはりこうした新たな動きが出てきている下で、それを歓迎してさらに進めていく。この宣言をしている自治体として、こうした立場にぜひ立っていただきたいと思います。品川宣言には「一刻も早く、核兵器をなくさなければならない」ともあります。この非核平和都市品川宣言と、核兵器禁止条約は同じ方向性だと思いますが、いかがでしょうか。","respondent":"立川総務課長","answer":"繰り返しになりますけれども、品川区といたしましては、非核平和都市品川宣言に基づき、事業を実施してまいります。","voiceIndex":239,"id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"品川が行っている宣言と核兵器禁止条約、その中身は同じ方向性ではないかと私は聞いたのです。この品川宣言にも、「製造、配備、持込みを認めない」と。核兵器禁止条約にも、製造や実験、配備をすることなどを禁止しております。同じ方向性だと言えないのでしょうか。伺います。","respondent":"立川総務課長","answer":"同じ方向性であるかどうかは、それぞれ解釈していただければというふうに考えております。","voiceIndex":241,"id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"それぞれの解釈ではなく、品川区の解釈を聞いているのです。ぜひお答えいただきたいと思います。国内でも、核兵器禁止条約に参加をすべきだと７割の方が答えています。やはり核兵器と人は共存できないと。だからこそ、この宣言をしている品川区が、核兵器廃絶へ向けて条約を歓迎すべきだと思います。この態度表明が核兵器廃絶への後押しになるとは考えないのか、伺います。","respondent":"立川総務課長","answer":"条約は条約として発効されたです。区は非核平和都市品川宣言を基にした事業を実施しています。それぞれよりどころと言ってはなんですけれども、その辺は異なりますが、地道に努力していきたい、そのように考えております。","voiceIndex":243,"id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"つまりは核兵器禁止条約とは立場は違うということですか、伺います。生物兵器や化学兵器、最近ではクラスター爆弾も違法化されて、廃絶へと進んできました。私はこの核兵器禁止条約が大きな力を持っていると考えています。区は、この核兵器禁止条約が核兵器廃絶への力になると考えているのか、伺います。","respondent":"立川総務課長","answer":"何回も同じ質問をされておりますので、また同じ回答をいたします。核兵器禁止条約に関しましては、区として態度表明を行う考えはありません。","voiceIndex":245,"id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした条約に対してしっかりと態度表明を行っていくことが、核兵器禁止を進めていく、推進していくという力になると思います。ぜひ宣言をしている自治体として、まだ、この参加をしていない日本政府にも署名、批准を求めていただきたいと思います。そうしたことが、やはり核兵器廃絶へとつながっていくと思いますので、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-109"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。最初に、１７７ページの総合庁舎緊急対応改修工事についてお聞きいたします。これ、令和元年度に総合庁舎の共用部のタイル改修７,９００万円ということで、今回、緊急の対応改修工事が９,２００万円余ということなのですけれども、具体的にどういった工事をするのか、お知らせいただきたいと思います。","respondent":"東野経理課長","answer":"緊急対応改修工事ですが、第３庁舎の空調機設備の更新工事、こちらは令和２年度に予算計上していたところなのですけれども、コロナ対策ということで令和３年度に見送ったものです。","voiceIndex":249,"id":"exchange-110"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。そうすると、工事はどのぐらいの期間を見ているのか。これは第３庁舎の工事が一番主立った内容だと思うのですけれども、工期についてお知らせいただきたいと思います。","respondent":"東野経理課長","answer":"工事期間につきましては、今後調整という形になるのですけれども、大体３か月程度というふうに見ているところです。","voiceIndex":251,"id":"exchange-111"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして１８１ページ、区民活動情報サイトについてお伺いいたします。今現在、登録団体数が５３４団体に対して、アクセス件数は月約７,０００件のアクセスがあるということで、今回４００万円の予算を使い、リニューアルするのですけれども、リニューアルをした後、団体数は限られているのでしょうが、アクセス数を考えて、大体どのぐらいを見通しているのか。","respondent":"宮澤協働・国際担当課長","answer":"委員ご指摘のございました、見づらさという点がございまして、特にスマートフォンやタブレットに対応していないというところがありますので、リニューアルに際しまして、画面の表示の最適化をするような形になります。","voiceIndex":253,"id":"exchange-112"},{"speaker":"高橋（伸）委員","kind":"質問","question":"町会に限っていうと、写真とか、今までこの貼り付けなどに、結構手間がかかるのです。それで来週ですか、３月８日の月曜日と火曜日に、システム操作説明会があると思うのですけれども、それによって、町会の方なども当然いらっしゃると思うのですが、今現在お分かりになっている、大体どれぐらいの人数、当然コロナ禍なので、人数を制限すると思うのですが、今の現状をお知らせください。","respondent":"宮澤協働・国際担当課長","answer":"リニューアル後のシステムの操作説明会というものを予定しております。コロナ禍というところもありまして、事前申込み制にしています。今のところの申込み件数は１５団体になっております。","voiceIndex":255,"id":"exchange-113"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そのような中、特に転入されてこられる方が、当該地区、例えば取り扱っていない品川第二、大崎第二、大井第二、大井第三、荏原第二、荏原第三、荏原第五に来ていただいたときに、当然、例えば荏原だったら荏原第四センターに行ってくださいと伝え、足を運んでもらう、促すと思うのですけれども、私がちょっとお聞きしたいのが、そこの地域センター、取り扱っていない地域センターの所長。","respondent":"川島地域活動課長","answer":"地域センターの職員のマナーアップの取組、それから課長の現場をどのくらい見ているかというようなお話だと思いますけれども、私も定期的に地域センターへはなるべく足を運ぶようにしておりまして、職員と面談等を行う中で、指導というか、アドバイスをしたり、様子をうかがって。","voiceIndex":257,"id":"exchange-114"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"課長がおっしゃっていることは分かるのですけれども、やはり何かトラブル、「わざわざここに来たのに、何で扱っていないの」など、住民の方、これから転入されている方で納得いかない方もいらっしゃると思うのです。そのようなときに、その職員に対して、会話の術を、より足を運んでもらえるよう、どのようにされているのかどうかを、ちょっともう１回教えていただきたいと思います。","respondent":"川島地域活動課長","answer":"トラブル対応の大切なところというようなことだと思いますけれども、やはりお客様の言い分というか、言うところをまずしっかり聞くと。耳を傾けると。傾聴した上で丁寧な対応をするというようなことが基本になるということで、日頃から指導しています。","voiceIndex":259,"id":"exchange-115"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。続きまして１９７ページ、ジュニア二極化解消事業等についてお聞きいたします。これは、品川区のスポーツ推進計画では、子どもが体を動かすことの楽しさと自分の得意な動きを体感できるスポーツということで、二極化、スポーツもあまり得意ではない子に向けてもやっていきましょうというような事業だと思うのですけれども、具体的な内容、やられている内容をお知らせいただきたいと思います。","respondent":"中元スポーツ推進課長","answer":"ジュニア二極化解消事業等の具体的な内容です。親子スポーツ教室、こちらは令和３年度はヨガ教室を予定しています。２つ目として、チャレンジスポーツ教室、こちらは駆けっこ、縄跳び、跳び箱、ボール投げなど、運動の基本的動作の基礎を培う教室を予定しています。","voiceIndex":261,"id":"exchange-116"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"チャレンジ親子スポーツ教室など、いろいろやられていて、令和２年度の予算ですと１３１万円余、来年度の予算が１９９万円余なのですけれども、増額になって、何かまた別に、今課長がおっしゃったように、改めて令和３年度も計画しているのかどうか、お知らせいただきたいと思います。","respondent":"中元スポーツ推進課長","answer":"令和３年度につきましては、こちらのほうもうまく先に場所を確保してやらせていただくというところと、新しくジュニアダンス教室をオンラインで始めるということで、少し金額を増やして要求をさせていただいたものです。","voiceIndex":263,"id":"exchange-117"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"同じく１９７ページの、親子ジュニアスポーツフェスタについてお伺いいたします。このフェスタは、３月１日の広報しながわに、ジュニアスポーツフェスタとは掲載はしていないと思うのですけれども、今回３月１日に広報しながわに載っていたこのイベントが親子ジュニアスポーツフェスタの部類に入るのかどうか、お知らせいただきたいと思います。","respondent":"中元スポーツ推進課長","answer":"委員ご指摘のとおり、親子ジュニアスポーツフェスタですが、当初リアルに広い場所で集まって、スポル品川大井町を借りて、そこでイベントをやるというもので予算組みをしていたところですが、新型コロナウイルス感染症の感染拡大の状況で、やはりリアルイベントは難しい、また。","voiceIndex":265,"id":"exchange-118"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これが今月の３月２８日の日曜日に午前９時から午後２時半まで、１４時半までやるということで、６項目ぐらいいろいろあります。これは、事前の申込みになっていると思うのですけれども、Ｚｏｏｍのオンラインでやるのですが、これ、取組内容としてそれぞれ６項目あり、やはり人数の制限がある中、どれぐらい、バランスよく振り分けてやっていかれるのかということをお知らせいただきたいと思います。","respondent":"中元スポーツ推進課長","answer":"それぞれ３００組です。親子でという形になってあります。１組で６種目全てを申し込むということでも大丈夫ですが、ただ、こちら先着順となっていますので、そこを超してしまうと受けられないということになってきます。","voiceIndex":267,"id":"exchange-119"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当はスポーツとして、このようなオンラインというものは、課長としても少し残念だと思うのですけれども、来年度の予算で、６７０万円余という予算づけ、令和２年度と比べて減額されているのですけれども、これはやはり今、新型コロナウイルス感染症によって広場でできない、来年度もオンライン、今のところオンラインで計画しているから減額なのか。","respondent":"中元スポーツ推進課長","answer":"失礼いたしました。来年度につきましては、区立総合体育館での開催を予定しています。","voiceIndex":269,"id":"exchange-120"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひとも未来ある少年・少女のスポーツ普及にこれからも取り組んで、未来ある子どもたちのためにやっていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":271,"id":"exchange-121"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは１６９ページ、ＩＣＴ推進費とキャッシュレス決済、これに区民集会所の使用料についてもお伺いしたいと思います。それから１７３ページ、男女共同参画、時間があれば、新庁舎についても少しお伺いいたします。現在の感覚に合ったものに見直しを検討してはいかがかと思いますが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"ただ時代に合わせ、やはり検討が必要だということも認識しておりますので、次回はまた少し内容等を検討させていただきたいと考えております。よろしくお願いします。","voiceIndex":273,"id":"exchange-122"},{"speaker":"あべ委員","kind":"提案","question":"当事者団体の声も聞きながら、幅広く検討していただければと思います。次に、ＩＣＴならびにキャッシュレス決済等々についてお伺いしたいと思います。午前中も同様の議論があったと思いますけれども、まず集会室の使用料支払いについてお伺いいたします。昨年の予算特別委員会でキャッシュレス対応するよう提案したところ、ベンダーと検討していただけるということでした。検討結果を教えてください。","respondent":"山本情報推進課長","answer":"来年度サービスコーナーや税務課の窓口でも拡大をする予定ですが、地域センターの窓口につきましても、令和４年度対応できるように検討を進めているところです。その中で施設の使用料につきましても、キャッシュレス化対応していくかは考えていきたいと思ってあります。","voiceIndex":275,"id":"exchange-123"},{"speaker":"あべ委員","kind":"質問","question":"それは土日も料金収受ができるという意味でよろしいでしょうか。","respondent":"山本情報推進課長","answer":"土日の対応も含めまして、今後考えてまいります。","voiceIndex":277,"id":"exchange-124"},{"speaker":"あべ委員","kind":"質問","question":"令和４年度からということで、ちょっとまだ時間はかかるかなとは思うのですけれども、ぜひよろしくお願いしたいと思います。感染症だけではなくて、大災害時、また平時の働き方改革のためにも、場所を制限されない働き方の実現は急務だと思いますけれども、品川区ではまず実証実験に参加しているのかどうか、そして現在の活用状況などについても教えてください。","respondent":"山本情報推進課長","answer":"ＬＧＷＡＮを活用したテレワークというところで、昨年は国のほうが、地方公共団体のテレワークを推進するために、自治体テレワーク推奨実証実験を行っておりまして、区のほうも２０ライセンス分持ち込んで、実験のほうに参加しています。","voiceIndex":279,"id":"exchange-125"},{"speaker":"あべ委員","kind":"質問","question":"ＬＧＷＡＮ－ＡＳＰでは、オンライン会議ですとか、チャット機能といったことも利用が可能になってきていると思います。そちらの活用状況はいかがでしょうか。品川区の職員の方々の活用状況はお分かりでしょうか。この一連のテレワーク等の活用について、どの辺りを目標において、今何合目辺りにいるか、自己評価されているか教えてください。","respondent":"山本情報推進課長","answer":"それからＬｏＧｏチャットに関しましては、１年間自治体が無償で使えるというところで、今年度実証実験という意味合いを含めまして、今利用しています。それから、現在の達成度ですが、ウェブ会議、テレワーク含めて、まだ検証の段階だというふうに考えてあります。","voiceIndex":281,"id":"exchange-126"},{"speaker":"あべ委員","kind":"質問","question":"全体として非常に活発に活用されているという印象を受けました。自治体デジタル・トランスフォーメーションは、待ったはなしだと考えています。品川区では、５年後の自治体の姿をどのように描いているでしょうか。今後自治体のデジタル化を進めていく上で、一番大切なことは何だというふうに、品川区では考えているでしょう。","respondent":"山本情報推進課長","answer":"それからデジタル化を進めていく上で大事なところですが、デジタル化を何のためにやるかというと、それぞれ人々の暮らし、生活というものを便利にしていく、それから我々の働き方が大きく変わるものだと思ってありますので、そういった意味で区民サービスの向上。","voiceIndex":283,"id":"exchange-127"},{"speaker":"あべ委員","kind":"意見","question":"デジタル化を進める上で何が大切か、これはいろいろな答え方があると思います。デジタル・トランスフォーメーション、ＤＸを進めていく中で、品川区として、情報公開や行政の透明性をどのように認識しているかお答えください。","respondent":"山本情報推進課長","answer":"確かにデジタル化を進めるにあたりまして、区としても、区民の様々な情報を取り扱っていくことになると考えています。その辺りで、セキュリティ対策等も含めまして、区の取組はきちんと区民の方に説明していく必要があるというふうに考えてあります。","voiceIndex":285,"id":"exchange-128"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは１７１ページ、成人式経費、１８７ページ、ＡＩ型特殊詐欺対策アダプタ購入、２０５ページ、マイナンバーカード普及促進をお伺いしたいと思います。順不同で参ります。この代理人交付を行う場合、持参する書類は、交付通知書、その裏に委任状がありますので、そこを記入する。しかし、実際交付受付窓口では、申請者ご本人の顔写真つきの確認書類や診断書が求められたりする。","respondent":"木村戸籍住民課長","answer":"そのような対応も行っておりまして、あと事前にお問い合わせをいただいた段階で、ご事情をいろいろお伺いしながら、では何ができるだろうか、どうやったらできるだろうかというところをお聞き取りしながら、ケース・バイ・ケースで対応しています。","voiceIndex":290,"id":"exchange-129"},{"speaker":"こんの委員","kind":"提案","question":"そこで１つの提案というか、ほかの区でもやっていることをちょっとご紹介というか、ご存じかどうか確認したいのですが、例えば新宿区、世田谷区、江東区、調布市、ここでは代理人交付の理由について、ご本人の病気や障害、こうしたこと以外に、当面の緊急措置として、新型コロナウイルス感染症の拡大防止のために外出を自粛している申請者ご本人については、代理人による受け取りができるとしております。","respondent":"木村戸籍住民課長","answer":"他区等の事例については、認識をしているところではございまして、私どもとしても、より分かりやすいお知らせの仕方、運用を考えてまいりたいと考えています。","voiceIndex":292,"id":"exchange-130"},{"speaker":"こんの委員","kind":"質問","question":"成人式経費についてお伺いしたいと思います。もう一つ、昨年９月の総務委員会で報告されたものを見せていただきました。その頃はさすがに新型コロナウイルス感染症が終息している、してほしいと願うところですが、今回初のオンライン成人式を経験したわけですので、代替会場とオンラインのハイブリッド形式、こうしたことも開催方法として考えられるのではないかと思いますけれども、いかがでしょうか。","respondent":"立川総務課長","answer":"きゅりあんが使えない再来年からですけれども、代替会場とともに、いわゆるオンラインでの開催を併用して実施する、今年もそういうつもりで考えていたところがありますので、委員ご提案の内容も踏まえまして、検討していきたいと思います。","voiceIndex":294,"id":"exchange-131"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２項の地域振興費から、１８３ページ、国際交流推進事業、それから１８７ページ、市町村交流事業、時間の状況で１７９ページ、町会・自治会加入促進支援、その辺からお聞きしたいと思います。それから、国際交流推進事業に関してです。現長期基本方針における国際交流の考え方について、改めてお聞きしたいと思います。","respondent":"川島地域活動課長、宮澤協働・国際担当課長","answer":"実績は、数でいいますと、ひだまりの里の利用実績が令和元年度は２,０３４名というところが、令和２年度は１,３９７名、それから早川町のほうも、ヘルシー美里、ヴィラ雨畑の宿泊利用助成などで見ますと。５年ごとに周年行事という交流を含めて、各都市との交流を進めてきたというところと、また、多文化共生社会の実現に向けて、区民へのそういった啓発活動を進めていく中で、国際都市品川に向けて積極的な事業を行ってきているです。","voiceIndex":299,"id":"exchange-132"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば、区が調査する世論調査が今まで行われてきましたけれども、そういう中で、区民の方が市町村交流をどの程度知っているかというのを調査したことがあるのかどうか、その辺をお聞きしたいと思います。それから、国際交流のほうです。その辺についてお考えを教えてください。","respondent":"川島地域活動課長、宮澤協働・国際担当課長","answer":"市町村交流事業の交流都市の認知度ですが、実際、調査という形で、数で把握はしてございませんが、山北町につきましては昭和６３年に協定を締結しまして、それから。毎年４月になりましたら、各大使館を回るなどして連携を強めているところです。各姉妹友好都市とも５年ごとの交流というのがありますので、そういった機会を捉えてしっかり交流を進めていくです。","voiceIndex":302,"id":"exchange-133"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川区としても、そういう交流都市と交流しているという、例えば庁舎内のどこかにあるわけでもないと思うのです。表示されているわけでもない。その辺についてお考えをお聞きしたいと思います。交流では、品川区国際友好協会との関係がかなり強くなってくると思うのですけれども、当然この辺については、今までどおり行ってもらいたいと思うのですが、改めてそこについてもお聞きしたいと思います。","respondent":"川島地域活動課長、佐藤企画調整課長","answer":"交流ツアーとかイベント参加者がリピーターになって、また再度、交流都市に行くという事例もありますので、認知度も高まってきているとは思うのですが、より一層の工夫というか、これまで以上にというご提案のようなところですけれども。これまで総務課で平和派遣というところと、今回国際交流というところで、長期基本計画で一本化して、より積極的に進めていくというところで、今後は総務課が顔となって、全庁的、また区内全般的にわたって。","voiceIndex":305,"id":"exchange-134"},{"speaker":"鈴木（真）委員","kind":"質問","question":"山北町だとひだまりの里、私も最近行っていないのですけれども、建物がちょっと古くなってきている状態もあると思うのです。ですから、今後の活用ですとか、それから、マウントしながわをどうやって活用していくのか、その点についてもう１回お答えをお願いしたい。その辺も踏まえてもう１回、国際的なものの考え方をお願いいたします。","respondent":"川島地域活動課長、宮澤協働・国際担当課長","answer":"より多くの方に知っていただく工夫というのは、委員のご指摘も踏まえて考えていく予定です。姉妹都市、友好都市の３都市との交流を進めているのを中心にしています。例えば産業、教育であったり、そういった分野に特化した形の交流という考え方もありますので、在住外国人の動向等を注視しながら研究してまいります。","voiceIndex":308,"id":"exchange-135"},{"speaker":"西本委員","kind":"質問・要望","question":"変えてほしいところ。きちんとお金を払っているわけですから、しっかり不具合もチェックしなければならないのではないでしょうか。これはまた別問題になりますが、コロナ禍なので、使用料については、歳入のところでも言いましたけれども、倍以上のお金を使っているわけですから、減免という形でコロナ禍の期間だけでも配慮していただきたいと要望しますが、いかがでしょうか。","respondent":"佐藤企画調整課長、古巻文化観光課長","answer":"今後、成果指標に基づいた実施計画をつくりまして、また新公会計のデータもあわせて、収支の観点も入れながらご報告をしたいと考えており、検討を進めているところです。すみません、私はＷｉ－Ｆｉが使えるという認識で、昨日もいろいろその辺の話はしておりますけれども、その辺については確認させていただいて、使えるように今後進めてまいりたいと思います。","voiceIndex":312,"id":"exchange-136"},{"speaker":"西本委員","kind":"提案","question":"区民の人たちが不便だ、利便性がないというのがあるならば、なぜそこの指定管理の方々が考え、提案をして、変えようとしないのでしょうか。指定管理の中で、いろいろ変える提案をしているということがあるのではないでしょうか。なぜきゅりあんはそれができないのでしょうか。今、コロナ禍において大変な思いをして、苦慮しているわけですから、減免というか、少しは考慮してもいいのではないでしょうか。","respondent":"古巻文化観光課長","answer":"指定管理者としての提案等につきましては、今回、また指定管理の選定をいたしましたけれども、その中でも様々な提案をいただいておりますし、きゅりあんだけが何かできないということではないと認識をしておりますので、今後はきちんと考えていきたいと思います。","voiceIndex":315,"id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"情報公開についてなのですが、情報公開手数料については、行政情報は区民の財産ですし、区政への区民参加、知る権利の保障からも、３００円の手数料は無料にすべきだと共産党としても一貫して求めてきましたので、改めて手数料の無料化を要望しておきたいと思います。１４０円というのは高過ぎると思うのですけれども、ぜひコピー代の引下げもしていただきたいと思うのですが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"白黒のコピー代については、国や都、他区と比較しましても、妥当な金額だと考えております。ただ、カラーのコピー代につきましては、現在の状況と照らし合わせまして、妥当であるかの検証は必要であると認識しています。","voiceIndex":318,"id":"exchange-138"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２つ目に、指定管理者について伺いたいと思います。これを求めて質問したいと思います。この見直しを行ってきたのはどの部署で、どんなメンバーで、どんな形で行われてきたのか、大分長い期間見直しをされていると思うのですけれども、この点について伺います。作成されるとしたら、いつできるのかについても伺います。","respondent":"佐藤企画調整課長","answer":"指定管理制度について何点かご質問いただきました。１点目の方針の見直しにつきましては、委員ご指摘のとおり、平成３０年の後半ぐらいから進めてまいりました。","voiceIndex":320,"id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"企画調整課だけで、もう３年以上かかっているということになると思うのですけれども、なぜこんなにかかっているのかなと思うのですが、それから運営指針とかガイドラインは、新年度の早い時期にできるということで確認させていただいていいでしょうか。その資料からは透明性も客観性もないし、公平性、公正性も、その担保がどうされているのかというのも分からないという状況です。","respondent":"佐藤企画調整課長","answer":"１点目の方針等はいつできるのかというのは、先ほどご答弁したとおり、来年度早々には策定を完了したいと考えています。","voiceIndex":322,"id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこのことを公表していただきたいと思うのですけれども、その考え方も教えてください。それからもう一つは、事業計画書です。ということなので、先ほども申し上げました選定委員会の構成、氏名と役職、それから選定結果、点数も含めて、それから選定委員会の会議録、それから事業計画書、これをぜひ資料として議会へ提出していただきたいし、公表もしていただきたいと思うのですが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"指定管理者に関わる公表の件です。１つ目の選定委員に関しましては、基本的に氏名等の公表が必要であると今のところは検討しているところで、最終的に判断していきたいと考えております。","voiceIndex":324,"id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"これは実態が見えないのです。収入が合計幾らで支出が合計幾らなのか、この収支を明記すべきではないかと思うのですが、いかがでしょうか。その提案した事業への実施状況を、報告書という形で出していますので、それをまとめて出していただければいいのではないかと思うのですけれども、それについても資料で出せるようにしていただきたい。以上３点の改善を求めますが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"しかしながら、議会や区民等に指定管理者制度の公平性、客観性を示すためにも、その辺の項目というのはできるだけ出していきたいと区としても考えておりますので、先ほど来言っておりますけれども、民間事業者に配慮しながら、ただ民間事業者から手を挙げてもらえなくなると。","voiceIndex":326,"id":"exchange-142"},{"speaker":"たけうち委員","kind":"質問","question":"１８５ページの自動通話録音機等の特殊詐欺対策、それから２０３ページで住民基本台帳関係費に関連して伺います。自動通話録音機は午前中もお話があって、特殊詐欺が東京都でも、新聞報道等だと２５％ぐらい減っていると。それから、品川区においてそれが減った要因をどのように捉えているか、ここを教えてください。これが何件ぐらいあったか教えてください。","respondent":"黛生活安全担当課長、宮澤しながわ活力応援給付金担当課長","answer":"被害が減少した要因ですが、コロナ禍の影響で外出する機会が減少したことが主な要因であると警視庁本部においては分析をしていますが、それだけではなく。８月５日に申請書を発送しまして、宛てどころなし等の理由で戻ってきた申請書の数は、１,４９４件です。申請されていない世帯に対しまして、９月３０日に勧奨通知を発送しました。その戻りは１５１件というところでございました。","voiceIndex":329,"id":"exchange-143"},{"speaker":"たけうち委員","kind":"質問・要望","question":"特殊詐欺なのですけれども、実はこの間、２週間ぐらい前ですか、私の自宅にも電話が来まして、それで私の妻が出たのですが、「荏原警察署の何々です」と。あわせて、品川区でも青パトが回っていますけれども、ここも連携しているのですか。それで、多分２回目の勧奨通知のときになぜ届いたかというと、郵便配達の方が、そこに名前が出ていれば、よかれと思って入れてくれたと。","respondent":"黛生活安全担当課長、木村戸籍住民課長","answer":"区の青パトがその地域に直ちに出動して、被害防止の広報を行うなど、緊密に連携をして被害防止対策を図っているところです。引き続き、こうした活動を積極的に展開してまいりたいと考えております。全貌については分かりませんけれども、手続きのやり方についてはそのような形です。それと、電話番号については、届け書にはお書きいただくのですけれども、いわゆるデータとして保存してはいないです。","voiceIndex":332,"id":"exchange-144"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ただ、あまりいろいろなメールが来過ぎてしまって、かえってどうなのかなと思うのですけれども、そういうもう一重の取組についてお聞かせいただきたい。それはそれで自由なので、いいのだけれども、さっきのような方で、悪意はないのだけれども、返戻された方について、何か一重工夫して、そういうことが防げないかなと思うのですけれども、一応ご感想というか、教えてください。","respondent":"黛生活安全担当課長、木村戸籍住民課長","answer":"ただ、大変有効な手段であるのではないかと考えております。どういうときにこれが使えるのか、また使わなければいけないのかにつきまして、これから関係課と調査・研究を進めてまいりたいと思います。受付の際に、郵便物が必ず届くようにというご案内を一つ添えたような形で、それを徹底してまいりたいと考えています。","voiceIndex":335,"id":"exchange-145"},{"speaker":"たけうち委員","kind":"質問・要望","question":"特殊詐欺のＡＩのほうも先ほどいろいろあって、実験的にやっていくということなので、そういうものも含めて複合的に、ぜひさらに減少していただくように要望します。それから住民基本台帳は、これから、特にワクチンなども含めて出てくるので、何かできないか、また引継ぎも含めて、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":338,"id":"exchange-146"},{"speaker":"本多委員","kind":"質問","question":"１７１ページの危機管理経費について質問します。宿日直経費等について、平成１７年から危機管理室が設置されました。それ以来、１５年経ちましたけれども、充実されてきた点ですとか、あるいは積み上げてきた点などについてお聞かせください。","respondent":"立川総務課長","answer":"約１５年経ちまして、その間、様々対応してきたところですけれども、平成２１年には新型インフルエンザの関係で本部を立ち上げたりとか、また、平成２３年には東日本大震災の関係ですとか、様々危機管理に関しまして、初動体制をつくるということでやってまいりました。","voiceIndex":340,"id":"exchange-147"},{"speaker":"本多委員","kind":"意見","question":"分かりました。危機管理宿直室は総務部内にあり、危機管理担当部長と災害対策担当部長を兼務されておりますけれども、総務部と災害対策担当のそれぞれの組織の役割について、どう発揮をされてきたのか、その点をお聞かせください。","respondent":"立川総務課長","answer":"危機管理におきまして、災害対策担当部長におきましては、危機管理監としての役割を担っていただいております。防災と災害という切り口では災害対策担当部長が中心にやっていくということで、それ以外のところを総務課、また総務部長が中心にやっている、そういった切り分けです。","voiceIndex":342,"id":"exchange-148"},{"speaker":"本多委員","kind":"質問","question":"事例を挙げて聞いていきます。複合災害で、多重防御について伺います。災害には、予測災害と突発災害があります。区内のみならず、防災協定締結自治体で災害が起きた場合、あるいは近距離での災害、一例を挙げますと、伊豆大島の噴火が３５年前にもありました。伊豆大島の噴火の周期は３０年から４０年と言われています。そうした備えや心構えについて、危機管理宿直室としてはいかがお考えでしょうか。","respondent":"立川総務課長","answer":"自然災害における品川区の危機管理宿直という視点ですけれども、この辺につきましては、宿直の職員として、管理職が日々交代で対応していますので、連絡網等を整備いたしまして、災害時、即座に連絡が区長をはじめ行き渡るように、体制を取っているところです。","voiceIndex":344,"id":"exchange-149"},{"speaker":"本多委員","kind":"質問・要望","question":"あらゆる想定をして備えていただきたいと危機管理的に思います。そして、組織強化について質問するのですが、現在品川区内には自衛隊出身の方、任期付採用２名、会計年度任用職員１名になります。平成２７年度から５年間、曽田部長、令和２年度からは滝澤部長に対応していただいております。自衛隊を退官された方の採用を強化し、組織のさらなる強化を図る点について、区のお考えをお聞かせください。","respondent":"黒田人事課長","answer":"専門的な知識を有する職員の採用につきましては、地方公共団体の一般職の任期付職員の採用に関する法律に基づきまして、一定程度の期間、任用するというところで、実際に職員を育成するというところが前提となっている中で、期間的な限定任用というところで。","voiceIndex":346,"id":"exchange-150"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほどデジタル化のほうでも外部人材の活用という議論がありました。いろいろ全般的に、区政全般について、そういった着眼点で進めていただきたいと思います。ぜひその点について改めて教えていただきたいのと、今現在、自衛隊・警察・消防出身者の採用での組織強化をしているというのを、もう少し区民に知っていただくＰＲについてはいかがでしょうか。","respondent":"黒田人事課長","answer":"ＰＲにつきましては、２３区で初めて部長として採用したときにはプレス等もしておりますので、そういった中で様々な方法を考えてまいりたいと思ってあります。","voiceIndex":348,"id":"exchange-151"},{"speaker":"本多委員","kind":"質問・要望","question":"もう少し区民に、こういう取組をして、こういう方を採用をしているので、区の組織が強化したのだということをＰＲしていただきたいと思いますし、現実的に組織強化ということでうたって取組をしていますので、組織強化になったという部分を改めて教えていただきたいと思います。","respondent":"黒田人事課長","answer":"専門的知見を持っているベテランの方が組織におりますと、そういった中で様々な計画を立てたりですとか、事業を執行する上での今まで気がつかなかった視点というところが当然出てまいりますので、そういったところで。","voiceIndex":350,"id":"exchange-152"},{"speaker":"本多委員","kind":"質問","question":"例えば、この間の２月の地震のときにも、テレビで２３区の震度は、最初は４と出たけれども、最終的に品川区は３と修正されました。それは突発的なことですから、最初に出たのと後で修正というのは当然あることだと思いますけれども、品川区が３というのが出るのは防災課任せなのか、あるいは総務部でも、夜に起きたら宿日直で、品川区内の震度は幾つだというのを把握できているのか、その辺を教えてください。","respondent":"立川総務課長","answer":"いわゆるマスコミ等で報道される震度につきましては、その震度計の震度とは異なりまして、それは東京消防庁、そういった機関で把握しているものと、気象庁等が把握しているものと認識しております。","voiceIndex":352,"id":"exchange-153"},{"speaker":"本多委員","kind":"質問・要望","question":"もし分からなければ結構なのですが、品川ふ頭に、都の港湾局が管理している敷地内に、品川地震観測所がありまして、その辺の把握というか、どうなのかなと思って、素朴に教えていただきたいと。","respondent":"立川総務課長","answer":"総務課としては、港湾局の震度計については認識しておりません。","voiceIndex":354,"id":"exchange-154"},{"speaker":"本多委員","kind":"質問・要望","question":"分かりました。総務部としても、危機管理にものすごく対応していただいていると感じました。引き続き、組織強化に向けて取り組んでいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":356,"id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１６３ページ、企画調整費、指定管理者モニタリング・評価経費、それから１６９ページ、ＩＣＴ推進管理費、時間があれば予算編成全体に伺いたいと思います。１６３ページですけれども、指定管理者の指定の議案と同じように、予算措置である債務負担行為、指定管理者の設定について、以前から議案として提出していただきたいという観点からお伺いします。現在も総務省はこの立場です。横須賀市です。","respondent":"佐藤企画調整課長","answer":"指定管理者における債務負担行為の設定に関しましては、委員ご紹介のとおりの認識を私どもも持っております。様々な対応、また考え方があると思いますので、その辺に関しましても、今検討しています。","voiceIndex":358,"id":"exchange-156"},{"speaker":"高橋（し）委員","kind":"提案","question":"今検討しているということです。その指定の議決を、つまり予算措置のないまま議決してくださいと、議案として提案されているわけであります。そういった観点からも債務負担行為を、上限を定める形で、現在工事などをやっておりますけれども、そういった形で設定するべきだと思います。そういった観点からも必要だと思いますが、改めてもう一度お願いします。","respondent":"佐藤企画調整課長","answer":"指定管理者に関する債務負担の関係ですが、委員にこれまでご指摘いただいた内容は、区としても把握をしています。私どもの区のように設定していない自治体もございまして、そういった場合の理由や根拠等も精査しながら、今後検討を進めたいと思います。","voiceIndex":360,"id":"exchange-157"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"単年度の協定を理由ということで、今日はお話しにならなかったので、その根拠を伺うことができませんでしたが、今検討しているということですので、ぜひ議案審査の中で、債務負担行為も含めて、予算として出てくることを要望いたします。方針を改定されるということですので、債務負担行為の項目を入れていただけるように強く求めます。","respondent":"山本情報推進課長","answer":"ただ、昨年末、国から自治体への自治体ＤＸ推進計画が策定されまして、区として、自治体として、重点的に取り組むべき事項というのが挙げられておりますので、それらの取組というところを、それぞれ基本的な方針と内部の進め方等は考えていきたいと考えています。","voiceIndex":362,"id":"exchange-158"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その検討を進めていっていただきたいと思います。専門的なところであるので、そのお話と、それから、先日もほかの委員のご質問にありましたけれども、接種管理などでＲＰＡの活用等も考慮すべきだと思うのですが、いかがでしょうか。","respondent":"山本情報推進課長","answer":"新型コロナウイルス感染症のワクチンに関する情報推進課の関係ですが、システムの連携、データの連携等がありますので、その辺りは情報推進課でしっかり計画を立てながら、今後、国から工程が示されますので、それに沿って着実に進めていきたいと考えています。","voiceIndex":364,"id":"exchange-159"},{"speaker":"大倉委員","kind":"提案","question":"１６７ページ、ＬＩＮＥ公式アカウント運用、１７１ページ、企業・大学との連携、１７５ページ、庁舎管理費について伺います。ＬＩＮＥ公式アカウント運用でチャットボットなのですが、午前中もお話がありましたが、これを利用しやすいように改善していくと伺いましたけれども、私もちょっとだけ意見を言わせていただければと思います。何かありましたらお願いします。","respondent":"山本情報推進課長、東野経理課長","answer":"チャットボットの利用方法についてですが、区といたしましても、利用方法について改善の余地もまだあると考えていますので、委員からご指摘いただいた点も含めまして、より使いやすいものになるよう工夫してまいります。今後も新型コロナウイルス感染症の対策としては、そういった面につきましても検討していきたいと考えています。","voiceIndex":368,"id":"exchange-160"},{"speaker":"大倉委員","kind":"質問・要望","question":"ＬＩＮＥのほうは、お願いいたします。２階、３階、本庁舎にいろいろと入り口があるということで、かなり運用するのも大変だということと、実際、発熱された方が来たときの対応とかは、もう検討されているのかどうか教えてください。もう一度お願いします。アンケートや、学生の皆さんから意見などを聴いていただいて、何か支援につながればいいなと思っているのですが、お考えをお聞かせください。","respondent":"東野経理課長、立川総務課長","answer":"サーモグラフィーという部分への対応ですが、令和３年度も予算計上はしていない状況です。ただいま委員からありました大学生への支援ということに関しましては、所管のほうに、そういったことが考えられるのかどうかということについては伝えておきます。","voiceIndex":371,"id":"exchange-161"},{"speaker":"大倉委員","kind":"質問・要望","question":"大学生への支援なのですが、所管はどこになるのでしょうか。今、分からなかったので、大学との連携で伺ったので、分かれば教えていただきたいのと、ぜひアンケート等も含めて大学生の声を。区長もたしか東京医療保健大学の大学生と意見交換みたいなことをするというお話もあったかと思いますので、ぜひその点も踏まえて、連携をしていっていただきたいと思いますので、最後に、よろしくお願いします。","respondent":"立川総務課長","answer":"大学生ですので、青少年対策ということになるかなと考えております。","voiceIndex":374,"id":"exchange-162"},{"speaker":"藤原委員","kind":"確認","question":"自動販売機だけがある。それで、細い道のところにぽつんとある販売機の横にはごみ箱があって、ごみを入れる円い穴が開いているではないですか。だけれども、ごみ箱を置きなさいという規定です。そこを徹底してもらいたいのが１点。それと、１８７ページ、わんわんパトロール。すみません、わんわんパトロールは来年度からやめるのですか。だから予算書に載っていないのですか。その確認をさせてもらいます。","respondent":"黛生活安全担当課長","answer":"今後は業界団体を通じての働きかけを継続するとともに、ホームページ、それからＳＮＳなど、様々な広報手段等を活用して、周知と啓発に努めるようにしてまいります。２点目の防犯カメラです。","voiceIndex":377,"id":"exchange-163"},{"speaker":"藤原委員","kind":"質問","question":"課長に今、３点伺って、わんわんパトロールが一番答弁が長くて、わんわんパトロールはまた来年度もきちんとやっていきますということなのですけれども、それで財政課長、こういうところこそわんわんパトロールという項目を入れないと駄目でしょう。そういう思いを受け取って、予算書は作っていかないといけないと思うのです。それが、こうやって出ていないで、どこかとまとめてしまうのは、どうなのですか。","respondent":"品川財政課長","answer":"予算書の表記につきましては、いろいろとご意見等があるかと思います。こういうご指摘を受けまして、来年予算書等を作成するにあたって、所管課とも連携しながら、引き続き、表記については考えていきたいと思います。","voiceIndex":379,"id":"exchange-164"},{"speaker":"藤原委員","kind":"質問・要望","question":"生活安全担当課長、区民の安心・安全を守っていきましょうと、この場で質問してお願いをしているわけです。今、答弁をいただきました。もしかしたら東京都、警視庁に戻ってしまうかもしれないのですけれども、それでも、ここでの経験を、今度は１,２００万人の東京都民のために、ぜひこの経験を活かしていっていただきたいと思うのですけれども、何かあれば答弁いただけますか。","respondent":"黛生活安全担当課長","answer":"私はこのことを忘れずに、また感謝の気持ちを常に持ちながら、１人の警察官として、首都東京の良好な治安の確保のために全力を尽くしてまいる覚悟です。","voiceIndex":381,"id":"exchange-165"},{"speaker":"藤原委員","kind":"質問","question":"次は、１７５ページの食堂と、あと、職員給与費という意味で、ちょっと前に出ていた職員の方の定年延長、それと役職定年。食堂に関しては、十何年前はプロポーザルに、結構業者が来ていたと思うのですけれども、現状はどうなっているのでしょうか。","respondent":"黒田人事課長","answer":"現在の運営状況ですが、１日の食数として、大体１４０食ぐらいということで、座席数が椅子の数で１２９ありますが、コロナ禍というところで、複数の席については半分の利用というところでいいますと、大体２回転しないような状況です。","voiceIndex":383,"id":"exchange-166"},{"speaker":"藤原委員","kind":"意見","question":"職員の方の定年延長と役職定年はどうなったのか。食堂のことは大事だと思うのですけれども、よろしくお願いします。","respondent":"黒田人事課長","answer":"公務員の定年延長ですが、こちらは令和２年の第２０１回通常国会に、国家公務員および地方公務員の定年年齢を６５歳まで段階的に引き上げて、６０歳で役職を定年とする改正法案が提出されておりましたが、この国会での審議が未了ということで。","voiceIndex":385,"id":"exchange-167"},{"speaker":"藤原委員","kind":"質問","question":"課長、３点、質問したのですけれども、その中で食堂のことが多分、課長の頭の中にがんと入ってしまったと思うのですが、課長ご自身は食堂へ行かれているのですか。質問します。","respondent":"黒田人事課長","answer":"私は、できる限り食堂で昼食を取るようにしております。","voiceIndex":387,"id":"exchange-168"},{"speaker":"藤原委員","kind":"質問","question":"分かりました。お願いします。それと、１７１ページの新年賀詞交歓会を伺います。課長、残念でしたね。去年の委員会で伺ったときに、東京都の指示どおりやっていきますみたいなお話を、たしか答弁でいただいたのですけれども、まず、ぎりぎりまで新年賀詞交歓会をやりますと言っていましたが、本当に直近になって、やらないと。とてもがっかりしたと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"立川総務課長","answer":"１１月の時点で城南地区、５区ありますけれども、品川区だけが実施するということで頑張っておりました。","voiceIndex":389,"id":"exchange-169"},{"speaker":"藤原委員","kind":"質問","question":"そんな申し訳ないなんて、硬いです。本当にがっかりしましたよねと伺ったので、その辺のことを伺いたいのと、毎年大体１月５日に開催されますが、区の行政に関わっている方等が本当に多く来られて、この１年の初めに、こうやって区に協力をしてやっていきましょうという会が、ああいう形で開催できなかった。","respondent":"立川総務課長","answer":"そういった方々に対して、新年の初めに区長・議長がご挨拶いたしまして、今年もご協力をいただきたいということで、毎年お願いする場ですので、そういったことができなかったということに関しましては、区民の皆様に対しても大変申し訳なかったと考えております。","voiceIndex":391,"id":"exchange-170"},{"speaker":"藤原委員","kind":"質問","question":"課長、申し訳なかったという答弁ではなくて、行政にとって多大なマイナスになったのですかという質問なので、その辺について明確にお答えいただけますか。","respondent":"立川総務課長","answer":"新年賀詞交歓会を楽しみに来ていただいている方がかなりいらっしゃるということは聞いているところですので、そういった意味では、モチベーションが低下したのかなとは考えているところです。","voiceIndex":393,"id":"exchange-171"},{"speaker":"藤原委員","kind":"質問","question":"新年賀詞交歓会はやりませんでした。でも、行政はきちんと運営できていますという答弁だと私は感じるのですけれども、そうすると、新年賀詞交歓会がなくても行政はきちんと回りますということを言っているのかなと思うのですけれども、その辺について、いかがでしょうか。","respondent":"立川総務課長","answer":"新年賀詞交歓会を実施することによりまして、区民の皆様に１年間気持ちよく区政に協力していただけるということで、これからも実施していきたいとは考えているところです。","voiceIndex":395,"id":"exchange-172"},{"speaker":"安藤委員","kind":"質問","question":"私からは、１７２ページ、人事管理費に関わって、いわゆる天下りのことと、１８５ページ、歩行喫煙防止推進経費に関わって、大崎駅西口の喫煙所について伺います。天下りについてですが、まず、区職員の定年退職の規定はどうなっているのか伺います。定年後の再任用の規定についても伺います。再任用の場合、待遇面は定年前と比べてどうなるのか、簡単でいいので教えてください。","respondent":"黒田人事課長","answer":"再任用の規定ですが、定年退職等した職員が再任用職員として採用を希望した場合に、欠格事項や分限免職事由に該当すると判断した場合以外は、原則として採用するという制度でございまして、待遇面ですが、再任用職員につきましては。","voiceIndex":398,"id":"exchange-173"},{"speaker":"安藤委員","kind":"質問","question":"定年退職した後、部長・課長・係長経験者で、例えば品川文化振興事業団や福栄会などの、区の関連団体あるいは関連企業に再就職している、いわゆる天下りしている方というのは、現在何人いらっしゃるのか伺います。再就職先の企業・団体名とあわせて、それぞれ何人いらっしゃるのか伺います。","respondent":"黒田人事課長","answer":"そのほかの公益的な法人ですが、社会福祉法人等々合わせまして１０団体ございまして、こちらには管理職のＯＢが８名行っているという状況です。","voiceIndex":400,"id":"exchange-174"},{"speaker":"安藤委員","kind":"質問","question":"先ほどご答弁いただいた数ですけれども、そのうち理事長、常務理事、事務局長、施設長、社長、部長など、役職に就いておられる方はどれぐらいいらっしゃるのか伺います。そうした方の待遇というのは、賞与もあるなど、ほとんど常勤待遇だと思うのですけれども、どうなのでしょうか。伺います。","respondent":"黒田人事課長","answer":"各団体での給与ですが、基本的に、区に問い合わせがありましたら、区の再任用の給与水準をお伝えし、情報提供をしていますが、各企業については、各団体でそれぞれの規定で定めておりますので、こちらで詳細について把握してございません。","voiceIndex":402,"id":"exchange-175"},{"speaker":"安藤委員","kind":"質問","question":"国家公務員については、２００７年に当時の第一次安倍内閣により改悪、骨抜きにされたとはいえ、あっ旋による民間企業への天下りを一定規制するルールがあります。地方公務員にはこのような法規制はあるのか、それともないのか、伺います。あわせて、品川区として独自に天下りに関する自主規定やルール、指針などは設けているのでしょうか、伺います。","respondent":"黒田人事課長","answer":"地方公務員法の規定では、退職した後、営利企業等に再就職した際に、退職前の職場に働きかけるなどの行為について規制する条文がございまして、そちらにつきましては、退職前５年間に在籍した職に関することに、退職後２年間は働きかけをしてはならないという規制がありまして。","voiceIndex":404,"id":"exchange-176"},{"speaker":"安藤委員","kind":"質問","question":"国家公務員については再就職にあたり、公務の公正性に対する国民の信頼を確保するため、再就職依頼や、退職時期や地位などの情報提供などをするあっ旋を禁止と。伺いますけれども、品川区としては現状でも、先ほど答弁されたようにたくさんのＯＢが再就職されているという事実があるのですけれども、このようなあっ旋ですとか、あるいは働きかけというのは行われているのか、それぞれ伺います。","respondent":"黒田人事課長","answer":"基本的に、退職された後にどこで仕事をするかについては、職業選択の自由がありますので、それぞれ個人の自由であろうと考えていますし、元いた職場、仕事への働きかけというのは法律で禁止されていて、刑事罰が科されているですので。","voiceIndex":406,"id":"exchange-177"},{"speaker":"安藤委員","kind":"質問","question":"いわゆるあっ旋です。それは行われているのかを伺いました。今の答弁だとあまり分からなかったので、もう一度伺います。","respondent":"黒田人事課長","answer":"あっ旋ということは行ってございません。","voiceIndex":408,"id":"exchange-178"},{"speaker":"安藤委員","kind":"質問","question":"平成６年の同様の資料には、あっ旋人数だけではなくて、あっ旋された方が事務局長、課長、次長、常務理事何名と、内訳まで書いているのです。伺いますけれども、当時品川区は堂々とあっ旋をして、それを公表していたわけですが、今はあっ旋しないということに方針が変わったということなのでしょうか。変わったなら、いつ、どんな理由でそれを変えたのか伺います。","respondent":"黒田人事課長","answer":"繰り返しになりますが、あっ旋は行ってございませんで、先ほど申し上げたとおり、再任用につきましては、再任用を希望する方が申込みをするという制度ですので、再任用の申込みをしない方がどちらに就職されるかというところは。","voiceIndex":410,"id":"exchange-179"},{"speaker":"安藤委員","kind":"質問","question":"当時の資料としては、あっ旋、計何名と、各団体ごとに書かれていたのですが、これは、当時はしていたということだと思うのです。なぜ変わったのか、その理由を改めて伺いたいと思いますし、当時はやっていたということでよろしいのでしょうか。","respondent":"黒田人事課長","answer":"あっ旋という言葉が、どのような意味で使われたのか分かりませんが、現時点において、いわゆるあっ旋による就職は行っておりません。","voiceIndex":412,"id":"exchange-180"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのですが、いわゆる天下りは、李下に冠を正さずという言葉もありますが、公務の公正性を損なうことになっていないのか、伺いたいと思います。公務の公正性を担保するため、あるいは公益財団法人等の公益性や独立性を担保するために、いわゆる天下りを規制する自主的なルールづくりが必要だと思いますけれども、いかがでしょうか。","respondent":"黒田人事課長","answer":"条例で定めるものについては、給与を地方公共団体で負担してよいということで、ある意味、公益的な団体と地方公共団体が施策の目的を果たすためであれば、地方公共団体が給与を負担して、その団体の職員として専ら仕事させてよいという、そういった法律の規定がある中では。","voiceIndex":414,"id":"exchange-181"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後ともこの問題については、注視していく必要があると考えています。撤去してほしいと。それができないなら、完全な天井までの囲いや風除装置、扉などで、煙を持ち出さないようにしてほしいという声です。大崎駅西口のバスターミナル脇の喫煙所なのですが、早急な撤去もしくは、煙を外と完全に遮断する喫煙施設の整備を求めます。新規事業に助成事業がありましたので、それとあわせて伺います。","respondent":"黛生活安全担当課長","answer":"ただいま委員からご指摘をいただきましたようなご意見は、ほかにも私どもでもいただいているところです。しっかりと受け止めまして、たばこを吸う人、吸わない人が、共に快適に過ごせるまちづくりを進めてまいりたいと考えております。","voiceIndex":416,"id":"exchange-182"},{"speaker":"大沢委員","kind":"質問・要望","question":"初日の補正予算についても、この２０項目、様々な区の財政、お財布のやりくりを痛いほどよく理解したところではありますが、ここのところでしながわ活力応援給付金について、どのように苦労されたのか、工夫されたのか、そしてまた成果と感想について、総括という意味で、今後このような出費も、先の見えない時代だからあろうかと思いますので、そこの４点についてご答弁いただきたい。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"補正予算ということでご審議いただいてから、申請書の発送までに時間がなかった中で、同時並行で動いておりました特別定額給付金の事務としっかり連携をしまして、工夫すべき点、改善すべき点というところを、しっかり連携した上で進めてまいりました。","voiceIndex":420,"id":"exchange-183"},{"speaker":"大沢委員","kind":"質問・要望","question":"これについては、本当に区長の英断、ならびに各部の創意工夫により、このような給付金、議会の総意、これは議会全体で４０人の心を一つにしてお願いしたわけですから、これについて、本当に区長の英断には改めて敬意を表させていただきたいと思います。この予算特別委員会のことでありますが、今日、新型コロナウイルスの感染者数が３０１名とＹＡＨＯＯ！に載っていました。","respondent":"立川総務課長","answer":"昨年からですけれども、委員会運営につきましては、議会の皆様と、またこちらの理事者側で最善を尽くして感染防止対策を施し、実施していると認識しております。","voiceIndex":422,"id":"exchange-184"},{"speaker":"大沢委員","kind":"質問・要望","question":"理事者は、第２委員会室、そして第５委員会室に分散しており、そちらの工夫は重々に分かっておりますけれども、私はこの議会に来ると、理事者の皆さんが、私たちの質問に答えていただくので、入退室がなかなか自由にできない部分があろうかと思いますけれども、ただ、英語で言えば「Ｎａｔｕｒｅ ｃａｌｌｓ ｍｅ」といったら、自然が私を呼んでいるとか、自然現象のことを言うのですけれども。","respondent":"立川総務課長","answer":"理事者側の入退室の取決めですが、特に生理現象について規制しているということはございません。","voiceIndex":424,"id":"exchange-185"},{"speaker":"大沢委員","kind":"質問","question":"それと、先ほど密とお話ししたように、たまには水分を取るなり、緊急事態宣言が解除されれば、私たちも区民の皆様の負託を受けているわけですから、通常の委員会に戻すべきだと思いますけれども、コロナ禍においては、理事者の皆さんにおいても、その辺の自由度をお持ちになったほうがいいのではなかろうか。そこについてどのようにお考えになるのか、総務課長、お願いします。","respondent":"立川総務課長","answer":"理事者側の態度、また考え方といたしましては、委員の皆様に極力失礼がないように、その辺を最重点として運営に携わっているものです。","voiceIndex":426,"id":"exchange-186"},{"speaker":"大沢委員","kind":"質問・要望","question":"お互いに敬意を表しながらだと、遠慮で見合ってしまうので、コロナ禍ではありますので、そこのところはぜひとも、４番目の波、３番目の波ということがあるので、いつ収まるとも限らないので、理事者の皆さんにおかれましては、その辺のところを十分に留意しながら、遠慮をなさらず、区長、副区長、教育長が、目を光らせておりますけれども、コロナ禍ということですので。","respondent":"川島地域活動課長","answer":"こうした駅至近の土地で、窓口開庁時間も増えました。引き続き、地域に根差した地域事務も行いまして、より一層地域の皆様に愛される地域センターを目指しまして、全力で開設準備を進めているところです。","voiceIndex":428,"id":"exchange-187"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと、場所柄多くの方が集まってくるので、ニーズも多かろうと思います。当初に説明を受けましたように、開庁時間とか、いろいろな部分、もっと大きな部分のニーズが今後出てくると思いますので、そこのところの検討をお願いしながら、新しい地域センターづくりに努めていただきたいと思いますけれども、もう一度、決意のほどよろしくお願いいたします。","respondent":"川島地域活動課長","answer":"地域の皆様にも大変期待されている、新しいところに移るという新荏原第一地域センターですので、ご期待に沿えますように、しっかり準備を進めてまいりたいと考えています。","voiceIndex":430,"id":"exchange-188"},{"speaker":"若林委員","kind":"質問・要望","question":"こういう数字がざっと並んで、効果があったのか、なかったのか、見直しがしっかり進められたのかというところを説明いただきたいのですが、数字とか具体的にというと、予算書には節があって、この中には、例えば経常経費に当たる需用費などが、ずっと１節から、多分これは２８節、節があるのですが、この辺でもし説明できれば、その成果・効果についてお聞きしたいと思います。それから、続けます。","respondent":"品川財政課長、佐藤企画調整課長、黛生活安全担当課長","answer":"ただ、今回１０％のマイナスシーリングという形で、歳入が厳しいということを各部、各課、各予算担当職員に。事業評価につながる実施計画の作成については、まず新型コロナウイルス感染症の収束を一定待ちたいと考えています。民間の公共喫煙所への補助ですが、具体的にお話をしますと、設置費用については、１,０００万円を上限に３分の２を、維持管理経費については。","voiceIndex":433,"id":"exchange-189"},{"speaker":"若林委員","kind":"意見","question":"時間がない中、すみませんでした。本村橋の指定喫煙所、それから先ほどもありました大崎駅西口、それから東口の高架下は、決してそういう環境をつくらない、それまでは閉鎖をするという考え方でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":437,"id":"exchange-190"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は１８９ページ、都市型観光についてお伺いいたします。そのときにＪＲ東日本の方に伺ったのが、１日何人を想定されているのですかと。これは必ずあると思っています。こういうところも、もちろん考えていらっしゃると思うのだけれども、この辺のところを、まず最初に何点か伺ったのだけれども、そういうこともやっていらっしゃると思っているのだけれども、この辺の見解を教えていただきたい。","respondent":"古巻文化観光課長","answer":"全てとは言い切れないのですけれども、例えば動画配信とかでいいますと、閲覧数はどれぐらいを見込むという目標値を立てて、どれぐらいの達成率なのか、そういったことを効果測定しながら次の事業につなげていく形で、観光事業を進めているところです。","voiceIndex":439,"id":"exchange-191"},{"speaker":"石田（秀）委員","kind":"提案","question":"どうしてこの話をするかというと、考え方の話ですから、答弁は要らないのだけれども、品川区立環境学習交流施設をやろうと言ったとき、担当の課長も大変ご苦労いただいたと考えていますけれども、まずあれをやると言ったときに、地域でも、いかがなものかみたいな話がちょっとあって、大変ご苦労いただいて、やっとここまで来たので、よく頑張ったなと考えていますけれども、そのとき、戸越公園もあり。","respondent":"佐藤企画調整課長","answer":"今後、全庁的な連携も企画部が中心となって、集客・観光の視点を持った施策の推進について取り組んでいきたいと思います。","voiceIndex":441,"id":"exchange-192"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1130#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":125034,"voices":443}}]);
